	"fmt"
	"os"

	"github.com/aws/aws-lambda-go/events"
	"github.com/aws/aws-lambda-go/lambda"
	"github.com/aws/aws-xray-sdk-go/xray"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/xray"
)

func handleRequest(ctx context.Context, s3event events.S3Event) (string, error) {
	sess := session.Must(session.NewSession(&aws.Config{
		Region: aws.String(os.Getenv("AWS_REGION")),
	}))

	svc := xray.New(sess)

	for _, record := range s3event.Records {
		s3 := record.S3

		segment, _ := xray.BeginSegment(ctx, "S3_Delete")

		_, err := svc.PutTraceSegments(&xray.PutTraceSegmentsInput{
			TraceSegmentDocuments: []*string{
				aws.String(fmt.Sprintf(`{ "id": "%s", "trace_id": "%s", "start_time": %.f, "end_time": %.f, "annotations": { "bucket": "%s", "key": "%s" } }`, segment.TraceID, segment.ParentID, segment.StartTime, segment.EndTime, s3.Bucket.Name, s3.Object.Key)),
			},
		})

		if err != nil {
			fmt.Println("Error", err)
			return "", err
		}

		segment.Close(nil)
	}

	return "Done", nil
}

func main() {
	lambda.Start(handleRequest)
}
```

