	"fmt"
)

func errorParens(lst []string) string {
	counter := 0
	for _, s := range lst {
		for _, c := range s {
			if c == '(' {
				counter++
			} else if c == ')' {
				counter--
			}
			if counter < 0 {
				return "Invalid"
			}
		}
	}
	if counter == 0 {
		return "Valid"
	} else {
		return "Invalid"
	}
}

