import java.math.BigInteger;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;

class DataSource implements Runnable {

    private final BlockingQueue<BigInteger> queue;

    public DataSource(BlockingQueue<BigInteger> queue) {
        this.queue = queue;
    }

    @Override
    public void run() {
        while (true) {
            try {
                BigInteger number = BigInteger.valueOf(ThreadLocalRandom.current().nextInt(1_000_000));
                queue.put(number);
                TimeUnit.MILLISECONDS.sleep(500);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}

class DataProcessor implements Runnable {

    private final BlockingQueue<BigInteger> queue;
    private BigInteger total = BigInteger.ZERO;

    public DataProcessor(BlockingQueue<BigInteger> queue) {
        this.queue = queue;
    }

    @Override
    public void run() {
        while (true) {
            try {
                total = total.add(queue.take());
                System.out.println("Cumulative Total: " + total);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
    }
}

public class MultiThreadedIntegerProcessor {

