        BlockingQueue<BigInteger> queue = new LinkedBlockingQueue<>();

        new Thread(new DataSource(queue)).start();
        new Thread(new DataSource(queue)).start();
        new Thread(new DataSource(queue)).start();
        new Thread(new DataSource(queue)).start();
        new Thread(new DataSource(queue)).start();

        new Thread(new DataProcessor(queue)).start();
    }
}
```

