bool checkUnderflowOverflow(double a, double b) {
    // checking overflow
    if(a > 0 && b < 0 && std::abs(b) > std::numeric_limits<double>::max() - a) {
        std::cout << "Overflow Condition!" << "\n";
        return true;
    }

    // checking underflow 
    double minPositive = std::numeric_limits<double>::min();
    if(a > 0 && b > 0 && a < minPositive && b < minPositive) {
        std::cout << "Underflow Condition!" << "\n";
        return true;
    }

    return false;
}

void computeDifference(double a, double b) {
    if(!checkUnderflowOverflow(a, b)) {
        double result = a - b;
        std::cout << "Difference: " << std::fixed << std::setprecision(10) << result << "\n";
    }
}

