sub reverse_even {
    my ($s) = @_; # retrieve the first argument
    my @even_chars;
    my @odd_chars;
    for (my $i = 0; $i < length $s; $i++) {
        if ($i % 2 == 0) { # Check if index is even
            unshift @even_chars, substr $s, $i, 1; # Push to start of even_chars array
        } else {
            push @odd_chars, substr $s, $i, 1; # Push to end of odd_chars array
        }
    }
    my @result;
    while (@odd_chars) {
        # remove from the start of even_chars array and end of odd_chars array
        push @result, shift @even_chars, pop @odd_chars;
    }
    push @result, @even_chars if @even_chars; # check if even_chars array is not empty

    return join '', @result; # join array elements into a string
}
```

