fn find_max(words: &[&str]) -> &str {
    let mut max_count = 0;
    let mut max_word = "";

    for &word in words {
        let unique_count = count_unique_characters(word);
        if unique_count > max_count {
            max_count = unique_count;
            max_word = word;
        } else if unique_count == max_count && max_word > word {
