// Utility function to check if a given number is prime
fn is_prime(n: i32) -> bool {
    if n <= 1 {
        return false;
    }
    for i in 2..n {
        if n % i == 0 {
            return false;
        }
    }
    return true;
}

// Function to calculate prime factors of a given number
fn prime_factors(n: i32) -> Vec<i32> {
    let mut factors = Vec::new();
    let mut x = n;
    while x % 2 == 0 {
        factors.push(2);
        x /= 2;
    }
    let mut i = 3;
    while i * i <= x {
        while x % i == 0 {
            x /= i;
            factors.push(i);
        }
        i += 2;
    }
    if x > 2 {
        factors.push(x);
    }
    return factors;
}

// Function to calculate weights for a given number
fn compute_weights(n: i32) -> (f64, f64) {
    let factors = prime_factors(n);
    let w1 = factors.iter().map(|x| (f64::from(*x)).powf(1.0/3.0)).sum();
    let w2 = factors.iter().map(|x| (f64::from(*x)).sqrt()).product();
    return (w1, w2);
}

// Function to calculate weighted median with a custom base
fn weighted_median_custom_base(n: i32, m: i32, base: i32, w1: f64, w2: f64) -> Result<String, &'static str> {
    if n > m || w1 > w2 || base < 2 || base > 16 {
        return Err("Invalid inputs");
    }
    let weights: Vec<_> = (n..=m).map(|x| compute_weights(x)).collect();
    let weighted_nums: Vec<f64> = weights.iter().map(|x| x.0 * w1 + x.1 * w2).collect();
    let median = weighted_nums.iter().sum::<f64>() / weighted_nums.len() as f64;
    let median: i32 = median.round().try_into().unwrap();
    return Ok(convert_to_base(median, base));
}

// Function to convert a number from base 10 to the target base
fn convert_to_base(n: i32, base: i32) -> String {
    let chars = "0123456789ABCDEF";
    let mut result = String::new();
    let mut x = n;
    loop {
        let remainder = x % base;
        x /= base;
        result.push(chars.chars().nth(remainder as usize).unwrap());
        if x == 0 {
            break;
        }
    }
    return result.chars().rev().collect::<String>();
}
