```Java
import java.util.HashMap;
import java.util.Map;

public class Student {

    private String fullname;
    private String id;
    private double gpa;
    private HashMap<String, Double> courseCredit;
    private Object lock = new Object();

    public Student(String fullname, String id) {
        this.fullname = fullname;
        this.id = id;
        courseCredit = new HashMap<String, Double>();
    }

    public String getFullname() {
        return fullname;
    }

    public String getId() {
        return id;
    }

    public double getGpa() {
        synchronized (lock) {
            return gpa;
        }
    }

    public Map<String, Double> getCourseCredit() {
        return courseCredit;
    }

    public void addCourse(String course, double credit, double grade) {
        synchronized (lock) {
            courseCredit.put(course, credit);
            updateGpa(grade, credit);
        }
    }

    public void updateCourse(String course, double credit, double grade) {
        synchronized (lock) {
            if(!courseCredit.containsKey(course)){
                System.out.println("Course not found");
                return;
            }
            courseCredit.put(course, credit);
            recalculateGpa();
        }
    }

    private void updateGpa(double grade, double credit) {
        gpa = (gpa * totalCredit() + grade * credit) / (totalCredit() + credit);
    }

    private double totalCredit() {
        return courseCredit.values().stream().reduce(0.0, Double::sum);
    }

    private void recalculateGpa() {
        gpa = courseCredit.entrySet().stream().mapToDouble(e -> e.getValue() * (gpa / totalCredit())).sum();
    }
}
```

In this class, when adding or updating a course, we acquire a lock to ensure thread-safety. In `updateGPA` method, we recalculate the GPA according to the new grade and credit. In `recalculateGpa` method, we traverse through all the courses and calculate the GPA.

