This is a typical problem of computer science and is often solved using AVL trees, which are self-balancing BSTs. Here is a Python code where we first create a Node class to be used as nodes of the tree, then create an AVL tree class where we commit all operations such as insertion, left rotation, right rotation and balancing of the tree itself. 

```python
class Node:
    def __init__(self, val=None):
        self.val = val
        self.left_child = None
        self.right_child = None
        self.height = 1

class AVLTree:
    def insert(self, root, key):
        # Perform normal BST insert
        if not root:
            return Node(key)
        elif key < root.val:
            root.left_child = self.insert(root.left_child, key)
        else:
            root.right_child = self.insert(root.right_child, key)

        # Update the height of the parent node
        root.height = 1 + max(self.get_height(root.left_child),
                              self.get_height(root.right_child))

        # Calculate the balance to check whether this node became unbalanced
        balance = self.get_balance(root)

        # If this node becomes unbalanced, then there are 4 cases

        # Case 1 - Left Left
        if balance > 1 and key < root.left_child.val:
            return self.right_rotate(root)

        # Case 2 - Right Right
        if balance < -1 and key > root.right_child.val:
            return self.left_rotate(root)

        # Case 3 - Left Right
        if balance > 1 and key > root.left_child.val:
            root.left_child = self.left_rotate(root.left_child)
            return self.right_rotate(root)

        # Case 4 - Right Left
        if balance < -1 and key < root.right_child.val:
            root.right_child = self.right_rotate(root.right_child)
            return self.left_rotate(root)

        return root

    def left_rotate(self, z):
        y = z.right_child
        T2 = y.left_child
        y.left_child = z
        z.right_child = T2
        z.height = 1 + max(self.get_height(z.left_child),
                           self.get_height(z.right_child))
        y.height = 1 + max(self.get_height(y.left_child),
                           self.get_height(y.right_child))
        return y

    def right_rotate(self, z):
        y = z.left_child
        T3 = y.right_child
        y.right_child = z
        z.left_child = T3
        z.height = 1 + max(self.get_height(z.left_child),
                           self.get_height(z.right_child))
        y.height = 1 + max(self.get_height(y.left_child),
                           self.get_height(y.right_child))
        return y

    def get_height(self, root):
        if not root:
            return 0
        return root.height

    def get_balance(self, root):
        if not root:
            return 0
        return self.get_height(root.left_child) - self.get_height(root.right_child)


# Driver program to test above function
