```js
class Calculator {
    constructor() {
        this._history = [];
    }

    add(a, b) {
        const result = a + b;
        this.updateHistory('add', arguments, result);
        return result;
    }

    subtract(a, b) {
        const result = a - b;
        this.updateHistory('subtract', arguments, result);
        return result;
    }

    multiply(a, b) {
        const result = a * b;
        this.updateHistory('multiply', arguments, result);
        return result;
    }

    divide(a, b) {
        if (b === 0) throw new Error("Divide by zero error");
        const result = a / b;
        this.updateHistory('divide', arguments, result);
        return result;
    }

    sqrt(a) {
        if (a < 0) throw new Error("Cannot take the square root of a negative number");
        const result = Math.sqrt(a);
        this.updateHistory('sqrt', arguments, result);
        return result;
    }

    power(a, b) {
        const result = Math.pow(a, b);
        this.updateHistory('power', arguments, result);
        return result;
    }

    factorial(a) {
        if (a < 0) throw new Error("Cannot take the factorial of a negative number");
        let result = 1;
        for (let i = 2; i <= a; i++)
            result *= i;
        this.updateHistory('factorial', arguments, result);
        return result;
    }

    updateHistory(operation, operands, result) {
        if (this._history.length == 5)
            this._history.shift();
        this._history.push({operation, operands: Array.from(operands), result});
    }

    get history() {
        return this._history;
    }
}

