function advancedConcurrentCollisionDetector(n, leftLaneAutos, rightLaneAutos) {
    /* 
     * Detects the concurrent collisions between cars in both lanes.
     * Returns a list of objects where each object represents a collision.
     * The first two properties are the index of the collided cars in left and right lanes and the other two properties are the overlapping distance.
     *
     * @param {number} n - Number of automobiles in each lane
     * @param {Array} leftLaneAutos - List of objects indicating the start and end points of automobiles in left lane
     * @param {Array} rightLaneAutos - List of objects indicating the start and end points of automobiles in right lane
     * @return {Array} - A list of objects indicating the collided automobiles and their overlapping distance
     */
    let collisions = [];
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (leftLaneAutos[i].start < rightLaneAutos[j].end && leftLaneAutos[i].end > rightLaneAutos[j].start) {  
                let overlapStart = Math.max(rightLaneAutos[j].start, leftLaneAutos[i].start);
                let overlapEnd = Math.min(rightLaneAutos[j].end, leftLaneAutos[i].end);
                collisions.push({i: i, j: j, overlapStart: overlapStart, overlapEnd: overlapEnd});
            }
        }
    }
    return collisions;
}
