def is_prime(n):
    """Check if number is prime."""
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def longest_sequence(lst):
    """
    Find the longest subsequence in lst that contains 
    both prime and composite numbers.
    """
    best_start, best_end = 0, 0
    count_prime, count_composite = 0, 0
    current_start = 0
    for current_end, num in enumerate(lst):
        if is_prime(num):
            count_prime += 1
        else:
            count_composite += 1
        if count_prime > 0 and count_composite > 0:
            if current_end + 1 - current_start > best_end - best_start:
                best_start, best_end = current_start, current_end + 1
        elif count_prime == 0 or count_composite == 0:
            current_start = current_end + 1
            count_prime, count_composite = 0, 0
    return best_start, best_end - 1

