Here is a simple implementation in Java detailing how to create a doubly linked list, duplicate it, reverse it and perform operations like insert, delete and display on the reversed doubly linked list.

```java
// The Node class to represent node of a doubly linked list
class Node {
    int data;
    Node prev;
    Node next;

    // Constructor to create a new node
    Node(int d) {
        data = d;
        prev = null;
        next = null;
    }
}

// The DoublyLinkedList class containing methods for list operations
class DoublyLinkedList {
    Node head;

    // Inserting a node at the end of the list
    public void insert(int data) {
        Node newNode = new Node(data);
        if (head == null) {
            head = newNode;
        } else {
            Node temp = head;
            while (temp.next != null) {
                temp = temp.next;
            }
            temp.next = newNode;
            newNode.prev = temp;
        }
    }

    // Deleting a node from the list
    public void delete(int data) {
        Node temp = head;
        while (temp != null) {
            if (temp.data == data) {
                if (temp.prev != null) {
                    temp.prev.next = temp.next;
                }
                if (temp.next != null) {
                    temp.next.prev = temp.prev;
                }
            }
            temp = temp.next;
        }
    }

    // Displaying the list
    public void display() {
        Node temp = head;
        while (temp != null) {
            System.out.print(temp.data + " ");
            temp = temp.next;
        }
        System.out.println();
    }

    // Duplicating and reversing the list
    public DoublyLinkedList duplicateAndReverse() {
        DoublyLinkedList newList = new DoublyLinkedList();
        Node temp = head;
        while (temp != null) {
            newList.insert(temp.data);
            temp = temp.next;
        }
        // Reverse list
        Node prev = null;
        Node current = newList.head;
        Node next = null;
        while (current != null) {
            next = current.next;
            current.next = prev;
            current.prev = next;
            prev = current;
            current = next;
        }
        newList.head = prev;
        return newList;
    }
}

public class Main {
    public static void main(String[] args) {
        DoublyLinkedList list = new DoublyLinkedList();
        list.insert(1);
        list.insert(2);
        list.insert(3);
        list.insert(4);
        list.insert(5);
        DoublyLinkedList newList = list.duplicateAndReverse();

        System.out.println("Original list: ");
        list.display();
        System.out.println("Duplicated and reversed list: ");
        newList.display();

        newList.insert(6);
        System.out.println("After inserting 6: ");
        newList.display();

        newList.delete(4);
        System.out.println("After deleting 4: ");
        newList.display();
    }
}
```
