Here is a JavaScript solution that employs a depth-first search algorithm to recursively traverse the object structure and keep track of the frequency of all attribute occurrences.

The solution also uses a JavaScript Map for efficient frequency counting and retrieval of the attribute with the minimum frequency.

```javascript
const countAttributes = (obj, counts) => {
  if (typeof obj !== 'object' || obj === null) return;

  for (const key in obj) {
    counts.has(key) ? counts.set(key, counts.get(key) + 1) : counts.set(key, 1);
    countAttributes(obj[key], counts);
  }
};

const findLeastFrequentAttribute = (obj) => {
  const counts = new Map();
  let leastFreqAttr;
  let minCount = Infinity;

  // Count occurrences of all attribute keys
  countAttributes(obj, counts);

  for (const [key, count] of counts.entries()) {
    if (count < minCount) {
      minCount = count;
      leastFreqAttr = key;
    }
  }

  return leastFreqAttr;
};
```

