import java.util.*;

public class CarRaceCollision {

    public class Car {
        double collisionTime;
        double leftPosition;
        double rightPosition;

        public Car(double collisionTime, double leftPosition, double rightPosition) {
            this.collisionTime = collisionTime;
            this.leftPosition = leftPosition;
            this.rightPosition = rightPosition;
        }
    }

    public List<Tuple<Integer, Double>> carRaceCollision(int n, List<Tuple<Double, Double>> leftCars, List<Tuple<Double, Double>> rightCars){
        List<Car> allCars = new ArrayList<>();
        for(int i = 0; i < n; i++){
            Tuple<Double, Double> leftCar = leftCars.get(i);
            Tuple<Double, Double> rightCar = rightCars.get(i);

            // calculate collision time for each pair of car
            double collisionTime = Math.abs(rightCar.y - leftCar.y) / (leftCar.x + rightCar.x);
            allCars.add(new Car(collisionTime, leftCar.y, rightCar.y));
        }

        // sort by collision time
        allCars.sort(Comparator.comparingDouble(car -> car.collisionTime));

        int totalCollision = 0;
        List<Tuple<Integer, Double>> events = new ArrayList<>();

        for(int i = 0; i < allCars.size(); i++){
            Car car = allCars.get(i);

            // check duplicate collisions
            if(i > 0 && Math.abs(car.collisionTime - allCars.get(i - 1).collisionTime) < 1e-6){
                continue;
            }

            // find the cars involved in the collision
            List<Car> collidedCars = new ArrayList<>();
            for(Car c : allCars){
                if(Math.abs(c.collisionTime - car.collisionTime) < 1e-6){
                    collidedCars.add(c);
                }
            }

            // check if they are still in motion
            for(Car c : collidedCars){
                if(c.leftPosition >= car.leftPosition && c.rightPosition <= car.rightPosition){
                    totalCollision+=1;
                    events.add(new Tuple<>(totalCollision, car.collisionTime));
                }
            }
        }

        return events;
    }

    public class Tuple<X, Y> {
        public final X x;
        public final Y y;

        public Tuple(X x, Y y) {
            this.x = x;
            this.y = y;
        }
    }
}
