double weightedAverage(std::vector<int> &nums, std::vector<double> &weights) {
  // Edge Case: Arrays of Different Lengths
  if(nums.size() != weights.size()) {
    std::cerr << "Error: Arrays of different lengths!\n";
    return 0.0;
  }

  double sum = 0.0;
  double weightSum = 0.0;

