import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter a credit card number as a long integer: ");
        long number = scanner.nextLong();

        if (isValidCreditCard(number))
            System.out.println(number + " is a valid credit card number.");
        else
            System.out.println(number + " is an invalid credit card number.");
    }

    static boolean isValidCreditCard(long number) {
        return (getSize(number) >= 13 && getSize(number) <= 16) &&
                (prefixMatched(number, 4) || prefixMatched(number, 5) || prefixMatched(number, 37) || prefixMatched(number, 6)) &&
                ((sumOfDoubleEvenPlace(number) + sumOfOddPlace(number)) % 10 == 0);
    }

    static int sumOfDoubleEvenPlace(long number) {
        int sum = 0;
        long temp = number;
        while (temp > 0) {
            temp = temp / 10;
            int digit = (int)((temp % 10) * 2);
            sum += getDigit(digit);
            temp = temp / 10;
        }
        return sum;
    }

    static int getDigit(int number) {
        if (number < 10)
            return number;
        else
            return (number / 10) + (number % 10);
    }

    static int sumOfOddPlace(long number) {
        int sum = 0;
        while (number > 0) {
            int digit = (int)(number % 10);
            sum += digit;
            number = number / 100;
        }
        return sum;
    }

    static boolean prefixMatched(long number, int d) {
        return getPrefix(number, getSize(d)) == d;
    }

    static int getSize(long d) {
        int size = 0;
        while (d > 0) {
            d = d / 10;
            size++;
        }
        return size;
    }

    static long getPrefix(long number, int k) {
        long result = number;
        for (int i = 0; i < getSize(number) - k; i++)
            result = result / 10;
        return result;
    }
}
```

