Here is a Python solution for a doubly linked list:

```python
class Node:
    def __init__(self, data=None):
        self.data = data
        self.next = None
        self.prev = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None

    # Adding data elements
    def append(self, data):
        if not self.head:
            self.head = Node(data)
        else:
            new_node = Node(data)
            cur_node = self.head
            while cur_node.next:
                cur_node = cur_node.next
            cur_node.next = new_node
            new_node.prev = cur_node

    # Removing data elements
    def remove(self, data):
        cur_node = self.head
        while cur_node:
            if cur_node.data == data:
                if cur_node.next:
                    cur_node.prev.next = cur_node.next
                    cur_node.next.prev = cur_node.prev
                else:
                    cur_node.prev.next = None
                return
            cur_node = cur_node.next

    # Printing the Doubly Linked List
    def display(self):
        cur_node = self.head
        while cur_node:
            print(cur_node.data, end = ' ')
            cur_node = cur_node.next

