def process_numbers(numbers):
    def get_divisors(n):
        i = 1
        divisors = []
        while i*i < n:
            if n % i:
                divisors.extend([i, n//i])
            i += 1
        if i*i == n:
            divisors.append(i)
        return divisors

    def get_lcm_hcf(nums):
        def gcd(x, y):
            while(y):
                x, y = y, x % y
            return x
        nums = set(nums)
        lcm = nums.pop()
        hcf = lcm
        for num in nums:
            hcf = gcd(hcf, num)
            lcm = lcm*num//gcd(lcm, num)
        return hcf, lcm

    results = {}
    for number in numbers:
        try:
            num = float(number)
        except:
            results[number] = ("Invalid input", [], None, None, (None, None))
            continue
        num = round(num)
        divisors = sorted(get_divisors(num))
        odd_divisors = len(divisors) % 2 == 1
        product = 1 if divisors else 0
        composite = None
        for divisor in divisors:
            product *= divisor
            if divisor > 1 and not composite and len(get_divisors(divisor)) > 2:
                composite = divisor
        hcf, lcm = get_lcm_hcf(divisors) if divisors else (None, None)
        results[number] = (odd_divisors, divisors, product, composite, (hcf, lcm))
    return results
```  

