use std::cmp::Ordering;

fn binary_search(numbers: &Vec<i32>, low: usize, high: usize, num: i32) -> bool {
    if high >= low {
        let mid = (high + low) / 2;
        match numbers[mid].cmp(&num) {
            Ordering::Equal => true,
            Ordering::Greater => binary_search(numbers, low, mid - 1, num),
            Ordering::Less => binary_search(numbers, mid + 1, high, num),
        }
    } else {
