#include <vector>
#include <algorithm>
#include <random>

int main() {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 100);
    std::vector<int> seq(20);

    for(int i=0; i<20; i++)
        seq[i] = dis(gen);

    std::sort(seq.begin(), seq.end());

    for(int val : seq)
