In Perl, you can express the above code as follows:

```
sub partition {
    # The '_@' symbol is an array that contains all the arguments passed to the subroutine
    my (@arr) = @_;
    my $pivot = $arr[0];
    # Perl has an inbuilt function 'grep' similar to Python's 'list comprehension'
    my @left = grep { $_ < $pivot } @arr[1..$#arr];
    my @middle = grep { $_ == $pivot } @arr;
    my @right = grep { $_ > $pivot } @arr[1..$#arr];
    # Return references to these arrays instead of arrays themselves
    return \@left, \@middle, \@right;
}

sub quick_sort {
    my (@arr) = @_;

    return @arr if @arr == 0;

    my ($left, $middle, $right) = partition(@arr);
    # De-reference the array references
    return (quick_sort(@$left), @$middle, quick_sort(@$right));
}

sub shared_elements {
    my (@list1, @list2) = @_;
    my @common = ();
    my @sorted1 = quick_sort(@list1);
    my @sorted2 = quick_sort(@list2);

    my $i = 0;
    my $j = 0;

    while ($i < @sorted1 and $j < @sorted2) {
        # Perl doesn't support Python's sequence comparison, but comparing scalar values is straightforward
        if ($sorted1[$i] == $sorted2[$j]) {
            # To check if the last element in common is the same as current, the negative indices start from -1 in Perl
            if (@common == 0 or $common[-1] != $sorted1[$i]) {
                # 'push' appends elements at the end of the list
                push @common, $sorted1[$i];
            }
            $i++;
            $j++;
        }
        elsif ($sorted1[$i] < $sorted2[$j]) {
            $i++;
        }
        else {
            $j++;
        }
    }
    return @common;
}
```

