```python
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def prime_index_elements(lst):
    unique_prime_elements = {}
    for i in range(len(lst)):
        if is_prime(i) and lst[i] >= 0:
            if lst[i] not in unique_prime_elements:
                unique_prime_elements[lst[i]] = [i]
            else:
                unique_prime_elements[lst[i]].append(i)
    return dict(sorted(unique_prime_elements.items()))

