            var h1Tags = document.getElementsByTagName('h1'); // get all h1 tags
            var startColor = getRandomColor(); // get random start color
            var endColor = getRandomColor();  // get random end color
            var step = 1 / h1Tags.length;

            for(let i=0; i< h1Tags.length; i++){
                var color = interpolateColor(startColor, endColor, step * i);
                h1Tags[i].style.color = color;
            }

        function getRandomColor() {
            var letters = '0123456789ABCDEF';
            var color = '#';
            for (var i = 0; i < 6; i++) {
                color += letters[Math.floor(Math.random() * 16)];
            }
            return color;
        }

        function interpolateColor(startColor, endColor, step) {
            var colorArray = startColor.slice(1).match(/.{2}/g);  
            var percent = 1 - step;
            var newColor = colorArray.map(function (el) {
            el =  parseInt(el, 16);
            return ("0" + Math.round((parseInt(endColor.slice(1), 16) -  el) * percent + el).toString(16)).slice(-2);
            });
            return "#" + newColor.join("");
        }
       }
