Sure, here's an example of a simple C++ program that solves this problem. This program uses the Sieve of Eratosthenes algorithm for generating prime numbers up to 'n' in a highly efficient manner, and then checks if 'n' is prime or not. If 'n' is not prime, it then extends the sequence up to next prime number.

This is a efficient way of checking for prime numbers due to the properties of The Sieve of Eratosthenes algorithm. 

```cpp
#include<bits/stdc++.h> 
using namespace std;

vector<bool> prime;

void SieveOfEratosthenes(int n){
    prime = vector<bool>(n+1, true);
    prime[0] = prime[1] = false;
    for (int p=2; p*p<=n; p++) {
        if (prime[p] == true) {
            for (int i=p*p; i<=n; i += p)
                prime[i] = false;
        }
    }
}

int nextPrime(int N) {
    if (N <= 1)
        return 2;
    int prime = N;
    bool found = false;

    while (!found) {
        prime++;

        if(prime[N + 1] == true)
            found = true;

        if ((prime % 2 == 0) || (prime % 3 == 0))
            found = false;

        for (int i = 5; i * i <= prime; i = i + 6) {
            if ((prime % i == 0) || (prime % (i + 2) == 0))
                found = false;
        }
    }

    return prime;
}

int main() {
    int n = 100;
    SieveOfEratosthenes(n);

    cout << "Prime numbers upto " << n << " are: ";
    for(int p = 2; p <= n; p++)
       if (prime[p])
          cout << p << " ";

    if (prime[n] == false) {
        int next = nextPrime(n);
        cout << "Next prime is " << next;
    }

    return 0;
}
```

The first function SieveOfEratosthenes is used to generate prime numbers up to 'n'. 

nextPrime function is used to find the next prime after 'n'. 

In the main function, we first generate prime numbers up to 'n'. If 'n' is not a prime, we then get the next prime after 'n'.

