```Go
package main

import (
	"log"
	"sync"
	"time"

	"github.com/emicklei/go-restful"
	stomp "github.com/go-stomp/stomp"
	mgo "gopkg.in/mgo.v2"
	bson "gopkg.in/mgo.v2/bson"
)

type DataItem struct {
	ID       bson.ObjectId `bson:"_id,omitempty"`
	Timestamp time.Time    `bson:"timestamp"`
	Data     string        `bson:"data"`
}

var conn *stomp.Conn
var db *mgo.Database

func main() {
	InitializeStomp()
	InitializeMongoDB()

	ws := new(restful.WebService)
	ws.Route(ws.GET("/data").To(GetData))

	restful.Add(ws)

	log.Fatal(restful.ListenAndServe(":8080"))
}

func InitializeStomp() {
	opts := stomp.Options{
		HeartBeatError: 180 * time.Second,
		DropCount:      50,
	}

	conn, _ = stomp.Dial("tcp", "localhost:61613", opts)

	sub, _ := conn.Subscribe("/queue/test", stomp.AckAuto)

	var wg sync.WaitGroup
	wg.Add(1)

	go func() {
		defer wg.Done()
		for message := range sub.C {
			data := string(message.Body)
			if data != "" {
				item := &DataItem{
					Timestamp: time.Now(),
					Data:      data,
				}
				db.C("collection").Insert(item)
			}
		}
	}()

	wg.Wait()
}

func InitializeMongoDB() {
	session, _ := mgo.Dial("localhost")
	db = session.DB("stompDB")
}

func GetData(request *restful.Request, response *restful.Response) {
	var results []DataItem
	err := db.C("collection").Find(nil).Sort("-timestamp").All(&results)
	if err != nil {
		log.Fatal(err)
	}

	response.WriteEntity(results)
}
```
In this architecture, we consume the STOMP messages into a Go consuming service and store the messages in MongoDB, a NoSQL DB. We accommodate a network latency by setting `HeartBeatError` which defines the duration to tolerate with no network activity before closing the connection. The `DropCount` is used to drop the message if it's going to exceed our buffer size. This feature will avoid data duplication.

In addition, the self-learning behavior added by MongoDB’s WiredTiger storage engine’s capability to automatically select an optimal data compression method for each collection and index. This not only saves storage space but also enhances the performance of read/write operations.

The `GetData` API endpoint provides a way to retrieve the data from the service. It's sorted by timestamp, showing the latest received messages first.

