The given program is actually a simple divisor finding program, which doesn't cater to prime factorization. Therefore, we have to substantially modify it to achieve our required task. Here is a proposed solution in C++:

```cpp
#include <iostream>
#include <map>
using namespace std;

int main() {
    int num;
    cout << "Enter Number: ";
    cin >> num;

    // Using a map to hold prime factors and their counts.
    map<int, int> factors;

    // Determine the count of 2 as a prime factor.
    while(num % 2 == 0) {
        factors[2]++;
        num /= 2;
    }

    // Now num must be odd so a skip of 2 can be used.
    for(int i = 3; i * i <= num; i += 2) {
        // while i divides num, count i and divide num.
        while(num % i == 0) {
            factors[i]++;
            num /= i;
        }
    }

    // This condition is to handle the case when num is a prime number
    // greater than 2.
    if(num > 2)
        factors[num]++;

    // Printing the factors and their counts.
    for(auto i: factors) {
        cout << i.first << '^' << i.second;
        // To not print the comma at the end.
        if(i.first != (--factors.end())->first) 
            cout << ", ";
    }
    return 0;
}
```

