class AddressBook:
    def __init__(self):
        self.__addressBook = {}

    def add(self, username, address):
        try:
            self.__addressBook[username] = address
            return f'Address added for {username}'
        except Exception as e:
            return str(e)

    def update(self, username, newAddress):
        try:
            if username in self.__addressBook:
                self.__addressBook[username] = newAddress
                return f'Address updated for {username}'
            else:
                return 'User not found'
        except Exception as e:
            return str(e)

    def remove(self, username):
        try:
            if username in self.__addressBook:
                del self.__addressBook[username]
                return f'Address deleted for {username}'
            else:
                return 'User not found'
        except Exception as e:
            return str(e)

    def get_address(self, username):
        try:
            if username in self.__addressBook:
                return self.__addressBook[username]
            else:
                return 'User not found'
        except Exception as e:
            return str(e)


