#include <string>
#include <cctype>
#include <cstdlib>

std::string modifyString(std::string text, int shiftCount, bool changeCase) {
  std::string result = "";

  for (int i = 0; i < text.length(); i++) {
    char character = text[i];

    if (isdigit(character)) continue; // Ignore digits.

    int newCharCode = character + shiftCount;
    if (character >= 'A' && character <= 'Z') { // Check if character is uppercase.
      if (newCharCode > 'Z') newCharCode -= 26;
      if (newCharCode < 'A') newCharCode += 26;
    } else if (character >= 'a' && character <= 'z') { // Check if character is lowercase.
      if (newCharCode > 'z') newCharCode -= 26;
      if (newCharCode < 'a') newCharCode += 26;
    } else {
      // If it's not a alphabetic character or a digit, it's bad input.
      std::cout << "Bad input: input can consist of only letters and digits." << std::endl;
      exit(1);
   }

    char shiftedChar = newCharCode;
    result += changeCase ? toupper(shiftedChar) : tolower(shiftedChar);
  }

  return result;
}
```

Here we used the `isdigit` function that returns `true` if the character is a digit. The `toupper` and `tolower` functions allow you to convert a character to lowercase or uppercase respectively. The `exit(1)` function terminates the program with a status code of `1`, generally indicating an error.

