func uniqueBSTSort(_ arr: [Double]) -> [Double] {
    var arr = arr.sorted()
    var result = [Double]()

    while !arr.isEmpty {
        // Remove the smallest value and append it to the result array
        result.append(arr.removeFirst())

        // If there are values remaining, remove the largest value and append it to the result array
        if !arr.isEmpty {
            result.append(arr.removeLast())
        }
    }
    return result
}
