    vector<vector<long long>> dp(H+1,vector<long long>(W+1,0));
    long long ans=INT_MAX;

    for(long long i=1;i<=H;i++)
    {
        for(long long j=1;j<=W;j++)
        {
            // Calculating prefix sum
            dp[i][j] = nums[i-1][j-1]+dp[i-1][j]+dp[i][j-1]-dp[i-1][j-1];
            // Now for each (i,j) we find the minimum submatrix sum.
            for(long long h=0;h<i;h++)
            {
                for(long long w=0;w<j;w++)
                {
                    ans = min(ans,dp[i][j]-dp[h][j]-dp[i][w]+dp[h][w]);
                }
            }
        }
    }
    //Returning the minimum sum of sub-matrix
    return ans;
} 

int main() 
{
    vector<vector<long long>> nums = {{2, 3, 4}, {1, 2, 4}, {-1, -1, -1}};
    printf("%lld\n", minSubMatrixSum(nums)); //prints -3
    nums = {{-1, -2, -3}, {-4, -5, -6}};
    printf("%lld\n", minSubMatrixSum(nums)); //prints -21
    return 0; 
} 
