Python's built-in eval() function can be used to evaluate complex mathematical expressions. However, for tackling the problem in a programming way, here is an algorithm that achieves the solution using a stack for handling the tokenizing and parsing. It also handles decimals and negative numbers.
```
import re

def evaluate(expression):
    def apply_op(op, b, a):
        if op=='+': 
            return a + b
        elif op=='-': 
            return a - b
        elif op=='*': 
            return a * b
        elif op=='^': 
            return a ** b
        else:  # operator is '/'
            return a / b

    def precedence(op):
        if op=='+' or op=='-':
            return 1
        if op=='*' or op=='/':
            return 2
        if op=='^':
            return 3
        return 0

    data = []
    ops = []
    expression = re.split("([^0-9.])", expression.replace(" ", ""))
    for x in expression:
        if x.isdigit() or "." in x:
            data.append(float(x))
        elif x=="(":
            ops.append(x)
        elif x==")":
            while ops[-1] != "(":
                data.append(apply_op(ops.pop(), data.pop(), data.pop()))
            ops.pop()  # Remove '('
        else:
            while (len(ops) != 0 and 
                   precedence(x) <= precedence(ops[-1])):
                data.append(apply_op(ops.pop(), data.pop(), data.pop()))
            ops.append(x)

    while len(ops) != 0:
        data.append(apply_op(ops.pop(), data.pop(), data.pop()))

    return data[0]
```
Per your problem, consider the following examples:

```
print(evaluate("2*(3+4)"))  # Returns: 14.0
print(evaluate("2.0+(2.1*3) - (4*(5-3)^2)"))  # Returns: -4.2
-print(evaluate("2.0+(-2.1*-3) - (4*(5-(-3))^2)"))  # Returns: -117.7
```
