```python
class Node:
    def __init__(self, key, value):
        self.key = key
        self.value = value
        self.next = None

class HashTable:
    def __init__(self, capacity=4):
        self.capacity = capacity
        self.size = 0
        self.buckets = [None]*self.capacity

    def hash_function(self, key):
        return hash(key) % self.capacity

    def insert(self, key, value):
        self.size += 1
        index = self.hash_function(key)
        node = self.buckets[index]
        if node is None:
            self.buckets[index] = Node(key,value)
            return
        prev = node
        while node is not None:
            prev = node
            node = node.next
        prev.next = Node(key, value)

    def find(self, key): 
        index = self.hash_function(key)
        node = self.buckets[index]
        while node != None and node.key != key:
            node = node.next
        if node is None:
            return None
        else:
            return node.value

    def remove(self, key):
        index = self.hash_function(key)
        node = self.buckets[index]
        prev = None
        while node != None and node.key != key:
            prev = node
            node = node.next
        if node == None:
            return None
        else:
            self.size -= 1
            result = node.value
            if prev == None:
                self.buckets[index] = node.next
            else:
                prev.next = node.next 
            return result

