        self.stdscr = stdscr
        self.level_generator = Level()
        self.is_paused = False

    def start(self):
        self.invaders = self.level_generator.generate_invaders(self.level)

    def pause(self):
        self.is_paused = True

    def resume(self):
        self.is_paused = False

    def end(self):
        pass

    def update(self, key):
        if self.is_paused:
            if key == ord('p'):
                self.resume()
            return

        if key == ord('q'):
            self.end()
        elif key == ord('p'):
            self.pause()
        elif key == ord('a'):
            self.spaceship.move('left')
        elif key == ord('d'):
            self.spaceship.move('right')
        elif key == ord(' '):
            bullet = self.spaceship.shoot()
            self.check_collision(bullet)

        for invader in self.invaders:
            bullet = invader.shoot()
            self.check_collision(bullet)
            invader.move()

        self.check_game_over()

    def draw(self):
        self.stdscr.clear()
        self.stdscr.addstr(0, 0, f'Score: {self.score} Level: {self.level}')
        self.spaceship.draw(self.stdscr)
        for invader in self.invaders:
            invader.draw(self.stdscr)
        self.stdscr.refresh()

    def check_collision(self, bullet):
        for invader in self.invaders:
            if bullet.x == invader.x and bullet.y == invader.y:
                self.invaders.remove(invader)
                self.score += 1

    def check_game_over(self):
        for invader in self.invaders:
            if invader.y >= self.spaceship.y:
                self.end()

    def is_over(self):
        return self.is_paused
