     * to two decimal places.
     *
     * @param  array $operations
     * @param  array $fees
     * @return array
     */
function account_balance(array $operations, array $fees): array
{
    // Init balance
    $balance = 0;

    // Loop over operations
    foreach ($operations as $index => $operation) {
        // Calculate balance, note that we use $fees[$index] to get the fee associated with each operation
        $balance = round($balance + $operation - $fees[$index], 2);

        // If balance is less than zero return the status and the point where it went below zero
        if ($balance < 0) {
