from django.contrib.auth import BACKEND_SESSION_KEY
from default_auth_backend import DefaultAuthBackend

def abac_permission_required(required_attributes):
    """
    Decorator to check Attribute Based Access Control (ABAC).
    """

    def decorator(view):
        @functools.wraps(view)
        def wrapped_view(request, *args, **kwargs):
            # Consider the user data including attributes
            user = request.user

            # Use defined policy to check user attributes
            if not any(attr in user.attributes for attr in required_attributes):
                return HttpResponseForbidden()

            return view(request, *args, **kwargs)

        return wrapped_view
    return decorator


class ABACBackend(DefaultAuthBackend):
    """
    ABAC Backend for checking permissions.
    """
    def authenticate(self, request, username=None, password=None):
        try:
            # using default Django authentication
            user =  User.objects.get(username=username)
            user.attributes = get_user_attributes(user)  # Your function to get user attributes

