    def __init__(self):
        self.ranges = []

    def _bounds(self, left, right):
        i = bisect.bisect_left(self.ranges, left)
        j = bisect.bisect_right(self.ranges, right)
        return i, j

    def addRange(self, left, right, step):
        def update(i, j):
            if i % 2 == 0:
                if j % 2 == 0 and right > left:
                    self.ranges[i:j] = [left, right]
                elif j % 2 == 1:
                    self.ranges[i:j] = [left]
            elif j % 2 == 0:
                self.ranges[i:j] = []
            else:
                self.ranges[i:j] = [right]

        i, j = self._bounds(left, right)
        update(i, j)
        while i < len(self.ranges) and right > self.ranges[i]:
            old_right = self.ranges[i]
            del self.ranges[i]
            _, j = self._bounds(old_right+step, right)
            update(i, j)

    def queryRange(self, left, right):
        i, j = self._bounds(left, right)
        return i == j and i % 2 == 1

    def removeRange(self, left, right):
        def update(i, j):
            if i % 2 == 1:
                if j % 2 == 1 and right > left:
                    self.ranges[i:j] = [left, right]
                elif j % 2 == 0:
                    self.ranges[i:j] = [left]
            elif j % 2 == 1:
                self.ranges[i:j] = []
            else:
                self.ranges[i:j] = [right]

        i, j = self._bounds(left, right)
        update(i, j)
        while i < len(self.ranges) and right > self.ranges[i]:
            old_right = self.ranges[i]
            del self.ranges[i]
            _, j = self._bounds(old_right+1, right)
            update(i, j)

    def getRangeCount(self):
        return sum(self.ranges[i]-self.ranges[i-1] for i in range(1, len(self.ranges), 2))
```

