```python
def subsetSum(set, sum):
    n = len(set)
    dp = [False]*(sum+1)
    dp[0] = True  

    res = []

    for i in range(0, n):
        for j in range(sum, set[i]-1, -1):
            if dp[j-set[i]] or j == set[i]:
                dp[j] = True

                if j == sum:
                    res.append(set[i])

                    while sum != 0:
                        sum -= set[i]
                        if dp[sum]:
                            res.append(sum)

                        else:
                            for k in range(i-1, -1, -1):
                                if dp[sum+set[i]-set[k]]:
                                    res.remove(set[i])
                                    res.append(set[k])
                                    sum = sum+set[i]-set[k]   
                                break
                    return res 

    if dp[sum] == False:
        return []
```  

