Here's a Python solution and step by step explanation on how to execute an AVL Tree's rotation procedures:

1. Node Insertion: First we need to insert the node and later will take care of the balancing of the tree.
2. Tree Balancing: After insertion, we need to check the balance of the tree, for which we calculate the balance factor for each node starting from the newly inserted node up to the root node (reason for starting from the bottom is that the tree balance is affected upwards from the point of insertion). If the Absolute(balance factor) > 1, the tree is unbalanced and requires a rotation. Based on where the imbalance occurs, we do rotations.

```python
class Node:
    def __init__(self, key):
        self.key  = key
        self.left   = None
        self.right  = None
        self.height = 1

class AVL_Tree:
    def get_height(self, root):
        if not root:
            return 0
        return root.height

    def get_balance(self, root):
        if not root:
            return 0
        return self.get_height(root.left) - self.get_height(root.right)

    def get_max(self, root1, root2):
        return max(root1, root2)

    #              y                               x
    #            /  \                            /   \ 
    #           x    T3   Right Rotation       T1   y 
    #         /  \      - - - - - - - >            /  \ 
    #        T1  T2                             T2   T3
    def right_rotation(self, y):
        x = y.left
        T2 = x.right
        x.right = y
        y.left = T2
        y.height = 1 + self.get_max(self.get_height(y.left), self.get_height(y.right))
        x.height = 1 + self.get_max(self.get_height(x.left), self.get_height(x.right))
        return x

    #       x                              y
    #     /  \                           /   \
    #    T1   y     Left Rotation      x     T3
    #        /  \   - - - - - - - >   / \
    #      T2   T3                   T1 T2
    def left_rotation(self, x):
        y = x.right
        T2 = y.left
        y.left = x
        x.right = T2
        x.height = 1 + self.get_max(self.get_height(x.left), self.get_height(x.right))
        y.height = 1 + self.get_max(self.get_height(y.left), self.get_height(y.right))
        return y

    def insert_node(self, root, key): 
        if not root: 
