    function Shape(id, points, color, gradient, opacity) {
        this.id = id;
        this.points = points;
        this.color = color;
        this.gradient = gradient;
        this.opacity = opacity;
        this.element = document.createElementNS("http://www.w3.org/2000/svg", "polygon");
        this.element.setAttribute("id", this.id);
        this.element.setAttribute("points", this.points);
        this.element.setAttribute("fill", this.gradient);
        this.element.style.opacity = this.opacity;
        shapes.push(this);
    }

    Shape.prototype.changeColor = function (color, gradient) {
        this.color = color;
        this.gradient = gradient;
        this.element.setAttribute("fill", this.gradient);
    }

    Shape.prototype.changeOpacity = function (opacity) {
        this.opacity = opacity;
        this.element.style.opacity = this.opacity;
    }

    function createShape(id, points, color, gradient, opacity) {
        return new Shape(id, points, color, gradient, opacity);
    }

    function getShape(id) {
        return shapes.find(function (shape) {
            return shape.id === id;
        });
    }

    function deleteShape(id) {
        var shape = getShape(id);
        shapes.splice(shapes.indexOf(shape), 1);
        shape.element.parentNode.removeChild(shape.element);
    }

    function moveShape(id, newIndex) {
        var shape = getShape(id);
        var oldIndex = shapes.indexOf(shape);
        shapes.splice(oldIndex, 1);
        shapes.splice(newIndex, 0, shape);
    }

    function saveShapes() {
        var saveData = shapes.map(function (shape) {
            return {
                id: shape.id,
                points: shape.points,
                color: shape.color,
                gradient: shape.gradient,
                opacity: shape.opacity
            }
        });

        return JSON.stringify(saveData);
    }

    function loadShapes(savedData) {
        var data = JSON.parse(savedData);
        data.forEach(function (shapeData) {
            createShape(shapeData.id, shapeData.points, shapeData.color, shapeData.gradient, shapeData.opacity);
        })
    }

    return {
        createShape: createShape,
        deleteShape: deleteShape,
        moveShape: moveShape,
        saveShapes: saveShapes,
        loadShapes: loadShapes
    }
})();
