        my $binary_fractional_part = '.';

        while ($fractional_part > 0) {
            $fractional_part *= 2;
            my $bit = int($fractional_part);
            if ($bit == 1) {
                $fractional_part -= $bit;
                $binary_fractional_part .= '1';
            } else {
                $binary_fractional_part .= '0';
            }
        }
        return $prefix . $binary_integer_part . $binary_fractional_part;
    } else {
        return $prefix . sprintf("%b", int($x));
    }
}
```
