class PriorityQueue {
    constructor() {
        this.collection = [];
    }

    enqueue(element){
        if (this.isEmpty()){ 
            this.collection.push(element);
        } else {
            let added = false;
            for (let i = 0; i < this.collection.length; i++){
                 if (element[1] < this.collection[i][1]){ 
                    this.collection.splice(i, 0, element);
                    added = true;
                    break;
                 }
            }
            if (!added){
                this.collection.push(element);
            }
        }
    };

    dequeue() {
        return this.collection.shift();
    };

    isEmpty() {
        return (this.collection.length === 0) 
    };
}

function shortestPath(graph, start, end) {
    let distances = {};
    let prev = {}
    let pq = new PriorityQueue();
    distances[start] = 0;
    pq.enqueue([start, 0]);
    let nodes = Object.values(graph);

    while(!pq.isEmpty()) {
        let shortestDistanceNode = pq.dequeue();
        let currentNode = shortestDistanceNode[0];

        if(currentNode === end) {
            let path = end;
            let parent = prev[end];
            while(parent) {
                path = parent + ' -> ' + path;
                parent = prev[parent];
            }
            return path;
        }

        if(!distances[currentNode]) distances[currentNode] = Infinity;

        for(let neighbor in graph[currentNode]) {
            let distanceToNeighbor = graph[currentNode][neighbor];
            let totalDistance = distances[currentNode] + distanceToNeighbor;

            if(totalDistance < distances[neighbor] || !distances[neighbor]) {
                distances[neighbor] = totalDistance;
                prev[neighbor] = currentNode;
                pq.enqueue([neighbor, totalDistance]);
            }
        }
    }
}
