class AwsAurora {
public:
    AwsAurora(std::string host, std::string database,
              std::string user, std::string password)
        : host_(host), database_(database), user_(user), password_(password) {
        CreatePool();
    }

    // Destructor to clean up connections
    ~AwsAurora() {
        PQfinish(conn_);
    }

    void Query(std::string query_str) {
        PGresult *res = PQexec(conn_, query_str.c_str());
        if (PQresultStatus(res) != PGRES_TUPLES_OK) {
            throw std::runtime_error(PQerrorMessage(conn_));
        }
        // Retrieve result here..
        PQclear(res);
    }

    void Update(std::string update_str) {
        PGresult *res = PQexec(conn_, update_str.c_str());
        if (PQresultStatus(res) != PGRES_COMMAND_OK) {
            throw std::runtime_error(PQerrorMessage(conn_));
        }
        PQclear(res);
    }

    void HandleRequests(std::vector<std::string> requests) {
        pthread_t threads[requests.size()];
        int i = 0;
        for (auto &request : requests) {
            if (request.find("query") != std::string::npos) {
                // Create thread for Query operation
                pthread_create(&threads[i], nullptr, &AwsAurora::Query, (void *)&request);
            } else {
                // Create thread for Update operation
                pthread_create(&threads[i], nullptr, &AwsAurora::Update, (void *)&request);
            }
            i++;
        }

        for (i = 0; i < requests.size(); i++) {
            pthread_join(threads[i], nullptr);
        }
    }

private:
    void CreatePool() {
        std::string conninfo = "dbname = " + database_ + 
                               " user = " + user_ + 
                               " password = " + password_ + 
                               " hostaddr = " + host_ + " port = 5432";
        conn_ = PQconnectdb(conninfo.c_str());

        if (PQstatus(conn_) != CONNECTION_OK) {
            throw std::runtime_error(PQerrorMessage(conn_));
        }
    }

