def is_palindrome(string: str, l: int, r: int) -> bool:
    """ Test if given string is a palindrome, ignoring case and non-alphanumeric characters, using recursion """
    if l >= r:
        return True
    if not string[l].isalnum():
        return is_palindrome(string, l + 1, r)
    if not string[r].isalnum():
        return is_palindrome(string, l, r - 1)
    if string[l].lower() != string[r].lower():
        return False
    return is_palindrome(string, l + 1, r - 1)

def longest_palindromic_postfix(string: str) -> str:
    """ The helper function finds the longest postfix of the supplied string that is a palindrome """
    for i in range(len(string)):
        if is_palindrome(string, i, len(string) - 1):
            return string[i:]
    return ''

def make_palindrome(string: str) -> str:
    """ Find the shortest palindrome that begins with a supplied string, ignoring case and non-alphanumeric characters.
    Algorithm idea is simple:
    - Find the longest postfix of supplied string that is a palindrome.
    - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
    """
    postfix = longest_palindromic_postfix(string)
    prefix = string[:len(string) - len(postfix)]
    return string + prefix[::-1]

# Test examples
print(make_palindrome(''))         # should return an empty string ''
print(make_palindrome('cat'))      # should return 'catac'
print(make_palindrome('cata'))     # should return 'catac'
print(make_palindrome('A man!'))   # should return 'A manamanA'
```

