/** 
 * Function to calculate both the character-wise and word-wise distribution
 * and also the frequency for a given input string
 */
function distOfWordsAndChars(input) {
    // Error handling for the edge case of input missing or empty string
    if (!input || input.length === 0) {
        return "Input string is empty or not provided";
    }

    let charCount = {};
    let wordCount = {};
    let totalCharCount = 0;
    let totalWordCount = 0;

    // Cleanup the input: convert to lower case and remove punctuations
    let cleanInput = input.toLowerCase().replace(/[^a-z\s]/gi, '');

    // Process character counts
    for (let char of cleanInput) {
        if (char !== ' ') {
            charCount[char] = (charCount[char] || 0) + 1;
            totalCharCount++;
        }
    }

    // Process word counts
    let words = cleanInput.split(' ');
    for (let word of words) {
        if (word) {
            wordCount[word] = (wordCount[word] || 0) + 1;
            totalWordCount++;
        }
    }

    // Transform counts into percentages
    for (let char in charCount) {
        charCount[char] = ((charCount[char] / totalCharCount) * 100).toFixed(2);
    }

    for (let word in wordCount) {
        wordCount[word] = ((wordCount[word] / totalWordCount) * 100).toFixed(2);
    }

    return {
        characters: charCount,
        words: wordCount
    };
}
```

