    Node l1 = new Node(1, new Node(4, new Node(5, new Node(8, new Node(10)))));
    Node l2 = new Node(2, new Node(3, new Node(6, new Node(7, new Node(9)))));

    Node result = mergeLists(l1, l2);

    // print resulting list
    while(result != null) {
        System.out.print(result.val + " ");
        result = result.next;
    }
}
```

