def count_consonants(word):
    return sum(1 for c in word.lower() if c in "bcdfghjklmnpqrstvwxyz")


def merge_words(a, b):
    c = 0
    while True:
        i = random.randint(0, len(a)-1)
        if a[i] not in "aeiouAEIOU":
            break
        c += 1
        if c == len(a):
            break

    return a[:i] + a[i+1:] + b


def select_words(s, n):
    words = s.split()
    result = []
    current_word = ""
    for word in words:
        consonants = count_consonants(word)
        if consonants == n:
            if not current_word:
                current_word = word
            else:
                current_word = merge_words(current_word, word)
                n -= 1
        else:
            if current_word:
                result.append(current_word)
                current_word = ""

    if current_word:
        result.append(current_word)

    return result

