    var dobRegex = /^(0[1-9]|1[012])[- /.](0[1-9]|[12][0-9]|3[01])[- /.](19|20)\d\d$/;
    var passwordRegex = /^(?=.*\d)(?=.*[!@#$%^&*])(?=.*[a-z])(?=.*[A-Z]).{8,}$/;

    // Check name
    if (!name.match(nameRegex)) {
      alert("Invalid name");
      return false;
    }

    // Check email
    if (!email.match(emailRegex)) {
      alert("Invalid email");
      return false;
    }

    // Check phone
