        int totalSum = 0;
        int minNum = Integer.MAX_VALUE;

        for (int num : nums) {
            totalSum += Math.abs(num);
            if (num < minNum) {
                minNum = num;
            }
        }

        boolean[] dp = new boolean[totalSum + 1];
        dp[0] = true;

