function filterAndSortPrimes(arr) {
    let primeArray = arr
        .map(Number) // Convert strings to numbers.
        .filter(isPrime) // Filter out non-prime numbers.
        .sort((a, b) => b - a); // Sort the primes in descending order.

    return primeArray;
}

