def min_unique_subsequence(input_list):
    all_subsequences = {}
    for word_index, word in enumerate(input_list):
        word_length = len(word)
        for sub_length in range(1, word_length+1):
            for i in range(word_length-sub_length+1):
                subseq = word[i:i+sub_length]
                if subseq not in all_subsequences:
                    all_subsequences[subseq] = [(word_index, i)]
                else:
                    all_subsequences[subseq].append((word_index, i))

    unique_subseqs = {key:val for key, val in all_subsequences.items() if len(val)==1}
    sorted_subseqs = sorted(unique_subseqs.items(), key=lambda x:len(x[0]))
