Here is a JavaScript code snippet that accomplishes this using a continued fraction approximation algorithm. The algorithm is capable of converting decimal numbers into their fraction representations, even when the decimal number is repeating. However, there are some limits to how many repeating digits it can handle. The algorithm can also handle any positive floating point number:

```javascript
const gcd = (a, b) => {
    if (!b) {
        return a;
    }
    return gcd(b, Math.floor(a % b));
}

const returnDecimalAsFraction = (number) => {
    const tolerance = 1.0E-6;
    const fraction = number - Math.floor(number);
    if (fraction < tolerance) {
        return `${Math.floor(number)}`;
    }
    if (1 - tolerance < fraction) {
        return `${Math.ceil(number)}`;
    }
    let lower_n = 0;
    let lower_d = 1;
    let upper_n = 1;
    let upper_d = 1;
    while (true){
        let middle_n = lower_n + upper_n;
        let middle_d = lower_d + upper_d;
        if (middle_d * (fraction + tolerance) < middle_n){
            upper_n = middle_n;
            upper_d = middle_d;
        }
        else if (middle_n < (fraction - tolerance) * middle_d){
            lower_n = middle_n;
            lower_d = middle_d;
        }
        else {
            let integerPart = Math.floor(number);
            middle_n += integerPart * middle_d;
            let commonDivisor = gcd(middle_n, middle_d);
            return `${middle_n / commonDivisor}/${middle_d / commonDivisor}`;
        }
    }
}
```
