public static List<int> ParsePageNumbers(string str)
{
    var pages = new List<int>();
    var parts = str.Split(',');

    foreach (var part in parts)
    {
        if (part.Contains('-'))
        {
            var rangeParts = part.Split('-');
            var start = int.Parse(rangeParts[0]);
            var end = int.Parse(rangeParts[1]);

            for (var i = start; i <= end; i++)
            {
                pages.Add(i);
            }
        }
        else
        {
            pages.Add(int.Parse(part));
        }
    }

    return pages;
}
```

This function splits the string by commas, then for each element checks if it represents a range (contains a dash). If so, it splits the element by the dash, converts the start and end points to integers, and adds all numbers in the range to the `pages` list. If the element does not represent a range, it simply converts the string to an integer and adds it to the list.

You could then use it like this:

