```cpp
#include <iostream>
using namespace std;

bool isPerfect(int num) {
    int sum = 1;
    for(int i=2; i*i<=num; i++) {
        if(num%i==0) {
            if(i*i!=num)
                sum = sum + i + num/i;
            else
                sum = sum + i;
        } 
    } 
    if (sum==num && num!=1)
        return true;

   return false;
}

bool isPrime(int num) {
    if (num <= 1)
        return false;
    if (num <= 3)
        return true;

    if (num%2 == 0 || num%3 == 0)
        return false;

    for (int i=5; i*i<=num; i=i+6)
        if (num%i == 0 || num%(i+2) == 0)
            return false;

    return true;
}

