```Java
public class ComplexNumber {
    private double realPart;
    private double imaginaryPart;

    public ComplexNumber(double real, double imaginary) {
        this.realPart = real;
        this.imaginaryPart = imaginary;
    }

    public double getRealPart() {
        return realPart;
    }

    public double getImaginaryPart() {
        return imaginaryPart;
    }

    public ComplexNumber add(ComplexNumber cn) {
        double real = this.realPart + cn.getRealPart();
        double imaginary = this.imaginaryPart + cn.getImaginaryPart();
        return new ComplexNumber(real, imaginary);
    }

    public ComplexNumber subtract(ComplexNumber cn) {
        double real = this.realPart - cn.getRealPart();
        double imaginary = this.imaginaryPart - cn.getImaginaryPart();
        return new ComplexNumber(real, imaginary);
    }

    public ComplexNumber multiply(ComplexNumber cn) {
        double real = this.realPart * cn.getRealPart() - this.imaginaryPart * cn.getImaginaryPart();
        double imaginary = this.realPart * cn.getImaginaryPart() + this.imaginaryPart * cn.getRealPart();
        return new ComplexNumber(real, imaginary);
    }

    public ComplexNumber divide(ComplexNumber cn) {
        double denominator = Math.pow(cn.getRealPart(), 2) + Math.pow(cn.getImaginaryPart(), 2);
        double real = (this.realPart * cn.getRealPart() + this.imaginaryPart * cn.getImaginaryPart()) / denominator;
        double imaginary = (this.imaginaryPart * cn.getRealPart() - this.realPart * cn.getImaginaryPart()) / denominator;
        return new ComplexNumber(real, imaginary);
    }

    public double getMagnitude() {
        return Math.sqrt(Math.pow(this.realPart, 2) + Math.pow(this.imaginaryPart, 2));
    }

    public double getArgument() {
        return Math.atan2(this.imaginaryPart, this.realPart);
    }
}
```

