```java
import java.util.*;

class StudentRecord {
    private String studentName;
    private List<Integer> grades = new ArrayList<>();
    private int presentDays = 0;
    private int totalDays = 0;

    public StudentRecord(String studentName) {
        this.studentName = studentName;
    }

    public String getStudentName() {
        return studentName;
    }

    public void addGrade(int grade) {
        if(grade >= 0 && grade <= 100) {
            grades.add(grade);
        } else {
            throw new IllegalArgumentException("Grade must be between 0 and 100.");
        }
    }

    public double calculateAverageGrade() {
        if(grades.isEmpty()) {
            throw new IllegalStateException("No grades available.");
        }

        double sum = 0;
        for(int grade : grades) {
            sum += grade;
        }

        return sum / grades.size();
    }

    public void recordAttendance(boolean isPresent) {
        totalDays++;
        if(isPresent) {
            presentDays++;
        }
    }

    public double calculateAttendance() {
        if(totalDays == 0) {
            throw new IllegalStateException("No attendance information available.");
        }

        return ((double)presentDays / totalDays) * 100;
    }
}

public class StudentManager {
    private Map<String, StudentRecord> students = new HashMap<>();

    public void addStudent(String name) {
        students.put(name, new StudentRecord(name));
    }

    public void addGrade(String name, int grade) {
        StudentRecord studentRecord = students.get(name);
        if(studentRecord != null) {
            studentRecord.addGrade(grade);
        } else {
            throw new IllegalArgumentException("No student with this name exists.");
        }
    }

    public double getAverageGrade(String name) {
        StudentRecord studentRecord = students.get(name);
        if(studentRecord != null) {
            return studentRecord.calculateAverageGrade();
        } else {
            throw new IllegalArgumentException("No student with this name exists.");
        }
    }

    public void recordAttendance(String name, boolean isPresent) {
        StudentRecord studentRecord = students.get(name);
        if(studentRecord != null) {
            studentRecord.recordAttendance(isPresent);
        } else {
            throw new IllegalArgumentException("No student with this name exists.");
        }
    }

    public double getAttendance(String name) {
        StudentRecord studentRecord = students.get(name);
        if(studentRecord != null) {
            return studentRecord.calculateAttendance();
        } else {
            throw new IllegalArgumentException("No student with this name exists.");
        }
    }
}
