```
import java.util.List;

public class Main {

    public static void main(String[] args) {

        List<Character> charactersToRemove = List.of('a', 'b', 'c');
        String str = "abcabcabc";

        str = removeCharacters(str, charactersToRemove);
        str = caesarCipherEncrypt(str, 3);

        System.out.println("Final modified string: " + str);

    }

    // Function to remove a specific set of characters from a given string
    private static String removeCharacters(String str, List<Character> charactersToRemove) {

        StringBuilder strBuilder = new StringBuilder();

        for (char c : str.toCharArray()) {

            if (!charactersToRemove.contains(c)) {
                strBuilder.append(c);
            }
        }

        return strBuilder.toString();
    }

    // Function to perform a caesarCipherEncryption on the given string
    private static String caesarCipherEncrypt(String str, int shift) {

        StringBuilder strBuilder = new StringBuilder();

        for (char c : str.toCharArray()) {

            if (Character.isUpperCase(c)) {

                char ch = (char)(((int)c + shift - 65) % 26 + 65);
                strBuilder.append(ch);

            } else if (Character.isLowerCase(c)) {

                char ch = (char)(((int)c + shift - 97) % 26 + 97);
                strBuilder.append(ch);

            } else {

                strBuilder.append(c);

            }
        }

        return strBuilder.toString();
    }
}
```
