function removeDuplicates(arrStrings) {

    // use map to iterate through every sub array
    let newArrStrings = arrStrings.map(subArr => {

        // initialize empty array
        let noDuplicateSubArr = [];

        // initialize set
        let subArrSet = new Set();

        // iterate through the elements of sub array
        for(let str of subArr) {

          // add each string to the set
          // duplicates will be ignored
          if (!subArrSet.has(str)) {
            subArrSet.add(str);
            noDuplicateSubArr.push(str);
          }
        }

        // return the sub array without duplicates
        return noDuplicateSubArr;
      });

    // use filter to remove any empty sub arrays
    newArrStrings = newArrStrings.filter(subArr => subArr.length > 0);

    // return the new array
    return newArrStrings;
}
```

