    public static String capitalizeAndFixString(String str) {
        if(str == null || str.isEmpty()) return "";

        String[] punctuations = new String[]{".", "!", "?", ","};
        for (String punctuation : punctuations) {
            str = str.replaceAll("\\s*\\" + punctuation + "\\s*", punctuation + " ");
