```python
from itertools import permutations

def match_brackets(lst):
    brackets = {'(':')', '[':']', '{':'}'}

    for perm in permutations(lst):
        stack = []
        for string in perm:
            for character in string:
                if character in brackets.keys():
                    stack.append(character)
                elif stack and character == brackets[stack[-1]]:
                    stack.pop()
                else:
                    break
            else:
                continue
            break
        else:
            if not stack:
                return 'Yes'
    return 'No'
```

