    def __init__(self, data=None):
        self.data = data
        self.next = None

class LinkedList:
    # Linked List Class
    def __init__(self):
        self.head = None

    def add_element_at(self, index, data):
        # Adds an element at a specified index. If the index is larger than
        # the list's length, the element will be added to the end
        if not isinstance(index, int):
            raise Exception("Index must be an integer.")
        if index < 0:
            raise Exception("Index must be positive or zero.")
        if self.head is None:
            raise Exception("The list is null. Cannot add element.")

        if index == 0:
            new_node = Node(data)
            new_node.next = self.head
            self.head = new_node
        else:
            new_node = Node(data)
            temp = self.head
            counter = 0

            while temp is not None and counter < index:
                prev = temp
                temp = temp.next
                counter += 1

            prev.next = new_node
            new_node.next = temp
```
