func RescaleToUnit(numbers []float64) []float64 {
    min := numbers[0]
    max := numbers[0]

    // Find the min and max of the input list
    for _, num := range numbers {
        if num < min {
            min = num
        }
        if num > max {
            max = num
        }
    }

    // Subtract min and divide by (max-min) for each number
    for i, num := range numbers {
        numbers[i] = (num - min) / (max - min)
    }

    return numbers
