import java.util.*;

public class MainClass {

    public static List<List<String>> findAnagrams(String[] words) {
        if (words == null || words.length == 0)
            return new ArrayList<>();

        // using HashMap to group words by sorted string
        HashMap<String, List<String>> map = new HashMap<>();
        for (String word : words) {
            char[] chars = word.toCharArray();
            Arrays.sort(chars);
            String sortedString = new String(chars);

            if (!map.containsKey(sortedString)) {
                map.put(sortedString, new ArrayList<>());
            }

            map.get(sortedString).add(word);
        }

        // filter out groups that have more than one strings (anagrams)
        List<List<String>> result = new ArrayList<>();
        for (String key : map.keySet()) {
            List<String> list = map.get(key);
            if (list.size() > 1) {
                result.add(list);
            }
        }

        return result;
    }

    public static void main(String[] args) {
        String[] words = {"cat", "dog", "tac", "god", "act", "good"};
        List<List<String>> anagrams = findAnagrams(words);
