int bubbleSort(std::vector<int> &arr) {
    int n = arr.size();
    int total_swaps = 0;
    bool swapped = true;

    for(int i = 0; i < n-1 && swapped; i++) {
        swapped = false;
        for(int j = 0; j < n-i-1; j++) {
            if (arr[j] > arr[j+1]) {
                std::swap(arr[j], arr[j+1]);
                total_swaps++;
                swapped = true;
            }
        }
    }

    return total_swaps;
}

