            if (currentWord[j].match(/[\w]/)) {
                reversedWord += currentWord[j];
            } else {
                punctuation = currentWord[j] + punctuation;
            }
        }

        newArray.push(punctuation + reversedWord);
    }

    return newArray.join(' ');
}

