// Function to compute Fibonacci sequence
void computeFibonacci(int n)
{
    // Create a vector to store the Fibonacci sequence
    std::vector<long long> fibo(n + 1, 0);

    // Base cases
    fibo[0] = 0;
    fibo[1] = 1;

    // Compute the Fibonacci sequence
    for (int i = 2; i <= n; ++i)
    {
        fibo[i] = fibo[i - 1] + fibo[i - 2];
    }

    // Print the Fibonacci sequence
