```java
class InsufficientBalanceException extends Exception {
    public InsufficientBalanceException(String s) {
        super(s);
    }
}

class NegativeAmountException extends Exception {
    public NegativeAmountException(String s) {
        super(s);
    }
}

class Account {
    private String accountNumber;
    private double balance;

    public Account(String accountNumber) {
        this.accountNumber = accountNumber;
        this.balance = 0.0;
    }

    public void deposit(double amount) throws NegativeAmountException {
        if (amount < 0) {
            throw new NegativeAmountException("Deposit amount can't be negative");
        }
        this.balance += amount;
    }

    public void withdraw(double amount) throws InsufficientBalanceException, NegativeAmountException {
        if (amount < 0) {
            throw new NegativeAmountException("Withdrawal amount can't be negative");
        }
        if (this.balance < amount) {
            throw new InsufficientBalanceException("Insufficient balance");
        }
        this.balance -= amount;
    }

    public String getAccountNumber() {
        return accountNumber;
    }

    public double getBalance() {
        return balance;
    }
}

public class Main {
    public static void main(String[] args) {
        Account account1 = new Account("123456");
        try {
            account1.deposit(500);
            account1.withdraw(200);
            account1.deposit(-50); // This should raise an exception
            account1.withdraw(500); // This should raise an exception
        } catch(Exception e) {
            e.printStackTrace();
        }
    }
}
```
In this bank simulator, `InsufficientBalanceException` is thrown when trying to withdraw more money than is available in the account, and `NegativeAmountException` when trying to deposit or withdraw a negative amount.

