function createCascadingMenu(tiers, tierLevel = 1, parent = document.body) {
    if (tierLevel > tiers) {
        return;
    }

    let button = document.createElement('button');  // Create a new button
    let menu = document.createElement('div');  // Create a new div for the sub-menu

    button.style.backgroundColor = `rgb(${255 - (255 / tiers) * tierLevel}, 0, ${(255 / tiers) * tierLevel})`; // Change colour from red to blue gradually
    button.id = `button-tier${tierLevel}`;  // Set unique ID
    button.innerText = `Hello Tier ${tierLevel}`;  // Add text reflecting the tier

    button.onclick = function () {  // Toggle the visibility of the sub-menu on button click
        menu.style.display = menu.style.display === 'none' ? 'block' : 'none';
    };

    menu.style.display = 'none';  // hide sub-menu on initial load

    parent.appendChild(button);
    parent.appendChild(menu);

    createCascadingMenu(tiers, tierLevel + 1, menu);
}

