function is_prime($n) {
    if ($n <= 1) {  // Handling edge cases; 0, 1 and negatives are not prime numbers.
        return false;
    } 
    elseif ($n <= 3) {  // 2 and 3 are prime numbers.
        return true;
    } 
    elseif ($n % 2 == 0 || $n % 3 == 0) {  // Eliminate multiples of 2 and 3.
        return false;
    }

    $i = 5;
    while ($i * $i <= $n) {  // Now checking from 5 till √n if the number is divisible by any number.
        if ($n % $i == 0 || $n % ($i + 2) == 0) {
            return false;
        }
        $i += 6;  // Increment the counter by 6 since we have already checked for 2 and 3.
    }
    return true;
}
```
