function matchBrackets(lst) {
    // Declare a dictionary to pair open and close brackets
    var pair = {
        ')': '(',
        ']': '[',
        '}': '{'
    };

    // Declare a stack (an empty array)
    var stack = [];

    // Join the list to form a string and loop through each symbol
    for (var symbol of lst.join('')) {
        if(Object.values(pair).includes(symbol)) {    // Open bracket
            // Push the open brackets into the stack
            stack.push(symbol);
        } else if (Object.keys(pair).includes(symbol)) {    // Close bracket
            // If the stack is empty or the last open bracket doesn't match the close one
            if (stack.length === 0 || pair[symbol] !== stack.pop()) {
                return false;
            }
        }
    }
    // Check if the stack is empty at the end
    return stack.length === 0;
}

