import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.MethodSource;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.stream.Stream;
import java.util.stream.Stream.of;

public class DivisionTest {

    private static final double DELTA = 0.0000001;

    private static Stream<Arguments> floatPairsProvider() {
        return Stream.of(
                Arguments.of(10.0f, 5.0f, 2.0),
                Arguments.of(15.0f, 2.0f, 7.5),
                Arguments.of(-10.0f, 2.0f, -5.0),
                Arguments.of(10.0f, 0.0f, Double.POSITIVE_INFINITY) // edge case
        );
    }

    @ParameterizedTest
    @MethodSource("floatPairsProvider")
    public void testDivision(float a, float b, double expected) {
        if (b == 0.0f) {
            ArithmeticException exception = assertThrows(ArithmeticException.class, () -> a / b);
            assertEquals("/ by zero", exception.getMessage());
        } else {
            double result = a / b;
            assertEquals(expected, result, DELTA);
        }
    }
}
