Here's what this Python code looks like when translated to JavaScript:

```javascript
function hasSpecialChar(s) {
    // JavaScript also has regex support; you'll notice it looks quite similar to Python's
    const re = /[^A-Za-z]/;
    // JS's 'test' method for Regex objects returns a boolean, equivalent to the 'search' + 'bool' combo in Python
    return re.test(s);
}

function hasVowel(s) {
    const re = /[aeiou]/;
    return re.test(s);
}

function customStringList(lst, reverse=false) {
    // JS has 'filter' method on arrays that's similar to Python's filter function or list 
    // comprehensions with an 'if' condition
    let newList = lst.filter(x => x && !hasSpecialChar(x) && hasVowel(x));

    // JavaScript also has a 'sort' method on arrays. Here, we sort by length first, then by lexicographic
    // (dictionary) order if the lengths are equal.
    newList.sort((a, b) => {
        if (a.length !== b.length) {
            // If 'reverse' is true, we sort in descending order
            return reverse ? b.length - a.length : a.length - b.length;
        } else {
            // If 'reverse' is true, we reverse the sign of the result of 'localeCompare'
            return reverse ? b.localeCompare(a) : a.localeCompare(b);
        }
    });

    return newList;
}
```

