    // Split sentences into words by space character
    let words1: Vec<&str> = phrase1.split_whitespace().collect();
    let words2: Vec<&str> = phrase2.split_whitespace().collect();

    if order {
        // If order matters, compare word vectors directly
        words1 == words2
    } else {
        // If order doesn't matter, create sorted vectors and compare them
        let mut sorted_words1 = words1.clone();
        let mut sorted_words2 = words2.clone();

