def cum_sum_products(arr):

    def num(s) -> complex:
        try:
            # Try integer conversion (includes different bases)
            if type(s) == str and s.startswith(('0b', '0x', '0o')):
                return int(s, 0)
            else:
                return int(s)

        except ValueError:
            try:
                # Try floating point conversion
