class SecureDatabase {
    private $dbh;
    private $encryptionKey = 'YOUR_ENCRYPTION_KEY'; //Choose your encryption key

    public function __construct($host, $db, $user, $pass) {
        $this->dbh = new PDO("mysql:host=$host;dbname=$db", $user, $pass);
    }

    public function storeData($data) {
        $encryptedData = $this->encryptData($data);

        $stmt = $this->dbh->prepare("INSERT INTO secure_table (data) VALUES (:data)");
        $stmt->bindParam(':data', $encryptedData);
        $stmt->execute();
    }

    public function getData($id){
        $stmt = $this->dbh->prepare("SELECT data FROM secure_table WHERE id=:id");
        $stmt->bindParam(':id', $id);

        $stmt->execute();

        $row = $stmt->fetch(PDO::FETCH_ASSOC);

        return $this->decryptData($row['data']);
    }

    private function encryptData($data) {
        return openssl_encrypt($data, 'AES-128-ECB', $this->encryptionKey);
    }

    private function decryptData($data) {
        return openssl_decrypt($data, 'AES-128-ECB', $this->encryptionKey);
    }
}
