```python
class TemperatureTracker:

    def __init__(self):
        self.temperatures = {
            'Monday': [],
            'Tuesday': [],
            'Wednesday': [],
            'Thursday': [],
            'Friday': [],
            'Saturday': [],
            'Sunday': []
        }

    def add_temp(self, day, temp):
        # Check if day is valid
        if day not in self.temperatures:
            raise ValueError(f"Invalid day: {day}")

        # Check if the list for the day has already seven temperatures
        if len(self.temperatures[day]) == 7:
            # Remove the oldest temperature
            self.temperatures[day].pop(0)

        # Add the new temperature
        self.temperatures[day].append(temp)

    def get_average_temp(self, day):
        # Check if day is valid
        if day not in self.temperatures:
            raise ValueError(f"Invalid day: {day}")

        # Calculate average
        return round(sum(self.temperatures[day]) / len(self.temperatures[day]), 2)

    def get_weekly_average_temp(self):
        # Concatenate lists of temperatures for last five days
        weekly_temps = sum([self.temperatures[day] for day in list(self.temperatures.keys())[-5:]], [])

        # Check if temperatures have been recorded 
        if not weekly_temps:
            raise ValueError("No temperatures have been recorded")

        # Calculate average
        return round(sum(weekly_temps) / len(weekly_temps), 2)
```

