Here is a possible solution using Python. It creates a method to construct a tree from the given input, and another method to clone it. We also implement a simple BFS to locate the node with a given value.

```python
class Node:
    def __init__(self, val: int = 0, offspring: 'List[Node]' = None):
        self.val = val
        self.offspring = offspring if offspring is not None else []
        self.parent = None # Parent not needed for this problem

def build_tree(data):
    n = len(data)
    if n == 0: return None
    nodes = [Node(data[i]) for i in range(n) if data[i] is not None]
    node_map, children = {}, []
    for i in range(n):
        if data[i] is None:
            nodes[node_map[data[i-1]]].offspring.extend(children)
            children.clear()
        else: 
            children.append(nodes[i])
            node_map[data[i]] = i
    return nodes[0]

def clone_tree(root):
    if root is None: return None
    clone_root = Node(root.val)
    clone_map = {root.val: clone_root}
    q = collections.deque([(root, clone_root)])
    while q:
        node, clone_node = q.popleft()
        for child in node.offspring:
            if child.val not in clone_map:
                clone_child = Node(child.val)
                clone_map[child.val] = clone_child
                q.append((child, clone_child))
                clone_node.offspring.append(clone_child)
    return clone_root

def locate_node(root, target):
    if root is None: return None
    q = collections.deque([root])
    while q:
        node = q.popleft()
        if node.val == target:
            return node
        for child in node.offspring:
            q.append(child)
    return None
```

