```JavaScript
function classifyAndCountCharacters(str) {
    var classification = {
        vowels: [],
        consonants: [],
        numbers: [],
        uppercase: 0,
        lowercase: 0,
        specialChars: [],
    };

    for (let i = 0; i < str.length; i++) {
        let ch = str.charAt(i);

        if ((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z')) {
            if (ch == ch.toLowerCase()) {
