            classification.numbers.push(ch);
        } else if (ch >= ' ' && ch <= '~') {
            classification.specialChars.push(ch);
        }
    }

    classification.vowels.sort();
    classification.consonants.sort();
    classification.numbers.sort();
    classification.specialChars.sort();

    return classification;
}
