function medianAndMode(arr) {
    arr.sort(function(a, b) {
        return a - b;
    });

    // Calculate median
    var median;
    var arrLen = arr.length;
    if (arrLen % 2 === 0) { // array length is even
        median = (arr[(arrLen / 2) - 1] + arr[arrLen / 2]) / 2;
    } else { // array length is odd
        median = arr[Math.floor(arrLen / 2)];
    }

    // Calculate mode
    var freqDict = {};
    for (var i = 0; i < arrLen; i++) {
        var val = arr[i];
        freqDict[val] = (freqDict[val] || 0) + 1;
    }

    var maxFreq = Math.max(...Object.values(freqDict));
    var modes = Object.keys(freqDict).reduce(function(acc, val) {
        if (freqDict[val] === maxFreq) {
            acc.push(Number(val));
        }
        return acc;
    }, []);

    // If there's only a single mode, return it. Otherwise, no mode.
    var mode = modes.length === 1 ? modes[0] : null;

    return {median: median, mode: mode};
}
```
