    public static bool CheckAnagramSegments(string text)
    {
        // count the frequency of each unique character in the string
        var frequency = new Dictionary<char, int>();
        foreach (char charac in text)
        {
            if (frequency.ContainsKey(charac))
            {
                frequency[charac]++;
            }
            else
            {
                frequency[charac] = 1;
            }
        }

        // count characters with odd count frequency
