```javascript
// This function would control an individual image element
function controlImageElement(element, event) {
    // Set up the transformations
    let transformProps = ['rotateY', 'rotateX'];
    let rotate = {
        rotateY: event.clientX / window.innerWidth * 360 - 180,
        rotateX: event.clientY / window.innerHeight * -360 + 180
    };

    // Apply transformations to element
    let style = window.getComputedStyle(element)
    let transform = style.getPropertyValue('transform')
    transformProps.forEach(function(prop) {
