```javascript
function jsonToTable(json, table = null, row = null, pname = '') {
    let tag = table ? 'td' : 'th';
    row = row || document.createElement('tr');
    table = table || document.createElement('table');
    for (let key in json) {
        let cell = document.createElement(tag);
        cell.appendChild(document.createTextNode(Array.isArray(json) ? (Array.isArray(json[0]) ? pname : key) : key));
        row.appendChild(cell);
        if (typeof json[key] === 'object' && json[key] !== null && !Array.isArray(json[key])) {
            jsonToTable(json[key], table, null, key);
        } else {
            let cell = document.createElement(tag);
            if(Array.isArray(json)){
               cell.appendChild(document.createTextNode(json[key]));
            } else if (typeof json[key] !== 'object'){
               cell.appendChild(document.createTextNode(json[key]));
            }
            row.appendChild(cell);
        }
    }
    table.appendChild(row);
    return table;
}
