import Foundation

func get_car_position(time: Double, speed: Double, starting_time: Double) -> Double{
    return max(0.0, (time - starting_time) * speed)
}

func calculate_collision_time(left_car_start_time: Double, left_car_speed: Double, right_car_start_time: Double, right_car_speed: Double) -> Double? {
    if left_car_start_time >= right_car_start_time {
        return nil
    }
    let meeting_time = (right_car_start_time - left_car_start_time) / (left_car_speed + right_car_speed)
    if get_car_position(time: left_car_start_time + meeting_time, speed: left_car_speed, starting_time: left_car_start_time) <= get_car_position(time: right_car_start_time, speed: right_car_speed, starting_time: right_car_start_time - meeting_time){
        return left_car_start_time + meeting_time
    }
    return nil
}

func advanced_car_race_collision(n: Int, left_cars: [(Double, Double)], right_cars: [(Double, Double)], after_collision_speed: Double) -> Double? {
    var events = [(Double, (Double, Double), (Double, Double))]()
    for i in 0..<n {
        let (left_car_start_time, left_car_speed) = left_cars[i]
        for j in 0..<n {
            let (right_car_start_time, right_car_speed) = right_cars[j]
            if let collision_time = calculate_collision_time(left_car_start_time: left_car_start_time, left_car_speed: left_car_speed, right_car_start_time: right_car_start_time, right_car_speed: right_car_speed) {
                events.append((collision_time, (left_car_start_time, left_car_speed), (right_car_start_time, right_car_speed)))
            }
        }
    }
    events.sort { $0.0 < $1.0 } 
    var target_position = Double.infinity
    while !events.isEmpty {
        let (event_time, (left_start_time, left_speed), (right_start_time, right_speed)) = events.removeFirst()
        let left_car_position = get_car_position(time: event_time, speed: left_speed, starting_time: left_start_time)
        let right_car_position = get_car_position(time: event_time, speed: right_speed, starting_time: right_start_time)
        if left_car_position < target_position || right_car_position < target_position {
            target_position = min(left_car_position, right_car_position)
        } else {
            return event_time
        }
        events.append((event_time + (target_position / after_collision_speed), (left_start_time, after_collision_speed), (right_start_time, after_collision_speed)))
        events.sort { $0.0 < $1.0 }
    }
    return nil
}
```

