function partition(&$array, $low, $high, $cmp_func) {
    $pivot = $array[$high];
    $i = ($low - 1);

    for ($j = $low; $j <= $high - 1; $j++) {
        if ($cmp_func($array[$j], $pivot) < 0) {
            $i++;
            list($array[$i], $array[$j]) = [$array[$j], $array[$i]];
        }
    }
    list($array[$i + 1], $array[$high]) = [$array[$high], $array[$i + 1]];
    return ($i + 1);
}

function quick_select(&$array, $low, $high, $k, $cmp_func) {
    if ($k > 0 && $k <= $high - $low + 1) {
        $index = partition($array, $low, $high, $cmp_func);

        if ($index - $low == $k - 1) {
            return $array[$index];
        }
        if ($index - $low > $k - 1) {
            return quick_select($array, $low, $index - 1, $k, $cmp_func);
        }
        return quick_select($array, $index + 1, $high, $k - $index + $low - 1, $cmp_func);
    }
    return INF;
}

