class Vector20:

    def __init__(self, vec: list[list[int]]):
        self.v = []
        self.idx = 0
        self.skip = []
        self.num_skips = 0
        for sublist in vec:
            for el in sublist:
                self.v.append(el)

    def next(self) -> int:
        # Process any skips before returning next element
        while self.idx in self.skip and self.skip[self.idx] > 0:
            self.skip[self.idx] -= 1
            self.idx += 1
            self.num_skips -= 1

        result = self.v[self.idx]
        self.idx += 1
