    def hasNext(self) -> bool:
        # Update index to next valid element if necessary
        while self.idx in self.skip and self.skip[self.idx] > 0:
            self.skip[self.idx] -= 1
            self.idx += 1
            self.num_skips -= 1

        return self.idx < len(self.v)

