def all_permutations(string):
    # Validate if string contains any non-lowercase or duplicate letters
    letter_set = set()
    for ch in string:
        if not ch.islower():
            return "Input string should only contain lowercase letters"
        elif ch in letter_set:
            return "Input string should only contain distinct characters"
        else:
            letter_set.add(ch)

    result = []
    # Generate permutations for all substrings
    for i in range(len(string)):
        for j in range(i+1, len(string)+1):
            substring = string[i:j]
            permutations = generate_permutations("", substring, [])
            result.extend(permutations)
    # Remove duplicates and return sorted list
    result = remove_duplicates(result)
    return lexiographic_sort(result)

def generate_permutations(prefix, remaining, result):
    if len(remaining) == 0:
        result.append(prefix)
    else:
        for i in range(len(remaining)):
            generate_permutations(prefix + remaining[i], remaining[:i] + remaining[i+1:], result)
    return result

def remove_duplicates(lst):
    out = []
    for l in lst:
        if l not in out:
            out.append(l)
    return out

def lexiographic_sort(lst):
    len_list = len(lst)
    for i in range(len_list):
        for j in range(len_list-i-1):
            if lst[j] > lst[j+1]:
                lst[j], lst[j+1] = lst[j+1], lst[j]
    return lst

print(all_permutations("abc"))
```

This script first validates the string input. It then generates permutations for all substrings of the provided string, removes duplicates, sorts them in lexicographical order and returns the sorted list. Lowercase letters comparison is compatible with lexicographical order, so the script can just use the '>' operator to find out which letter precedes the other in the alphabet.

