```cpp
#include <iostream>
#include <string>

std::string getLastNCharacters(const std::string& str, int n) {
    if(n <=0 || n > str.length()) {
        // if n is non-positive or greater than string length , return the input string
        return str;
    } 

    // Get the starting position for substr function
    int startPosition = str.length() - n;
    // Get the last 'n' characters from the string
    return str.substr(startPosition, n);
}

int main() {
    std::string str = "Hello World!";
    int n = 5;

    std::string lastNCharacters = getLastNCharacters(str, n);

    std::cout << "The last " << n << " characters from the string '" << str << "' are '" << lastNCharacters << "'\n";

    return 0;
}
