      if (place.geometry.viewport) {
        bounds.union(place.geometry.viewport);
      } else {
        bounds.extend(place.geometry.location);
      }

      document.getElementById('coordinates').textContent = `Latitude: ${place.geometry.location.lat()}, Longitude: ${place.geometry.location.lng()}`;
    });

    map.fitBounds(bounds);
