def fibonacci_sequence(n):
    lst = []

    # First two numbers of fibonacci sequence
    a, b = 0, 1

    while len(lst) < n:
        # add next number to list
        a, b = b, a + b
        if a >= 1001: 
            a = a % 1000 + 1
            b = a % 1000 + 1

        if len(lst) == 0 or len(lst) > 0 and abs(lst[-1] - a) > 1:
            lst.append(a)
    return lst

def is_prime(n):
    if n == 1:
        return False
    elif n == 2:
        return True
    else:
        for x in range(2, n):
            if n % x == 0:
                return False
        return True  

