extern crate num_traits;
use num_traits::pow;
use std::f64::consts::PI;

pub fn do_calculations(operators: Vec<&str>, operands: Vec<f64>) -> f64 {
    let mut result = operands[0];
    for i in 0..operators.len() {
        match operators[i] {
            "+" => result += operands[i+1],
            "-" => result -= operands[i+1],
            "*" => result *= operands[i+1],
            "//" => result = (result / operands[i+1]).floor(),
            "**" => result = pow(result, operands[i+1] as u32),
            "sin" => result -= (operands[i+1]*PI/180.0).sin(),
            "cos" => result -= (operands[i+1]*PI/180.0).cos(),
            "tan" => result -= (operands[i+1]*PI/180.0).tan(),
            _ => (),
        }
    }
    (result * 100.0).round() / 100.0
}

