```c++
#include <iostream>
#include <vector>
#include <algorithm>
#include <stdexcept>

int main() {
    try {
        // Initialize a 2-D array
        int arr[3][3] = {{-2, 5, 12}, {7, -1, 8}, {3, 3, -4}};

        // Initialize a 1-D vector to store the elements of the 2-D array
        std::vector<int> vec;

        // Loop through the 2-D array to place its elements into the 1-D vector
        for (int i = 0; i < 3; ++i) {
            for (int j = 0; j < 3; ++j) {
                vec.push_back(arr[i][j]);
            }
        }

        // Sort the vector. This can handle negative numbers and duplicates.
        std::sort(vec.begin(), vec.end());

        // Print out the sorted elements
        for (int i = 0; i < vec.size(); ++i) {
            std::cout << vec[i] << " ";
        }
    } catch (const std::exception &e) {
        // This will catch any standard exceptions thrown during program execution
        std::cerr << "Exception caught: " << e.what() << '\n';
    } catch (...) {
        // This will catch all other exceptions not caught by the previous handler
        std::cerr << "Unknown exception caught.\n";
    }

    return 0;
}
```

