class PrimesInRange:
    def __init__(self, start_num, end_num):
        if start_num > end_num or start_num <= 0 or end_num <= 0:
            raise ValueError("start_num must be less than end_num and both should be positive integers")
        self.start_num = start_num
        self.end_num = end_num

    def is_prime(self,n):
        if n <= 1 or (n % 2 == 0 and n > 2):
            return False
        return all(n % i for i in range(3, int(n**0.5) + 1, 2))

    def count_primes(self, inclusive=True):
        count = 0
        for i in range(self.start_num, self.end_num+1):
            if self.is_prime(i):
                if inclusive:
                    count += 1
                elif i > self.start_num and i < self.end_num:
                    count += 1
        return count
