int how_many_times(char* string, char* substring) {
    int start = 0;
    int count = 0;
    char* pos;

    while (start < strlen(string)) {
        pos = strstr(&string[start], substring); // Finds the substring from the starting position
        if (pos != NULL) {
            start = pos - string + 1;  // Updates the starting position
            count++; 
        }
        else
            break;
    }
    return count;
}

// Function to count how many times a string can be formed from another string
int count_subsequences(char* string, char* substring) {
    int m = strlen(substring);
    int n = strlen(string);

    if (m > n) return 0; // If substring is longer than the string, it can't form anything

    // Create the dynamic programming table
    int** count = (int**)malloc((m+1) * sizeof(int*));
    for (int i = 0; i < m+1; i++)
        count[i] = (int*)malloc((n+1) * sizeof(int));

    // Initialize the zero row with 1
    for (int j = 0; j <= n; j++)
        count[0][j] = 1;

    for (int i = 1; i <= m; i++) {
        for (int j = 1; j <= n; j++) {
            // If the current characters match, increment the count of previous solutions
            if (substring[i - 1] == string[j - 1]) 
                count[i][j] = count[i - 1][j - 1] + count[i][j - 1];
            else
                count[i][j] = count[i][j - 1]; // Else keep the count of the solutions without the new character
        }
    }

    int result = count[m][n]; // The last cell will hold the number of times a string can be formed

    for (int i = 0; i < m+1; i++) // Free the allocated memory
        free(count[i]);
    free(count);

    return result;
}

int main() {
    char string[] = "abcab";
    char substring[] = "ab";
    printf("%d\n", how_many_times(string, substring)); // Outputs 2
    printf("%d\n", count_subsequences(string, substring)); // Outputs 3
    return 0;
}
```
