import re

def extract_brackets(s):
    # curly braces, regular braces, angle brackets, square brackets
    brackets = {"curly": [], "angle": [], "square": [], "round": []}
    # escape sequences for different brackets
    escape_sequences = {'\{':'curly','\}':'curly','\(':'round','\)':'round','<':'angle','>':'angle','\[':'square','\]':'square'}

    # lists of opening and closing brackets
    open_brackets = ['{', '(', '<', '[']
    close_brackets = ['}', ')', '>', ']']

    stack = []
    for i in s:
        # check for opening brackets
        if i in open_brackets:
            stack.append(i)
            brackets[escape_sequences['\\'+str(i)]].append("")
        # check for closing brackets 
        elif i in close_brackets:
            # make sure that the closing bracket matches the last added opening bracket
            if len(stack) == 0 or open_brackets[close_brackets.index(i)] != stack[-1]:
                return "Mismatched brackets"
            else: 
                stack.pop()
        # otherwise, add the character to the current open bracket section
        elif len(stack) > 0:
            brackets[escape_sequences['\\'+str(stack[-1])]][-1] += str(i)

    # check if any brackets are still open
    if len(stack) != 0:
        return "Mismatched brackets"

    return brackets
```
