```python
class NonagonalNumbers:

    def __init__(self):
        self.results_cache = {0:0}
        self.cumulative_sum_cache = {0:0}
        self.product_cache = {0:1}
        self.limit = 1000

    def calc_nonagonal(self, n):
        if n < 0 or not isinstance(n, int):
            return "Invalid positive integer."

        if n > self.limit:
            return f"Your number exceeds the limit of {self.limit}."

        if n not in self.results_cache:
            result = 4.5 * n * n - 3.5 * n
            self.results_cache[n] = result

        return self.results_cache[n]

    def nonagonal_sequence(self, n):
        sequence = [self.calc_nonagonal(i) for i in range(n+1)]
        return sequence

    def cumulative_sum(self, n):
        if n not in self.cumulative_sum_cache:
            sum_result = sum(self.nonagonal_sequence(n))
            self.cumulative_sum_cache[n] = sum_result

        return self.cumulative_sum_cache[n]

    def product(self, n):
        if n not in self.product_cache:
            prod_result = 1
            for i in range(1, n+1):
                prod_result *= self.calc_nonagonal(i)
            self.product_cache[n] = prod_result

        return self.product_cache[n]

    def process_range(self, start, end):
        if start > end or start < 1:
            return "Invalid range."

        return [self.calc_nonagonal(i) for i in range(start, end+1)]

    def process_array(self, arr):
        if not all(isinstance(i, int) for i in arr):
            return "Invalid array of integers."

        return [self.calc_nonagonal(i) for i in arr]

    def process_array_of_ranges(self, array_of_ranges):
        if not all(len(range_i)==2 for range_i in array_of_ranges):
            return "Invalid array of ranges."

        return [self.process_range(range_i[0], range_i[1]) for range_i in array_of_ranges]
```
