// Bank Account class
class BankAccount {
  constructor(accountNumber) {
    this.accountNumber = accountNumber;
    this.balance = 0;
  }

  deposit(amount) {
    if (amount < 0) throw new Error('Invalid amount');
    this.balance += amount;
  }

  withdraw(amount) {
    if (amount > this.balance) throw new Error('Insufficient balance');
    this.balance -= amount;
  }

  transfer(amount, toAccount) {
    this.withdraw(amount);
    toAccount.deposit(amount);
  }
}

// Customer class
class Customer {
  constructor() {
    // Using Map instead of Object as map better a suitable data structure for this use case.
    this.bankAccounts = new Map();
  }

  addAccount(account) {
    this.bankAccounts.set(account.accountNumber, account);
  }

  makeOperation(operation, accountNumber, amount, toAccountNumber = null) {
    let account = this.bankAccounts.get(accountNumber);
    if (!account) throw new Error('Invalid account number');

    switch (operation) {
      case 'deposit':
        account.deposit(amount);
        break;

      case 'withdraw':
        account.withdraw(amount);
        break;

      case 'transfer':
        let toAccount = this.bankAccounts.get(toAccountNumber);
        if (!toAccount) throw new Error('Invalid account number for transfer');
        account.transfer(amount, toAccount);
        break;

      default:
        throw new Error('Invalid operation');
    }
  }
}
