Below is a simple program to find common words in two sentences in Node.js using sets:

```node.js
function commonWords(sentence1, sentence2) {
  // Ensure input is string
  if (typeof sentence1 !== 'string' || typeof sentence2 !== 'string') {
    return 'Input must be string';
  }

  // Convert string to Array
  let sentence1Array = sentence1.toLowerCase().split(' ');
  let sentence2Array = sentence2.toLowerCase().split(' ');

  // Initialize new Set for each sentence to remove any duplicate words
  let set1 = new Set(sentence1Array);
  let set2 = new Set(sentence2Array);

  // Filter set1 to contain only elements also in set2
  let commonWords = [...set1].filter(word => set2.has(word));

  return commonWords;
}

let sentence1 = 'The quick brown fox jumps over the lazy dog.';
let sentence2 = 'The lazy dog barks at the quick fox.';

console.log(commonWords(sentence1, sentence2));
```

The function `commonWords` takes two sentences as input and converts them into arrays of words with the `split` method. To ensure we do not have duplicates, we convert the arrays into sets.
Then we use `Array.filter` to create a new array (commonWords) of elements that return true from a check whether `set2` includes the `set1` element. Then it returns `commonWords`.
By running this script, we will have an array of words, which are common to both sentences.

