function longestCommonPrefix(strings) {
  if (!strings.length) return ""; // return an empty string if the input array is empty

  let prefix = strings[0];

  for (let i = 1; i < strings.length; i++) {
    let j = 0;

    while (j < prefix.length && j < strings[i].length && prefix[j] == strings[i][j]) {
        j++; // increment j if the characters at index j in prefix and strings[i] are the same
