In JavaScript, objects extend other objects. So, it's an object-based language rather than class-based language. Prototypal inheritance refers to the ability of an object to inherit properties and methods from another object. This is the core concept of JavaScript.

Here is a simple code snippet demonstrating prototypal inheritance:

```javascript
function Vehicle(type) {
    this.type = type;
}

Vehicle.prototype.getType = function() {
    return this.type;
}

function Car(name) {
    this.name = name;
}

Car.prototype = new Vehicle("car");

let myCar = new Car("Tesla");
console.log(myCar.getType()); // "car"
```

In this example, `Car` inherits from `Vehicle` by setting `Car`'s prototype to a new instance of `Vehicle`. When `getType` is invoked on `myCar`, JavaScript looks up the prototype chain, doesn't find it on `Car`, but finds it on `Vehicle`.

A closure is a function bundled together (enclosed) with references to its surrounding state (lexical environment). In JavaScript, closures are created every time a function is created, at function creation time.

```javascript
function Vehicle(type) {
    let vehicleType = type;

    return {
        getType: function() {
            return vehicleType;
        }
    }
}

function Car(name) {
    let instance = Vehicle("car");
    instance.name = name;

    return instance;
}

let myCar = Car("Tesla");
console.log(myCar.getType()); // "car"
```

This above code represents a combination of closures and prototypal inheritance. `Vehicle` returns an object which closes over `type` and `Car` returns an instance of `Vehicle`, with some additions. 

One common issue with prototypal inheritance is shared properties between instances through prototype.

```javascript
function Vehicle() {
  this.features = [];
}

function Car() {}

Car.prototype = new Vehicle();

let car1 = new Car();
let car2 = new Car();

car1.features.push('electric');

console.log(car2.features); // ['electric']
```

As you see, `features` array is shared between car1 and car2 which is not the expected behavior. We can solve this problem using closures.

```javascript
function Vehicle() {
    let features = [];

    return {
        addFeature: function(feature) {
            features.push(feature);
        },
        getFeatures: function() {
            return [...features]; //return a copy of our features array to prevent mutations
        }
    }
}

function Car() {
    let vehicle = Vehicle();
    return Object.assign({}, vehicle);
}

let car1 = Car();
let car2 = Car();

car1.addFeature('electric');

console.log(car1.getFeatures()); // ['electric']
console.log(car2.getFeatures()); // []
```

In this example, each car has its own features array because it's not inherited from `Vehicle`'s prototype but captured from the individual function call.

Here is a simple java program that validates a credit card number using Luhn's algorithm and also checks that the card number is 16 digits long and starts with either the digit 4 or 5.

```java
public class Main {
    public static void main(String[] args) {
        String cardNumber = "4532015112830361";
        System.out.println(validateCard(cardNumber));
    }

    public static boolean validateCard(String cardNumber) {
        if ((cardNumber.length() != 16) || (cardNumber.charAt(0) != '4' && cardNumber.charAt(0) != '5')) {
            return false;
        }

        int sum = 0;
        boolean alternate = false;
        for (int i = cardNumber.length() - 1; i >= 0; i--) {
            int n = Integer.parseInt(cardNumber.substring(i, i + 1));
            if (alternate) {
                n *= 2;
                if (n > 9) {
                    n = (n % 10) + 1;
                }
            }
            sum += n;
            alternate = !alternate;
        }

        return (sum % 10 == 0);
    }
}
```

This program firstly checks the length of the card number and the first digit. If the card number is not 16 digits long or doesn't start with 4 or 5 it instantly returns false. Then it applies the Luhn algorithm: traverses the card number from right to left, doubles every second digit and adds those to a running total. If doubling of a digit results in a number greater than 9, it subtracts 9 from the product. Lastly, it checks if the total modulo 10 is equal to 0, which implies that the card number is valid according to Luhn's algorithm.

