def optimize_all_products(p, q, init, radix):
    if p > q or init < 0 or not(2 <= radix <= 16):
        return -1

    product = init
    for i in range(p, q+1):
        product *= i

    if radix == 2:
        return bin(product)
    elif radix == 8:
