		testing.Main(func(pat, str string) (bool, error) { return true, nil },
			[]testing.InternalTest{},
			[]testing.InternalBenchmark{{"MyBenchmark", BenchmarkSomething}},
			[]testing.InternalExample{})
		return nil
	},
}

func BenchmarkSomething(b *testing.B) {
