class Stack:
    def __init__(self):
        self.stack = []
        self.maxStack = []

    def push(self, num):
        self.stack.append(num)
        if len(self.maxStack) == 0 or num > self.maxStack[-1]:
            self.maxStack.append(num)

    def pop(self):
        if len(self.stack) != 0:
            if self.stack[-1] == self.maxStack[-1]:
                self.maxStack.pop()
            return self.stack.pop()
        else:
            return None

    def max_stack(self):
        if len(self.maxStack) != 0:
            return self.maxStack[-1]
        else:
            return None
