private:
    unordered_map<int, Employee*> db; // to ensure unique employee_id and fast access to Employee
    map<double, set<int>> salary_map; // to ensure quick access to highest salary, and median salary

public:
    void addEmployee(int id, string name, double salary){
        if(db.find(id)!=db.end())
            return;
        Employee* new_employee = new Employee(id, name, salary);
        db[id] = new_employee;
        salary_map[-salary].insert(id); // store negative of salary for accessing highest salary
    }

    void updateSalary(int id, double new_salary){
        if(db.find(id)==db.end())
            return;
        double old_salary = db[id]->salary;
        salary_map[-old_salary].erase(id);
        if (salary_map[-old_salary].empty()) {
            salary_map.erase(-old_salary);
        }
        db[id]->salary = new_salary;
        salary_map[-new_salary].insert(id);
    }

    const Employee* findEmployee(int id){
        if(db.find(id)==db.end())
            return nullptr;
        return db[id];
    }

    vector<Employee*> kHighestSalaryEmployees(size_t k) {
        vector<Employee*> result;
        for (auto it = salary_map.begin();
            it != salary_map.end() && result.size() < k;
            ++it) {
            for (int id : it->second) {
                result.push_back(db[id]);
                if(result.size() == k)
                    break;
            }
        }
        return result;
    }

    double medianSalary() {
        int n = db.size();
        double median;
        auto it = salary_map.begin();
        std::advance(it,n/2);
        if(n % 2 == 0){
            median = (it->first + (++it)->first) / 2.0;
        }else{
            median = it->first;
        }
        return -median;
    }
};

