Here is a simple implementation of a LRU Cache using a LinkedList and a HashMap in Java:

```java
import java.util.HashMap;

public class LRUCache<K, V> {
    private int capacity;
    private HashMap<K, Node> map;
    private Node head, tail;

    public LRUCache(int capacity) {
        this.capacity = capacity;
        this.map = new HashMap<>();
        head = new Node(0, 0);
        tail = new Node(0, 0);
        head.next = tail;
        tail.prev = head;
    }

    public V get(K key) {
        Node node = map.get(key);
        if(node == null) {
            return null; //should return something like NullValueException
        }
        remove(node);
        insert(node);
        return node.value;
    }

    public void add(K key, V value) {
        if(map.containsKey(key)) {
            remove(map.get(key));
        }
        if(map.size() == capacity) {
            remove(tail.prev);
        }
        insert(new Node(key, value));
    }

    public boolean exists(K key) {
        return map.containsKey(key);
    }

    public void display() {
        Node cur = head.next;
        while(cur != tail) {
            System.out.print(cur.value + " ");
            cur = cur.next;
        }
        System.out.println();
    }

    private void remove(Node node) {
        map.remove(node.key);
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    private void insert(Node node){
        map.put(node.key, node);
        node.next = head.next;
        node.prev = head;
        head.next.prev = node;
        head.next = node;
    }

    class Node {
        K key;
        V value;
        Node prev, next;

        public Node(K key, V value) {
            this.key = key;
            this.value = value;
        }
    }
}
```

