function calculateSinCos(angleInDegrees) {
    // Check if input is a number
    if (typeof angleInDegrees !== 'number') {
        return 'Please provide a number';
    }

    // Adjust for negative input and values larger than 360
    let adjustedAngle = (((angleInDegrees % 360) + 360) % 360);

    // Convert the degrees to radians
    let angleInRadians = adjustedAngle * Math.PI / 180;

    // Calculate sine and cosine
    let sineValue = Math.sin(angleInRadians).toFixed(4);
    let cosineValue = Math.cos(angleInRadians).toFixed(4);

    // return as object
    return {
        sine: sineValue,
        cosine: cosineValue
    };
}

