// Required in Node.JS environment to parse dates
const { parseISO, differenceInMonths } = require('date-fns');

function employeeDetails(employee){
    // Retrieving the 'name', 'age', and 'city' details of the person.
    const name = employee.name;
    const age = employee.age;
    const city = employee.city;

    // Listing all the 'departmentName' where the person has worked.
    const departmentsWorked = employee.departments.map(department => department.departmentName);

    // Deduce the current department name where the person is working currently, or return 'Unemployed' if the person is not currently working.
    const currentDepartment = employee.departments.find(department => department.endDate === null);
    const currentDepartmentName = currentDepartment ? currentDepartment.departmentName : 'Unemployed';

