        while (i != 0 and self.heap[self.parent(i)] > self.heap[i]):
            self.swap(self.parent(i), i)
            i = self.parent(i)

    def heapify_down(self, i):
        smallest = i
        if (2*i + 1 < len(self.heap) and self.heap[smallest] > self.heap[2*i + 1]):
            smallest = 2*i + 1
        if (2*i + 2 < len(self.heap) and self.heap[smallest] > self.heap[2*i + 2]):
            smallest = 2*i + 2
        if smallest != i:
            self.swap(smallest, i)
            self.heapify_down(smallest)

    def verify_min_heap_property(self):
        for i in range(1, len(self.heap)):
            if self.heap[self.parent(i)] > self.heap[i]:
                return False
        return True

class MaxHeap:
    def __init__(self):
        self.heap = []

    def parent(self, i):
        return (i - 1)//2

    def insert_key(self, k):
        self.heap.append(k)
        self.heapify_up(len(self.heap)-1)

    def increase_key(self, i, new_val):
        self.heap[i] = new_val
        self.heapify_up(i)

    def maximum(self):
        return self.heap[0]

    def extract_max(self):
        if len(self.heap) <= 0:
            return float('-inf')
        root = self.heap.pop(0)
        self.heapify_down(0)
        return root

    def delete_key(self, i):
        self.increase_key(i, float('inf'))
        self.extract_max()

    def swap(self, x, y):
        self.heap[x], self.heap[y] = self.heap[y], self.heap[x]

    def heapify_up(self, i):
        while (i != 0 and self.heap[self.parent(i)] < self.heap[i]):
            self.swap(self.parent(i), i)
            i = self.parent(i)

    def heapify_down(self, i):
        largest = i
        if (2*i + 1 < len(self.heap) and self.heap[largest] < self.heap[2*i + 1]):
            largest = 2*i + 1
        if (2*i + 2 < len(self.heap) and self.heap[largest] < self.heap[2*i + 2]):
            largest = 2*i + 2
        if largest != i:
            self.swap(largest, i)
            self.heapify_down(largest)

    def verify_max_heap_property(self):
        for i in range(1, len(self.heap)):
            if self.heap[self.parent(i)] < self.heap[i]:
                return False
        return True
