        while cur:
            print(cur.data, end=' ')
            cur = cur.next
        print()

    def delete_at_positions(self, positions):
        cur = self.head
        idx = 0
        while cur:
            if idx in positions:
                if cur.prev:
                    cur.prev.next = cur.next
                if cur.next:
                    cur.next.prev = cur.prev
                if idx == 0:
                    self.head = cur.next
            cur = cur.next
            idx += 1

