                    newArray[i][j] = multiArray[i][j];
                    newArrayLength++;
                }
            }
        }

        // Print new array
        for(int i = 0; i < newArray.length; i++) {
            for(int j = 0; j < newArray[i].length; j++) {
                System.out.print(newArray[i][j] + " ");
