```go
package main

import "fmt"

func fibfib(n int) int {
    memo := make(map[int]int)
    return helper(n, memo)
}

func helper(n int, memo map[int]int) int {
    if _, ok := memo[n]; ok {
        return memo[n]
    } 

    var result int
    if n <= 1 {
        return 0
    } else if n == 2 {
        return 1
    } else if n > 2 {
        result = helper(n-1, memo) + helper(n-2, memo) + helper(n-3, memo)
    } else if n < 0 {
        result = helper(n+3, memo) - helper(n+2, memo) - helper(n+1, memo)
    }

    memo[n] = result
    return result
}

func main() {
    fmt.Println(fibfib(10))
}
```

