Here is an example of a simple Least Recently Used (LRU) cache in the C++ Standard Library:

```cpp
#include <unordered_map>
#include <list>

template <typename Key, typename Value>
class LRUCache {
public:
    LRUCache(size_t maxSize) : maxSize(maxSize) {}

    void insert(Key key, Value* value)
    {
        // First check if it's already in our items map
        // If it is, move it to the front of the list
        if (itemsMap.find(key) != itemsMap.end())
        {
            // Move an existing item to the front
            itemsList.splice(itemsList.begin(), itemsList, itemsMap[key]);
        }
        else
        {
            // Insert it to list and add it to the item map
            itemsList.push_front(*value);
            itemsMap[key] = itemsList.begin();

            // If we exceeded the max size, remove the last item
            if (itemsList.size() > maxSize)
            {
                itemsMap.erase(itemsList.back());
                itemsList.pop_back();
            }
        }
    }

    Value* get(Key key)
    {
        if (itemsMap.find(key) == itemsMap.end())
            return nullptr;

        // Move the accessed item to the front
        itemsList.splice(itemsList.begin(), itemsList, itemsMap[key]);
        return &(*itemsMap[key]);
    }

    bool exists(Key key) const
    {
        return itemsMap.find(key) != itemsMap.end();
    }

    size_t size() const
    {
        return itemsMap.size();
    }

private:
    std::list<Value> itemsList;
    std::unordered_map<Key, decltype(itemsList.begin())> itemsMap;
    size_t maxSize;
};
```

In this example, the LRU Cache is implemented using an STL list to keep the items and an unordered_map to map the keys to their corresponding list iterators. When an item is accessed and found in the map, it is moved to the front of the list. When an item is inserted and the cache is full, the last item in the list is removed. For inserting and accessing an item, it works at O(1) complexity.

