public class PalindromePrimeChecker {

    public static class Result {
        private final int number;
        private final boolean isPalindrome;
        private final boolean isPrime;

        public Result(int number, boolean isPalindrome, boolean isPrime) {
            this.number = number;
            this.isPalindrome = isPalindrome;
            this.isPrime = isPrime;
        }

        public int getNumber() {
            return number;
        }

        public boolean isPalindrome() {
            return isPalindrome;
        }

        public boolean isPrime() {
            return isPrime;
        }
    }

    public static Result checkNumber(int input) {
        return new Result(input, isPalindrome(input), isPrime(input));
    }

    private static boolean isPalindrome(int n) {
        int reverse = 0;
        int original = n;

        while (n != 0) {
            reverse = reverse * 10 + n % 10;
            n = n / 10;
        }

        return original == reverse;
    }

    private static boolean isPrime(int n) {
        if (n <= 1)
            return false;

        if (n <= 3)
            return true;

        if (n % 2 == 0 || n % 3 == 0)
            return false;

        for (int i = 5; i * i <= n; i = i + 6) {
            if (n % i == 0 || n % (i + 2) == 0)
                return false;
        }

        return true;
    }

    public static void main(String[] args) {
        Result result = checkNumber(101);

        System.out.println("Number: " + result.getNumber());
        System.out.println("isPalindrome: " + result.isPalindrome());
        System.out.println("isPrime: " + result.isPrime());
    }
}

