func circularShift(_ x: Int, _ shift: Int) -> Int {
    var lengthOfX = 0, result = 0
    var tempX = x
    while tempX != 0 {
        tempX /= 10
        lengthOfX += 1
    }

    if shift >= lengthOfX {
        var x = x
        while x != 0 {
            result = result * 10 + x % 10
            x /= 10
        }
    } else {
        let rightPart = x % Int(pow(10.0, Double(shift)))
        let leftPart = x / Int(pow(10.0, Double(shift)))
        let multiplier = Int(pow(10.0, Double(lengthOfX-shift)))
        result = rightPart * multiplier + leftPart
    }
    return result
}

print(circularShift(12, 1))  // Output: 21
print(circularShift(12, 2))  // Output: 12
```

The main difference is we are using division `/` and modulo `%` operators directly since Swift does not have `//` operator as in Python for integer division. Also, Swift uses `pow()` function for exponentiation instead of Python's `**`.

Another important difference is that Swift is a strongly typed language. This means that you have to explicitly convert integers to floating-point numbers when they are going to be used with floating-point functions such as `pow()`. And you have to convert the result back to an integer using `Int()`.

