import java.util.ArrayList;
import java.lang.Math;

public class Main {
    public static void main(String[] args) {
        System.out.println(digits(123456));
    }

    public static int digits(int n) {
        String stringN = Integer.toString(n);       

        ArrayList<Integer> odd = new ArrayList<>();
        ArrayList<Integer> even = new ArrayList<>();

        // for each digit in the number 'n'
        for (char c : stringN.toCharArray()) {
            int value = Character.getNumericValue(c);
            // Check if character is odd and add to list
            if (value % 2 != 0)
                odd.add(value);
            // Check if character is even and add to list
            else
                even.add(value);
        }

        int sumOddFactorial = 0;
        // For each odd number, find the factorial and add to sumOddFactorial
        for (int i : odd)
            sumOddFactorial += factorial(i);

        int sumEvenSquared = 0;
        // For each even number, find the square and add to sumEvenSquared
        for (int i : even)
            sumEvenSquared += Math.pow(i, 2);

        // Depending on the presence of odd or even numbers, return a specific result
        if (even.isEmpty())
            return factorial(odd.get(0));
        else if (odd.isEmpty())
            return (int) Math.sqrt(even.get(0) * even.get(1));
        else
            return sumOddFactorial + sumEvenSquared;
    }

    // Recursive method to calculate factorial of a number
    public static int factorial(int f) {
        if (f == 0)
            return 1;
        else
            return f * factorial(f - 1);
    }
}
```

**Note**

* In Java, you have to define your own factorial method, because `Math.factorial()` is not available as in Python.
* Instead of using `len()`, Java uses `isEmpty()` to check if a list is empty or not.
