Circular linked list is quite similar to the singly linked list. The only difference is the last node of the linked list points to the first node, forming a loop. Let us build a Java program to traverse the list. Here is the code:

```java
import java.util.Scanner; 

class Node {
    int data;
    public Node next;

    public Node(int data) {
        this.data = data;
    }
}

public class CircularLinkedList {
    Node head, tail;
    int size;

    public CircularLinkedList() {
        head = null;
        tail = null;
        size = 0;
    }

    public void addNode(int data) {
        Node newNode = new Node(data);

        if (head == null) {
            head = newNode;
        } else {
            tail.next = newNode;
        }

        tail = newNode;
        tail.next = head;
        size++;
    }

    public void traversal(int start) {
        Node current = head;

        if (head == null) {
            System.out.println("The list is empty");
            return;
        } else {
            //skip to the start node
            for (int i = 0; i < start; i++) {
                current = current.next;
            }
            System.out.println("\nNodes of the circular linked list starting from node " + start + ": ");

            for (int i = 0; i < size; i++) {
                System.out.print(current.data + " ");
                current = current.next;
            }
            System.out.println();
        }
    }

    public static void main(String[] args) {
        CircularLinkedList list = new CircularLinkedList();
        Scanner scanner = new Scanner(System.in); 

        list.addNode(1);
        list.addNode(2);
        list.addNode(3);
        list.addNode(4);
        list.addNode(5);

        System.out.println("Enter starting node: ");
        int startNode = scanner.nextInt();  

        list.traversal(startNode);
        scanner.close(); 
    }
}
```
