Here is a basic implementation of the Red-Black Tree in Rust:

```rust
pub enum Color {
    Red,
    Black,
}

pub struct Node<T> {
    color: Color,
    value: T,
    left: Option<Box<Node<T>>>,
    right: Option<Box<Node<T>>>,
}

impl<T: Ord> Node<T> {
    fn new(v: T) -> Node<T> {
        Node {
            color: Color::Black,
            value: v,
            left: None,
            right: None,
        }
    }

    fn insert(&mut self, v: T) {
        match self.value.cmp(&v) {
            std::cmp::Ordering::Equal => return, // Do not allow duplicates.
            std::cmp::Ordering::Less => {
                if let Some(right) = &mut self.right {
                    right.insert(v);
                } else {
                    let mut node = Box::new(Node::new(v));
                    node.color = Color::Red;
                    self.right = Some(node);
                }
            }
            std::cmp::Ordering::Greater => {
                if let Some(left) = &mut self.left {
                    left.insert(v);
                } else {
                    let mut node = Box::new(Node::new(v));
                    node.color = Color::Red;
                    self.left = Some(node);
                }
            }
        }
    }
}

pub struct RBTree<T> {
    root: Option<Box<Node<T>>>,
}

impl<T: Ord> RBTree<T> {
    pub fn new() -> RBTree<T> {
        RBTree { root: None }
    }

    pub fn insert(&mut self, v: T) {
        if let Some(root) = &mut self.root {
            root.insert(v);
        } else {
            self.root = Some(Box::new(Node::new(v)));
        }
    }
}
```

