```java
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class UppercaseTransformer {

    // Create ExecutorService for handling multi-threading
    private ExecutorService executor = Executors.newFixedThreadPool(5);

    public List<String> transform(List<String> input) {
        List<Future<String>> futures = input.stream()

                // For each string in list, start a new Callable task to convert it to uppercase
                .map(str -> executor.submit(() -> str.toUpperCase()))

                // Collect all futures to a list
                .collect(Collectors.toList());

        return futures.stream().map(future -> {
            try {
                // Wait for task to be done and return result
                return future.get();
            } catch (InterruptedException | ExecutionException e) {
                throw new RuntimeException(e);
            }
        }).collect(Collectors.toList());
    }

    public void shutdown() {
        // Always shut down executor service
        executor.shutdown();
    }

    public static void main(String[] args) {
        List<String> strings = Arrays.asList("Hello World", "hello", "world");
        UppercaseTransformer transformer = new UppercaseTransformer();
        List<String> result = transformer.transform(strings);
        result.forEach(System.out::println);
        transformer.shutdown();
    }
}
