const rp = require('request-promise');

class CouchDB {
  constructor(url, dbName) {
    this.url = `${url}/${dbName}`;
  }

  readDocument(docID) {
    let options = {
      uri: `${this.url}/${docID}`,
      json: true
    };
    return rp(options);
  }

  createDocument(doc, id) {
    let options = {
      method: 'PUT',
      uri: `${this.url}/${id}`,
      body: doc,
      json: true
    };
    return rp(options);
  }

  updateDocument(docID, doc) {
    return this.readDocument(docID).then((body) => {
      let options = {
        method: 'PUT',
        uri: `${this.url}/${docID}`,
        body: { ...body, ...doc },
        json: true
      };
      return rp(options);
    });
  }

  deleteDocument(docID) {
    return this.readDocument(docID).then((body) => {
      let options = {
        method: 'DELETE',
        uri: `${this.url}/${docID}?rev=${body._rev}`,
      };
      return rp(options);
    });
  }
}

module.exports = CouchDB;
