    if not re.fullmatch(hex_regex, hex_str) or not re.fullmatch(length_regex, hex_str):
        return res

    # Conversion from hexadecimal to decimal
    decimal = 0
    for i in range(2, len(hex_str)):
        if '0' <= hex_str[i] <= '9':
            decimal = decimal * 16 + ord(hex_str[i]) - ord('0')
        elif 'A' <= hex_str[i] <= 'F':
            decimal = decimal * 16 + ord(hex_str[i]) - ord('A') + 10
        else:
            decimal = decimal * 16 + ord(hex_str[i]) - ord('a') + 10

    # Conversion from decimal to binary
    binary = '0b' + bin(decimal)[2:]

    # Inserting results in the dictionary
