Below is a simple implementation of the described command-line tool. The tool doesn't perform actual voting on git commits, but simulates the concept by using a python dictionary. In a real-life scenario, you would use a service to hold all the votes and make API calls instead. 

This tool is named 'gitvote.py' and uses the argparse library to parse the command-line arguments.

```python
#!/usr/bin/env python

import argparse
import subprocess

votes = {}

def vote(commit):
    if commit in votes:
        votes[commit] += 1
    else:
        votes[commit] = 1

def list_votes():
    for commit, vote in votes.items():
        print(f'{commit}: {vote}')

def tally_votes():
    total_votes = 0
    for vote in votes.values():
        total_votes += vote
    print(f'Total votes: {total_votes}')

def elect_commit():
    max_votes = max(votes.values())
    elected_commits = [k for k, v in votes.items() if v == max_votes]
    print('Elected commit(s):')
    for commit in elected_commits:
        print(commit)

def main():
    parser = argparse.ArgumentParser(description='Vote on GIT commits.')
    subparsers = parser.add_subparsers(dest='command')

    vote_parser = subparsers.add_parser('vote', help='Vote for a commit')
    vote_parser.add_argument('commit', help='The commit to vote for')

    subparsers.add_parser('list', help='List all votes')

    subparsers.add_parser('tally', help='Tally all votes')

    subparsers.add_parser('elect', help='Elect a commit')

    args = parser.parse_args()

    if args.command == 'vote':
        vote(args.commit)
    elif args.command == 'list':
        list_votes()
    elif args.command == 'tally':
        tally_votes()
    elif args.command == 'elect':
        elect_commit()

if __name__ == '__main__':
    main()
```

