import random

def median(l: list):
    n = len(l)

    def quickselect(l, start, end, k):
        # Returns the kth smallest element in list_in start_end
        if start == end:  # If the list contains only one element
            return l[start]

        pivot_index = random.randint(start, end)  # Choose a random pivot
        pivot_index = partition(l, start, end, pivot_index)
        # The pivot is in its final sorted_position
        if k == pivot_index:
            return l[k]
        elif k < pivot_index:
            return quickselect(l, start, pivot_index - 1, k)
        else:  
            return quickselect(l, pivot_index + 1, end, k)

    def partition(l, start, end, pivot_index):
        # Moves the pivot element to end
        l[pivot_index], l[end] = l[end], l[pivot_index]
        # Puts elements less than pivot on left of pivot
        store_index = start
        for i in range(start, end):
            if l[i] < l[end]:
                l[store_index], l[i] = l[i], l[store_index]
                store_index += 1
        # Moves pivot to its final place
        l[end], l[store_index] = l[store_index], l[end]
        return store_index

    if n % 2 == 1:  # There's an odd number_of elements => one single median
        return quickselect(l, 0, n - 1, n // 2)
    else:  # Even number of elements => average of middle two
        return 0.5 * (quickselect(l, 0, n - 1, n // 2 - 1) +
                       quickselect(l, 0, n - 1, n // 2))

