function SlideTextAnimation(elementId, speed) {
    // Check if the element exists
    var element = document.getElementById(elementId);
    if(!element) {
        throw "Unable to find element with id: " + elementId;
    }

    this.element = element;
    this.speed = speed;
    this.direction = 1;
    this.pos = 0;

    var that = this;

    this.start = function() {
        // Get the width of the text and the div
        var textWidth = element.offsetWidth;
        var parentWidth = element.parentNode.offsetWidth;

        // If the text has reached the end, bounce back by reversing direction
        if(this.pos + textWidth >= parentWidth || this.pos < 0) {
            this.direction *= -1;
        }

        // Increase position
        this.pos += this.speed * this.direction;

        // Move the text
        this.element.style.left = this.pos + 'px';

        // Continue the animation
        this.timerId = setTimeout(function() { that.start(); }, 20);
    };

    this.pause = function() {
        // Pause animation
        clearTimeout(this.timerId);
    };

    // Add event listener to start and pause the animation on mouseover and mouseout
    this.element.addEventListener('mouseover', function() { that.start(); });
    this.element.addEventListener('mouseout', function() { that.pause(); });

