func RoundedAvg(n int, m int) string {
    if n > m {
        return "-1"
    }

    sum := 0
    count := 0
    for i := n; i <= m; i++ {
        sum += i
        count++
    }

    avg := float64(sum) / float64(count)
    roundedAvg := int(avg + 0.5) // adding 0.5 before conversion rounds to the nearest integer

    binaryAvg := strconv.FormatInt(int64(roundedAvg), 2)

    return "0b" + binaryAvg
}

