// Function to perform circular shift
void circularShift(std::vector<int> &arr, int k) {
    if (arr.empty()) {
        std::cout << "The array is empty. No shift operation can be performed.\n";
        return;
    }

    if (k < 0) {
        std::cout << "Invalid shift number. Shift number must be greater than or equal to zero.\n";
        return;
    }

    k %= arr.size(); // To handle shift values larger than the size of array

    if (k > 0) {
