```csharp
using System;
using System.Net;
using System.Net.Sockets;
using System.Threading;

public class Server
{
    private TcpListener _server;
    private bool _isRunning;

    public Server(int port)
    {
        _server = new TcpListener(IPAddress.Any, port);
        _server.Start();

        _isRunning = true;

        LoopClients();
    }

    public void LoopClients()
    {
        while (_isRunning)
        {
            // wait for client connection
            TcpClient newClient = _server.AcceptTcpClient();

            // client found.
            // create a thread to handle communication
            ThreadPool.QueueUserWorkItem(HandleClient, newClient);
        }
    }

    public void HandleClient(object obj)
    {
        // retrieve client from parameter passed to thread
        TcpClient client = (TcpClient)obj;

        // sets two streams
        StreamWriter sWriter = new StreamWriter(client.GetStream(), Encoding.ASCII);
        StreamReader sReader = new StreamReader(client.GetStream(), Encoding.ASCII);
        bool bClientConnected = true;
        string sData = null;

        while (bClientConnected)
        {
            // reads from stream
            sData = sReader.ReadLine();

            // shows content on the console.
            Console.WriteLine("Client says: " + sData);

            // to write something back.
            sWriter.WriteLine("Server says: " + sData);
            sWriter.Flush();
        }
    }
}
```

The ThreadPool class in C# is a pool of threads that can be used to execute tasks, post work items, process asynchronous I/O, wait on behalf of other threads, and process timers.

The TcpListener.AcceptTcpClient() method is synchronous and will block until a client connects. When that happens, the method returns with a TcpClient object that you can use to communicate with the client. 

