Here is an implementation of quicksort algorithm that uses a median of three partitioning method for selecting the pivot, with an array as the middle element, the first element and the last element. 

```python
def partition(arr, low, high):
    pivot = arr[low]
    i = low + 1
    j = high

    while True:
        while i <= j and arr[i] <= pivot:
            i = i + 1
        while i <= j and arr[j] >= pivot:
            j = j - 1
        if i <= j:
            arr[i], arr[j] = arr[j], arr[i]
        else:
            break

    arr[low], arr[j] = arr[j], arr[low]
    return j

def quick_sort(arr, low, high):
    if low < high:
        mid = median_of_three(arr, low, high)
        arr[low], arr[mid] = arr[mid], arr[low]
        pivot_index = partition(arr, low, high)
        quick_sort(arr, low, pivot_index - 1)
        quick_sort(arr, pivot_index + 1, high)

def median_of_three(arr, low, high):
    mid = (low + high) // 2
    if arr[low] < arr[mid]:
        if arr[mid] < arr[high]:
            return mid
        if arr[low] < arr[high]:
            return high
    else:
        if arr[low] < arr[high]:
            return low
        if arr[mid] < arr[high]:
            return high
    return mid

arr = [1, 9, 4, 6, 5, 8, 2]
quick_sort(arr, 0, len(arr) - 1)
print ("Sorted array: ", arr)
```

This implementation also uses the Hoare partition scheme, in which the pivot value is placed in its correct position and the lists are partitioned accordingly. This implementation also takes into account the possibility of repeated elements in the list.

The key idea behind the use of the median of three pivot selection is to provide a good pivot without the cost of sorting the entire array. This typically results in both faster and more stable performance than simple pivot selection methods like always choosing the first or last element.

Python provides great capabilities in terms of designing such programs. Here is a detailed implementation of Monte Carlo Tic Tac Toe simulation:

```python
import random

# Initializing the board
def create_board():
    return [' ' for _ in range(9)]

# Check if a player has won
def check_for_win(board, marker):
    win_cases = [[0, 1, 2], [3, 4, 5], [6, 7, 8], [0, 3, 6], [1, 4, 7], [2, 5, 8], [0, 4, 8], [2, 4, 6]]
    for case in win_cases:
        if board[case[0]] == board[case[1]] == board[case[2]] == marker:
            return True
    return False

# Choosing the next move
def get_move(board, player):
    choices = [i for i in range(9) if board[i] == ' ']
    # heuristic: if we can win, then win
    for choice in choices:
        temp_board = board[:]
        temp_board[choice] = player
        if check_for_win(temp_board, player):
            return choice
    # heuristic: if opponent can win, block them
    if player == 'X':
        opponent = 'O'
    else:
        opponent = 'X'
    for choice in choices:
        temp_board = board[:]
        temp_board[choice] = opponent
        if check_for_win(temp_board, opponent):
            return choice
    # else, choose randomly
    return random.choice(choices)

# Play a full game
def play_game():
    board = create_board()
    current_player = ['X', 'O'][randrange(2)]
    while ' ' in board:
        move = get_move(board, current_player)
        board[move] = current_player
        if check_for_win(board, current_player):
            return current_player
        current_player = 'X' if current_player == 'O' else 'O'
    # It's a draw
    return None

# Monte Carlo simulation
def monte_carlo_sim(n):
    x_wins = o_wins = draws = 0
    for _ in range(n):
        result = play_game()
        if result == 'X':
            x_wins += 1
        elif result == 'O':
            o_wins += 1
        else:
            draws += 1
    print(f"After {n} games, X won {x_wins} times, O won {o_wins} times, and there were {draws} draws.")

# Run the simulation
monte_carlo_sim(10000)
```
The simulation iterates over several games by switching the players randomly. It uses a Monte Carlo method to select moves: if a winning move exists, take it; if an opponent's winning move exists, block it; else, move randomly. The results over numerous games are then presented.

