            raise IndexError('Index out of range')
        return self.text[index]


class AdvancedStringAnalyzer(StringAnalyzer):
    def __init__(self, text):
        super().__init__(text)
        self.char_counts = self.calculate_frequencies()

    def calculate_frequencies(self):
        counts = {}
        for char in self.text:
            if char in counts:
                counts[char] += 1
            else:
                counts[char] = 1
        return counts

    def get_frequency(self, letter):
        if not isinstance(letter, str) or len(letter) != 1:
            raise ValueError('Input must be a single character')
        return self.char_counts.get(letter, 0)
