function reverse_even($s) {
    $s = str_split($s); // Convert string to array
    $even_chars = [];
    $odd_chars = [];

    // Separate characters at even and odd positions
    foreach ($s as $i => $ch) {
        if ($i % 2 == 0) {
            array_push($even_chars, $ch);
        } else {
            array_push($odd_chars, $ch);
        }
