        word1 = word1.toLowerCase();
        word2 = word2.toLowerCase();

        // convert strings to char array
        char[] chars1 = word1.toCharArray();
        char[] chars2 = word2.toCharArray();

        // sort the char array
        Arrays.sort(chars1);
        Arrays.sort(chars2);

        // compare sorted char arrays
        return Arrays.equals(chars1, chars2);
    }
}
