```python
import colorsys
import binascii

def rgb_to_hex(rgb):
    return '#%02x%02x%02x' % rgb

def hex_to_rgb(hex_color):
    hex_color = hex_color.lstrip('#')
    rgb = tuple(int(hex_color[i:i+2], 16) for i in (0, 2, 4))
    return rgb

def cmyk_to_rgb(cmyk):
    c, m, y, k = cmyk 
    r = 255 * (1-c) * (1-k)
    g = 255 * (1-m) * (1-k)
    b = 255 * (1-y) * (1-k)
    return (r,g,b)

def hsl_to_rgb(hsl):
    h, s, l = hsl
    h /= 360
    s /= 100
    l /= 100
    return tuple(round(i * 255) for i in colorsys.hls_to_rgb(h, l, s))

def rgb_to_hsl(rgb):
    r, g, b = rgb
    r /= 255
    g /= 255
    b /= 255
    h, l, s = colorsys.rgb_to_hls(r, g, b)
    return (h * 360, s * 100, l * 100)

def convert_color(color, to_hex=True, color_model='rgb'):
    if color_model == 'rgb':
        if to_hex:
            return rgb_to_hex(color)
        else:
            return hex_to_rgb(color)
    elif color_model == 'cmyk':
        if to_hex:
            color = cmyk_to_rgb(color)
            return rgb_to_hex(color)
    elif color_model == 'hsl':
        if to_hex:
            color = hsl_to_rgb(color)
            return rgb_to_hex(color)
        else:
            color = hex_to_rgb(color)
            return rgb_to_hsl(color)

print(convert_color((0.5, 0.25, 0.0, 0.2),color_model='cmyk')) # Convert CMYK to HEX
print(convert_color((255, 0, 0),color_model='rgb')) # Convert RGB to HEX
print(convert_color((0, 100, 50),color_model='hsl')) # Convert HSL to HEX
print(convert_color('#ff0000',to_hex=False,color_model='rgb')) # Convert HEX to RGB
print(convert_color('#ff0000',to_hex=False,color_model='hsl')) # Convert HEX to HSL
```
Note: This program assumes standard inputs for each of the color models: (0.0-1.0, 0.0-1.0, 0.0-1.0, 0.0-1.0) for CMYK, (0-255, 0-255, 0-255) for RGB, and (0-360, 0-100, 0-100) for HSL.

