bool below_threshold(const std::vector<int>& numbers, int threshold) {
    // Check if threshold is non-positive
    if (threshold <= 0)
        throw std::invalid_argument("Threshold must be a positive integer");

    // Check if list is empty
    if (numbers.empty())
