} Node;

// Function to create a new node
Node* newNode(int v, int x, int y) {
    Node* node = malloc(sizeof(Node));
    node->cost = v;
    node->x = x;
    node->y = y;
    return node;
}

// Comparing two nodes by their cost
int cmp(const void * a, const void * b) {
   Node *nodeA = *(Node **)a;
   Node *nodeB = *(Node **)b;
   return nodeA->cost - nodeB->cost;
}

void add(Node **arr, int *len, Node *node) {
    arr[*len] = node;
    (*len)++;
    qsort(arr, *len, sizeof(Node*), cmp);
}

Node* pop(Node ***arr, int *len) {
    Node *lastNode = (*arr)[*len - 1];
    (*len)--;
    return lastNode;
}

// Function to find the minimum path with k nodes
int* minPath(int grid[N][N], int k) {
    int N = sizeof(grid[0]); // size of the grid
    Node **indices = malloc(sizeof(Node*) * N * N);

    int path[N*N];
    for(int i = 0; i < N*N; i++)
        path[i] = grid[0][0];

    bool visited[N][N];
    for(int i = 0; i < N; i++)
        for(int j = 0; j < N; j++)
            visited[i][j] = false;

    int len = 0;
    add(indices, &len, newNode(grid[0][0], 0, 0));
    visited[0][0] = true;

    while(len > 0) {
        Node* current = pop(&indices, &len);

        if (current->cost == k)
            return path;

        // Moving to all possible directions
        int dx[] = {-1, 0, 1, 0};
        int dy[] = {0, 1, 0, -1};

        for (int i = 0; i < 4; i++) {
            int nx = current->x + dx[i], ny = current->y + dy[i];

            if (nx >= 0 && nx < N && ny >= 0 && ny < N && !visited[nx][ny]) {
                visited[nx][ny] = true;
                int new_cost = current->cost + grid[nx][ny];
                add(indices, &len, newNode(new_cost, nx, ny));
                path[len-1] = new_cost;
            }
        }
    }

    free(indices);
    return NULL; // return NULL if there's no path
}
