```cpp
#include <iostream>
#include <cmath>
#include <map>

enum RoundingMethod {
    TRADITIONAL,
    BANKERS,
    STATISTICIAN
};

class ExtractInteger {
public:
    ExtractInteger() {
        mapping["traditional"] = TRADITIONAL;
        mapping["bankers"] = BANKERS;
        mapping["statistician"] = STATISTICIAN;
    }

    std::tuple<int, double, bool> operator()(double number, bool round = true, int precision = 2, std::string method = "traditional") {
        RoundingMethod roundingMethod = mapping.count(method) ? mapping[method] : TRADITIONAL;

        int quotient = static_cast<int>(number);
        double remainder = number - quotient;

        if (!round)
            return std::make_tuple(quotient, remainder, false);

        double roundedRemainder = roundDecimal(remainder, precision, roundingMethod);
        if (roundedRemainder >= 0.5) {
            roundedRemainder -= 1;
            quotient += 1;
        }

        return std::make_tuple(quotient, roundedRemainder, (bool)quotient);
    }
private:
    std::map<std::string, RoundingMethod> mapping;

    double roundDecimal(double number, int precision, RoundingMethod roundingMethod) {
        double factor = std::pow(10, precision);
        double val = number * factor;

        switch (roundingMethod) {
        case TRADITIONAL:
            val = std::round(val);
            break;
        case BANKERS:
            val = std::nearbyint(val); // Banker's rounding
            break;
        case STATISTICIAN:
            val = std::floor(val + 0.5);
            break;
        default:
            break;
        }

        return val / factor;
    }
};

int main() {
    ExtractInteger extractInteger;
    int quotient;
    double remainder;
    bool nonZero;

    std::tie(quotient, remainder, nonZero) = extractInteger(12.34);
    std::cout << quotient << ", " << remainder << ", " << nonZero << std::endl;

    return 0;
}
```

It should be noted that C++ does not natively support all rounding modes specified in Python's Decimal package. In particular, Python's `ROUND_HALF_DOWN` (round towards zero) is not directly supported in C++. `std::round` is used for `ROUND_HALF_UP` (traditional rounding), `std::nearbyint` is used for `ROUND_HALF_EVEN` (banker's rounding), and `std::floor(val + 0.5)` is used for `ROUND_HALF_DOWN`. This assumes that `number` is positive; for negative numbers, you'd want to use `std::ceil(val - 0.5)` instead of `std::floor(val + 0.5)`.

