use Algorithm::Permute;

sub match_brackets {
    my ($lst) = @_;
    my %brackets = ('(' => ')', '[' => ']', '{' => '}');

    my $p = new Algorithm::Permute($lst);

    while (my @perm = $p->next) {
        my @stack;
        PERM_LOOP: for my $string (@perm) {
            for my $character (split //, $string) {
                if (exists $brackets{$character}) {
                    push @stack, $character;
                } elsif (@stack and $character eq $brackets{$stack[-1]}) {
                    pop @stack;
                } else {
