import java.util.Stack;

public class Main {
  public static boolean validateBrackets(String str) {
    Stack<Character> stack = new Stack<>();

    for (char c : str.toCharArray()) {
      if (c == '(' || c == '[' || c == '{') {
        stack.push(c);
      } else if (c == ')' || c == ']' || c == '}') {
        if (stack.isEmpty()) {
          return false;
        }

        char bracketOpened = stack.pop();   
        if (c == ')' && bracketOpened != '(' || 
            c == ']' && bracketOpened != '[' ||
            c == '}' && bracketOpened != '{') {
          return false;
        }
      }
    }

    return stack.isEmpty();
  }

  public static void main(String[] args) {
    // Test cases
    System.out.println(validateBrackets("()"));       // Output: true
    System.out.println(validateBrackets("[]"));       // Output: true
    System.out.println(validateBrackets("{}"));       // Output: true
    System.out.println(validateBrackets("{[]}()"));   // Output: true
    System.out.println(validateBrackets("[({})]"));   // Output: true
