    return count;
}

// Comparison function for qsort. It sorts the array based on the lengths of binary
// representations of numbers and then by their decimal values if the lengths are the same.
int compare(const void* a, const void* b) {
    int size_a = count_bin_len(*(int*)a);
    int size_b = count_bin_len(*(int*)b);

    // First try to sort based on the lengths of binary representations
    if (size_a > size_b)
        return 1;
    if (size_a < size_b)
        return -1;

    // If binary lengths are same, sort by their decimal values
    if (*(int*)a > *(int*)b)
        return 1;
    if (*(int*)a < *(int*)b)
        return -1;

    // Both binary length and decimal value are same for the two numbers
    return 0;
}

void sort_by_binary_len(int arr[], int n) {
    qsort(arr, n, sizeof(int), compare);
}

// This function prints the contents of 'arr'
void print_array(int arr[], int n) {
