  if (typeof num1 !== 'number' || typeof num2 !== 'number' || typeof num3 !== 'number') {
    return 'Input must be numeric.';
  }

  if (num1 === 0 || num2 === 0 || num3 === 0) {
    return 'Input must not be zero.';
  }

