import java.util.*;

public class PrimeNumberHelper {

    // This function checks whether a number is prime or not.
    private boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }
        for (int i = 3; i * i <= n; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }

    // This function returns sum of all prime number under 'n'
    public int sumOfPrimes(int n) {
        int sum = 0;
        for (int i = 2; i <= n; i++) {
            if (isPrime(i)) {
                sum += i;
            }
        }
        return sum;
    }

    // This function returns the 'n-th' prime number
    public int nthPrime(int n) {
        int count = 0;
        int num = 1;
        while (count < n) {
            num++;
            if (isPrime(num)) {
                count++;
            }
        }
        return num;
    }

    // main method to debug the application
    public static void main(String[] args) {
        PrimeNumberHelper helper = new PrimeNumberHelper();
        System.out.println("Sum of primes under 10: " + helper.sumOfPrimes(10));
        System.out.println("5th prime number is: " + helper.nthPrime(5));
    }
}
