            arr[swap_with[1]], arr[index - 1] = arr[index - 1], arr[swap_with[1]]
            total_swaps += 1
            return {
                'index': index,
                'swap_with': swap_with[1],
                'total_swaps': total_swaps,
            }

    return {'index': -1, 'swap_with': -1, 'total_swaps': 0}

