  while (low <= high) {
    let mid = low + Math.floor((high - low) / 2);
    if (arr[mid] === x) {
      return mid;
    }
    else if (arr[mid] < x) {
      low = mid + 1;
    }
    else {
      high = mid - 1;
    }
