    target = (sum1 + sum2) // 2
    for num in lst1:
        if (sum1 - num + sum2) % 2 == 0 and (sum1 - num) <= target:
            sum1 -= num
            lst1.remove(num)
            break
    for num in lst2:
        if (sum1 + num) % 2 == 0 and (sum1 + num) <= target:
            sum1 += num
            lst2.remove(num)
            break

    while sum1 != target:
        moved = False
        for num in lst1:
            if (sum1 - num) % 2 == 0 and (sum1 - num) <= target:
                sum1 -= num
                lst1.remove(num)
                moved = True
                break
        if not moved:
            return "NO"

        for num in lst2:
            if (sum1 + num) % 2 == 0 and (sum1 + num) <= target:
                sum1 += num
                lst2.remove(num)
                moved = True
                break
        if not moved:
