    <script>
        const text = document.getElementById("text");
        const agree = document.getElementById("agree");
        const disagree = document.getElementById("disagree");
        const resetBtn = document.getElementById("resetBtn");

        let storedSelection = localStorage.getItem("agreeDisagree");

        if (storedSelection) {
            if (storedSelection === "agree") {
                agree.checked = true;
                text.style.color = "green";
            } else if (storedSelection === "disagree") {
                disagree.checked = true;
                text.style.color = "red";
            }
        }

        agree.addEventListener("change", function () {
            localStorage.setItem("agreeDisagree", "agree");
            text.style.color = "green";
        });

        disagree.addEventListener("change", function () {
            localStorage.setItem("agreeDisagree", "disagree");
            text.style.color = "red";
        });

        resetBtn.addEventListener("click", function () {
            localStorage.removeItem("agreeDisagree");
            text.style.color = "black";
            agree.checked = false;
            disagree.checked = false;
        });
    </script>
</body>
</html>
```

