Here is a simple example:

```csharp
public string FormatDataTableToText(DataTable dt)
{
    StringBuilder sb = new StringBuilder();

    // Find the max length of output for each Column
    int[] maxLengths = new int[dt.Columns.Count];
    for(int i=0; i<dt.Columns.Count; i++){
        maxLengths[i] = dt.Columns[i].ColumnName.Length;

        foreach(DataRow row in dt.Rows){
            if(!row.IsNull(i)){
                int length = row[i].ToString().Length;

                if(length > maxLengths[i]){
                    maxLengths[i] = length;
                }
            }
        }
    }

    // Generate the output
    for(int i=0; i<dt.Columns.Count; i++){
        sb.Append(dt.Columns[i].ColumnName.PadRight(maxLengths[i]) + " ");
    }
    sb.AppendLine();

    foreach(DataRow row in dt.Rows){
        for(int i=0; i<dt.Columns.Count; i++){
            if(!row.IsNull(i)){
                sb.Append(row[i].ToString().PadRight(maxLengths[i]) + " ");
            } else {
                sb.Append(new string(' ', maxLengths[i]) + " ");
            }
        }
        sb.AppendLine();
    }
    return sb.ToString();
}
```

