```javascript
const { Pool } = require('pg');  // Import pg, Node.js PostgreSQL client

// Set up pool configuration
const pool = new Pool({
  user: 'dbuser',
  host: 'localhost',
  database: 'test',
  password: 'secretpassword',
  port: 5432,
});

// Connect to PostgreSQL and execute complex JOIN operation
async function executeJoin() {
  let client;
  try {
    // Get a client from the connection pool
    client = await pool.connect();

    // Start a transaction
    await client.query('BEGIN');

    // Issue complex JOIN SQL query
    const res = await client.query('SELECT users.name, COUNT(orders.id) as order_count FROM users LEFT JOIN orders ON users.id = orders.user_id GROUP BY users.name');

    // After successful operation, commit the transaction
    await client.query('COMMIT');

    // Return results back to the caller
    return res.rows;

  } catch (err) {
    if (client) {
      // Transaction failed. Roll it back.
      await client.query('ROLLBACK');
    }
    console.log(err.stack);
    return { error: err };
  } finally {
    if (client) {
      // Release the client back to the pool
      client.release();
    }
  }
}

// Execute JOIN operation
executeJoin().then((res) => {
  if (!res.error) {
    console.log('Successful join operation. Results: ', res);
  } else {
    console.log('Error occurred during join operation: ', res.error);
  }

  // After results (or error) are logged, gracefully shut down connection pool
  pool.end();
});
```

