Here is an example of a serverless function in Go language on AWS Lambda:

```Go
package main

import (
    "context"

    "github.com/aws/aws-lambda-go/lambda"
    "github.com/aws/aws-lambda-go/events"
    "github.com/aws/aws-sdk-go/aws"
    "github.com/aws/aws-sdk-go/aws/session"
    "github.com/aws/aws-sdk-go/service/s3/s3manager"
    "encoding/json"
    "bytes"
)

// Struct for IoT Telemetry data
type IOTData struct {
    DeviceID  string `json:"device_id"`
    Temp      float64 `json:"temp"`
    Humidity  float64 `json:"humidity"`
    Timestamp string `json:"timestamp"`
}

func HandleRequest(ctx context.Context, snsEvent events.SNSEvent) {
    for _, record := range snsEvent.Records {
        snsRecord := record.SNS
        var data IOTData
        err := json.Unmarshal([]byte(snsRecord.Message), &data)
        if err != nil {
            // handle error
        }

        convertAndStore(data)
    }
}

func convertAndStore(data IOTData) {
    // Create a session using SharedConfigEnable
    sess, _ := session.NewSession(&aws.Config{
        Region: aws.String("us-west-2")},
    )

    var bucket = "bucketname"    // The S3 Bucket to which to Upload the file. 
    var item = "iotdata.json"  // The name of the object to put to S3 bucket.

    jsonString, _ := json.Marshal(data)
    // Upload the file to S3.
    err := AddFileToS3(sess, bucket, item, jsonString)
    if err != nil {
        // handle error
    }
}

func AddFileToS3(s *session.Session, bucketName string, itemName string, body []byte) error {
    uploader := s3manager.NewUploader(s)
    _, err := uploader.Upload(&s3manager.UploadInput{
        Bucket: aws.String(bucketName),
        Key:    aws.String(itemName),
        Body:   bytes.NewReader(body),
    })
    if err != nil {
        return err
    }
    return nil
}

func main() {
    lambda.Start(HandleRequest)
}
```

