#include <iostream>                                  // For input/output stream operations
#include <vector>                                    // For to create dynamic arrays
#include <string>                                    // To use string datatype 

std::pair<int,int> calculate(std::vector<int> numbers, std::string operation) 
{
    int evenResult = 0, oddResult = 0;               // Declare variables to store results

    if(operation == "squares")                      // For squares operation
    {
        for(int num : numbers)                      // Loop through all numbers
        {
            if(num % 2 == 0)                         // If number is even 
                evenResult += num * num;             // Add its square to even result
            else                                    // If its odd 
                oddResult += num * num;              // Add its square to odd result
        }
    }    
    else if(operation == "cubes")                    // For cubes operation
    {
        evenResult = oddResult = 1;                  // Initialize results to 1
        for(int num : numbers)                       // Loop through all numbers
        {
            if(num % 2 == 0)                         // If number is even
                evenResult *= num * num * num;       // Multiply it's cube to even result
            else                                    // If its odd
                oddResult *= num * num * num;        // Multiply it's cube to odd result
        }
        if(numbers.empty())                          // In case of no numbers
            return std::make_pair(1, 1);             // Return 1 for both results
    }
    else                                             // Default case (invalid operation)
        return std::make_pair(0, 0);                 // Return 0 for both results

    return std::make_pair(evenResult, oddResult);    // Return final result
}

int main()
{
    std::vector<int> numbers = {1, 2, 3, 4};         // Define numbers vector
