// CheckedEle struct to enforce integer type and remember original index.
type CheckedEle struct {
	Val      int
	Original int
}

func sortEven(l []interface{}) ([]int, error) {
	// Type checking and creating corresponding slice of CheckedEle.
	list := make([]CheckedEle, 0, len(l))
	for i, val := range l {
		if val, ok := val.(int); ok {
			list = append(list, CheckedEle{
				Val:      val,
				Original: i,
			})
		} else {
			return nil, errors.New("All elements of the list should be integers")
		}
	}

	// Sorting odd index elements
	sort.Slice(list[1:], func(i, j int) bool {
		return list[i+1].Val < list[j+1].Val
	})

	// Sorting even index elements by negative and non-negative separately
	sort.Slice(list, func(i, j int) bool {
		if i%2 == 0 && j%2 == 0 {
			return (list[i].Val > list[j].Val && list[i].Val < 0 && list[j].Val < 0) || (list[i].Val < list[j].Val && list[i].Val >= 0 && list[j].Val >= 0)
		}
		return i < j
	})

	// Constructing the final output
	output := make([]int, len(list), len(list))
	for i := range list {
		output[i] = list[i].Val
	}

	return output, nil
}
