aspect Trace {
    pointcut virtual methods() = 0;

    advice execution("% main(...)"): before() {
        cout << "Entering main" << endl;
    }
    advice execution("% main(...)"): after() {
        cout << "Exiting main" << endl;
    }
    advice call(methods()): around() {
