```csharp
using System;

class MainClass {
  public static void Main (string[] args) {
    int[] A = { 2, 3, 4, 10, 40 };
    int element = 10;
    int foundAt = BinarySearch(A, element);

    if (foundAt != -1)
      Console.WriteLine("Element " + element + " found at index " + foundAt);
    else
      Console.WriteLine("Element " + element + " not found in the array.");
  }

  public static int BinarySearch(int[] array, int target) {
    int left = 0;
    int right = array.Length - 1;

    while (left <= right) {
      int mid = (left + right) / 2;

      if (array[mid] == target) {
        return mid;
      }

      if (array[mid] < target) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }

    return -1;
  }
}
```

