import math

class PrimeFactors(object):        
    def calculate_frequency(self, n):
        result = dict()
        # Divide n by 2 to find a number of 2's that divide n
        while n % 2 == 0:
            if 2 in result:
                result[2] += 1
            else:
                result[2] = 1
            n = n / 2
        # n must be odd at this point 
        for i in range(3,int(math.sqrt(n))+1,2):            
            # while i divides n, divide n
