from google.cloud import storage

class GCSClient:
    def __init__(self, project_id):
        self.client = storage.Client(project_id)

    def upload_file(self, bucket_name, source_file, destination_file):
        try:
            bucket = self.client.bucket(bucket_name)
            blob = bucket.blob(destination_file)

            blob.upload_from_filename(source_file)

            print(f"File {source_file} uploaded to {destination_file}.")
        except Exception as e:
            print(f"An error occurred: {e}")

    def download_file(self, bucket_name, source_file, destination_file):
        try:
            bucket = self.client.bucket(bucket_name)
            blob = bucket.blob(source_file)

            blob.download_to_filename(destination_file)

            print(f"File {source_file} downloaded to {destination_file}.")
        except Exception as e:
            print(f"An error occurred: {e}")

    def list_files(self, bucket_name):
        try:
            blobs = self.client.list_blobs(bucket_name)

            for blob in blobs:
                print(blob.name)
        except Exception as e:
            print(f"An error occurred: {e}")

    def delete_file(self, bucket_name, file_name):
        try:
            bucket = self.client.bucket(bucket_name)
            blob = bucket.blob(file_name)

            blob.delete()

            print(f"File {file_name} deleted.")
        except Exception as e:
            print(f"An error occurred: {e}")

    def rename_file(self, bucket_name, old_file_name, new_file_name):
        try:
            bucket = self.client.bucket(bucket_name)
            blob = bucket.blob(old_file_name)

            bucket.rename_blob(blob, new_file_name)

            print(f"File {old_file_name} has been renamed to {new_file_name}.")
        except Exception as e:
            print(f"An error occurred: {e}")

    def move_file(self, source_bucket_name, destination_bucket_name, file_name):
        try:
            source_bucket = self.client.bucket(source_bucket_name)
            source_blob = source_bucket.blob(file_name)

            destination_bucket = self.client.bucket(destination_bucket_name)

            source_bucket.copy_blob(
                source_blob, destination_bucket, new_name=file_name
            )

            source_blob.delete()

            print(f"File {file_name} moved from {source_bucket_name} to {destination_bucket_name}.")
        except Exception as e:
            print(f"An error occurred: {e}")
