Here's a simple algorithm written in Python:

```python
import itertools

def is_prime(n):
    if n <= 1:
        return False
    elif n <= 3:
        return True
    elif n%2 == 0 or n%3 == 0:
        return False
    i = 5
    while i*i <= n:
        if n%i == 0 or n%(i+2) == 0:
            return False
        i += 6
    return True

def construct_seq(arr, seq=None):
    if seq is None:
        seq = []
    if not arr:  # all elements processed
        return seq if is_prime(sum(seq[-3:])) else None  # check last three elements
    for element in arr:
        new_seq = [*seq, element]
        if len(new_seq) >= 3 and not is_prime(sum(new_seq[-3:])):
            continue  # skip non-prime small sequences
        solution = construct_seq([e for e in arr if e != element], new_seq)
        if solution:
            return solution  # stop on first valid sequence
    return None

def create_sequence(arr):
    if len(arr) < 3: return arr  # not enough elements to create sequence
    # try starting with all possible elements
    for element in arr:
        solution = construct_seq([e for e in arr if e != element], [element])
        if solution:
            return solution  # stop on first valid sequence
    return None


arr = [3, 1, 4, 2, 5, 9, 7, 6, 8]
print(create_sequence(arr))
```

