Lazy Propagation is a technique used in Segment Tree data structure where we postpone the update operation to all the nodes in the segment tree to a later stage. This means that if updates are made to an interval or segment, then the update process is not performed immediately. Instead, we mark that node representing that interval and perform the update when required.

This technique is helpful when there are multiple updates to the same segment simultaneously. It reduces the number of operations and time complexity as we don't update a node until a query is made to that particular node.

Here is the implementation with both range update and range query operations:
```cpp
#include<bits/stdc++.h>
using namespace std;

const int MAX = 100000;
int tree[MAX] = {0}; 
int lazy[MAX] = {0}; 

void updateRangeUtil(int si, int ss, int se, int us, int ue, int diff)
{
    if (lazy[si] != 0)
    {
        tree[si] += (se-ss+1)*lazy[si];
        if (ss != se)
        {
            lazy[si*2 + 1] += lazy[si];
            lazy[si*2 + 2] += lazy[si];
        }
        lazy[si] = 0;
    }
    if (ss>se || ss>ue || se<us)
        return ;
    if (ss>=us && se<=ue)
    {
        tree[si] += (se-ss+1)*diff;
        if (ss != se)
        {
            lazy[si*2 + 1] += diff;
            lazy[si*2 + 2] += diff;
        }
        return;
    }
    int mid = (ss + se)/2;
    updateRangeUtil(si*2+1, ss, mid, us, ue, diff);
    updateRangeUtil(si*2+2, mid+1, se, us, ue, diff);
    tree[si] = tree[si*2+1] + tree[si*2+2];
}

void updateRange(int n, int us, int ue, int diff)
{
   updateRangeUtil(0, 0, n-1, us, ue, diff);
}

int getSumUtil(int ss, int se, int qs, int qe, int si)
{
    if (lazy[si] != 0)
    {
        tree[si] += (se-ss+1)*lazy[si];

        if (ss != se) {
            lazy[si*2 + 1] += lazy[si];
            lazy[si*2 + 2] += lazy[si];
        }
        lazy[si] = 0;
    }
    if (ss>se || ss>qe || se<qs)
        return 0;
    if (ss>=qs && se<=qe)
        return tree[si];
    int mid = (ss + se)/2;
    return getSumUtil(ss, mid, qs, qe, 2*si+1) + getSumUtil(mid+1, se, qs, qe, 2*si+2);
}

int getSum(int n, int qs, int qe)
{
    return getSumUtil(0, n-1, qs, qe, 0);
}

int main()
{
    int arr[] = {1, 3, 5, 7, 9, 11};
    int n = sizeof(arr)/sizeof(arr[0]);
    updateRange(n, 0, 3, 10);
    updateRange(n, 1, 5, 20);
    getSum(n, 1, 3);
    return 0;
}
```
This program shows a Segment Tree implemented with Lazy Propagation. In this program, we perform range updates (add a value to a range of array elements and reflect this in the segment tree) and range queries (find the sum of a range of array elements) in an optimal way. It postpones the updates to a later stage to reduce the number of operations (Lazy Propagation). The updateRange and getSum functions are where you can test this.

