import java.util.Scanner;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.ArrayList;
import java.util.List;

class Tetrahedron {
    private double edge;

    public Tetrahedron(double edge) {
        if (edge <= 0) {
            throw new IllegalArgumentException("Edge length must be positive");
        }
        this.edge = edge;
    }

    public double volume() {
        return edge * edge * edge / (6 * Math.sqrt(2));
    }
}

class TetrahedronVolumeCalculator implements Runnable {
    private Tetrahedron tetrahedron;

    public TetrahedronVolumeCalculator(Tetrahedron tetrahedron) {
        this.tetrahedron = tetrahedron;
    }

    @Override
    public void run() {
        synchronized (System.out) {
            System.out.println("The volume of the tetrahedron with edge " +
                    tetrahedron.getEdge() + " is " + tetrahedron.volume());
        }
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter the number of tetrahedrons:");
        int n = scanner.nextInt();
        ExecutorService executorService = Executors.newFixedThreadPool(n);
        List<Future<?>> futures = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            System.out.println("Enter the edge length of tetrahedron " + (i+1) + ":");
            double edge = scanner.nextDouble();
            if (edge <= 0) {
                System.out.println("Edge length must be positive. Skipping this tetrahedron.");
                continue;
            }
            Tetrahedron tetrahedron = new Tetrahedron(edge);
            Future<?> future = executorService.submit(new TetrahedronVolumeCalculator(tetrahedron));
            futures.add(future);
        }

        for(Future<?> future : futures) {
            try {
                future.get(); 
            } catch (Exception e) {
                e.printStackTrace();
            }
        }

