import math

def binom(n, r):
    if type(n) != int or type(r) != int:
        raise TypeError('Both inputs must be integers')
    if n < 0 or r < 0:
        raise ValueError('Both inputs must be non-negative')
    if n < r:
        raise ValueError('First input must be greater than or equal to second input')

    try:
        return math.factorial(n) // (math.factorial(r) * math.factorial(n - r))
    except OverflowError:
        # For large inputs, use a more efficient calculation
        result = 1
        for i in range(min(r, n - r)):
            result = result * (n - i) // (i + 1)
        return result

print(binom(5, 3))
```

