        }
        quizSum -= minQuizScore;
        grade += (static_cast<double>(quizSum) / (student.quizScores.size()-1)) * 0.3;
    } else if (!student.quizScores.empty()) {
        grade += (static_cast<double>(student.quizScores[0])) * 0.3;
    }

    if (student.hwScores.size() > 1) {
