Below is a simple C++ program that uses array to represent circular queue and supports constant time complexity for enqueue, dequeue, front and rear operations. It also implements getSize and increaseCapacity methods.

```c++
#include<iostream>
using namespace std;

class CircularQueue {
    int *queue;
    int front, rear, capacity;
    int size;

    public:
    CircularQueue(int capacity) {
        front = -1;
        rear = -1;
        this->capacity = capacity;
        queue = new int[capacity];
        size = 0;
    }

    bool isFull() {
        return ((rear + 1) % capacity == front);
    }

    bool enqueue(int item) {
        if(isFull()) {
            return false;
        }
        if(front == -1) {
            front = 0;
        }
        rear = (rear + 1) % capacity;
        queue[rear] = item;
        size++;
        return true;
    }

    int dequeue() {
        if(front == -1) {
            throw "Queue is empty";
        }
        int item = queue[front];
        if(front == rear) {
            front = -1;
            rear = -1;
        }
        else {
            front = (front + 1) % capacity;
        }
        size--;
        return item;
    }

    int getFront() {
        if(front == -1) {
            throw "Queue is empty";
        }
        return queue[front];
    }

    int getRear() {
        if(front == -1) {
            throw "Queue is empty";
        }
        return queue[rear];
    }

    int getSize() {
        return size;
    }

    void increaseCapacity(int newCapacity) {
        int *newQueue = new int[newCapacity];
        for(int i = 0; i < size; ++i) {
            newQueue[i] = queue[(front + i) % capacity];
        }
        delete[] queue;
        queue = newQueue;
        front = 0;
        rear = size - 1;
        capacity = newCapacity;
    }

};

```

In the above code, 'enqueue', 'dequeue', 'isFull', 'front', and 'rear' operations return false, throw exceptions, or return values in O(1) time complexity, respectively. 'getSize' is simply returning the size which is stored, so the time complexity is also O(1). 'increaseCapacity' creates space for a larger array, copies elements to it and sets up the new array as the queue. It takes O(n) time complexity because it has to go through each element currently in the queue to copy it to the new array, where n is the number of elements already in the queue.

