        for (int i = 0; i < coord.size(); ++i)
            sum[i] = coord[i] +  b.coord[i];
        return Point(sum);
    }

    Point operator-(const Point& b) {
        if (coord.size() !=  b.coord.size()) throw std::domain_error("Dimensions are not the same");
        std::vector<double> diff(coord.size());
        for (int i = 0; i < coord.size(); ++i)
            diff[i] = coord[i] -  b.coord[i];
        return Point(diff);
    }

    bool operator<(const Point& b) const {
        return coord<b.coord;
    }

    bool operator==(const Point& b) const {
        return coord==b.coord;
    }

    bool operator>(const Point& b) const {
        return coord>b.coord;
    }

    // Euclidean distance 
    double EuclideanDistance(const Point& b) const {
        if (coord.size() !=  b.coord.size()) throw std::domain_error("Dimensions are not the same");
        double sum = 0.0;
        for (int i = 0; i < coord.size(); ++i)
            sum += std::pow(coord[i] - b.coord[i], 2);
        return std::sqrt(sum);
    }

    // Manhattan distance 
    double ManhattanDistance(const Point& b) const {
        if (coord.size() !=  b.coord.size()) throw std::domain_error("Dimensions are not the same");
        double sum = 0.0;
        for (int i = 0; i < coord.size(); ++i)
            sum += std::abs(coord[i] - b.coord[i]);
        return sum;
    }
};
```

Here, `coord` is a vector of doubles holding the coordinates of the point in n-dimensional space. The operator overloading functions check whether the dimensions of the two points are the same and throw a domain error if they are not.

The `EuclideanDistance` function computes the Euclidean distance between two points using the formula:

    sqrt((x1-x2)^2 + (y1-y2)^2 + ...)

The `ManhattanDistance` function computes the Manhattan distance between two points using the formula:

    abs(x1-x2) + abs(y1-y2) + ...

