func rollingMax(numbers []int) []int {
	var result []int

	if len(numbers) != 0 {
		maxNum := numbers[0]
		result = append(result, maxNum)

		for _, num := range numbers[1:] {
			if num > maxNum {
				maxNum = num
			}
			result = append(result, maxNum)
		}
	}

	return result
}

