/**
 * Separate parenthesis groups into separate strings.
 * @param {string} parenString - The string of parentheses.
 * @param {boolean} [innerParen=false] - Flag to indicate if we focus on inner parentheses only.
 * @returns {Array<string>} - The groups of parentheses separated into different strings.
 */
function separateParenGroups(parenString, innerParen = false) {
    var stack = [];
    var result = [];

    // Iterates over each character in the given string
    for (var char of parenString) {
        // Check if character is an opening bracket
        if (char === '(' || char === '[') {
            stack.push(char);
        } 
        // Check if character is closing bracket
        else if (char === ')' || char === ']') {
            var group = [];
            var last = stack.pop();
            // Keep popping the stack until an opening bracket is found
            while (last !== '(' && last !== '[') {
                group.unshift(last);
                last = stack.pop();
            }
            // Check if brackets are correctly paired
            if ((char === ')' && last === '(') || (char === ']' && last === '[')) {
                group.unshift(last);
                group.push(char);
            } else {
                throw new Error('Mismatched parentheses');
            }
            if (innerParen && stack.length > 0 && (stack[stack.length-1] === '(' || stack[stack.length-1] === '[')) {
                // If the condition is met, append the group into result with the surrounding brackets
                result.push(stack[stack.length-1] + group.join('') + stack[stack.length-1]);
                stack.push(char);
            } else {
                stack = stack.concat(group);
            }
        } 
        // discard other characters
        else {
            continue;
        }
    }

    // check if there's unmatched parentheses left
    if (stack.length > 0) {
        throw new Error('Unmatched parentheses');
    }
    return result;
}
```

Every line of code in this function works towards separating groups of parentheses into different strings, and adding these strings to the result array, finally value returned by the function.

