```Python
class Node: 
    def __init__(self, key): 
        self.key = key 
        self.left = None
        self.right = None
        self.height = 1

def insert(root, key): 
    if not root: 
        return Node(key) 
    elif key < root.key: 
        root.left = insert(root.left, key) 
    else: 
        root.right = insert(root.right, key) 

    root.height = 1 + max(getHeight(root.left), getHeight(root.right)) 

    balance = getBalance(root) 

    # Case 1 - Left Left
    if balance > 1 and key < root.left.key: 
        return rightRotate(root) 

    # Case 2 - Right Right 
    if balance < -1 and key > root.right.key: 
        return leftRotate(root) 

    # Case 3 - Left Right
    if balance > 1 and key > root.left.key: 
        root.left = leftRotate(root.left) 
        return rightRotate(root) 

    # Case 4 - Right Left
    if balance < -1 and key < root.right.key: 
        root.right = rightRotate(root.right) 
        return leftRotate(root) 

    return root 

def leftRotate(z): 
    y = z.right 
    T2 = y.left 
    y.left = z 
    z.right = T2 
    z.height = 1 + max(getHeight(z.left), getHeight(z.right)) 
    y.height = 1 + max(getHeight(y.left), getHeight(y.right)) 
    return y 

def rightRotate(y): 
    x = y.left 
    T3 = x.right 
    x.right = y 
    y.left = T3 
    y.height = 1 + max(getHeight(y.left), getHeight(y.right)) 
    x.height = 1 + max(getHeight(x.left), getHeight(x.right)) 
    return x 

def getHeight(root): 
    if not root: 
        return 0
    return root.height  

def getBalance(root): 
    if not root: 
        return 0 
    return getHeight(root.left) - getHeight(root.right) 
```

The basic idea behind this approach is to first insert the node the same way as in a standard Binary Search Tree and then get the balance factor for each node (the difference in height between the left and right child node). If the balance factor is less than -1 or greater than +1, rotation(s) are required. It will do proper rotations (Left-Left, Right-Right, Left-Right, and Right-Left) based on the balance factor and inserted key to balance the tree.

