        // Implement stochastic rounding:
        // Determine the base (largest integer not greater than number)
        var base = Math.floor(number);
        // Calculate the remainder and its chance to round up
        var remainder = number % 1;
        var chance = Math.random();

        // If the chance is less than the remainder, round up
        // If the remainder is 0 (exact integer), always round down (since chance is from [0, 1))
        if (chance < remainder) {
            // Ensure correct rounding direction for negative numbers
            return number > 0 ? base + 1 : base - 1;
        } else {
            return base;
        }
    }
}
