from django.shortcuts import render
from django.http import JsonResponse
from django.views import View
from .models import Content
from users.models import User

class ContentView(View):
    """
    ContentView handles the creation and retrieval of content.
    """

    def post(self, request):
        """
        Handle POST requests.
        """
        data = request.POST
        title = data.get('title')
        description = data.get('description')
        category = data.get('category')
        creator_username = data.get('creator')

        if not all([title, description, category, creator_username]):
            return JsonResponse({'error': 'Missing required information.'}, status=400)

        try:
            creator = User.objects.get(username=creator_username)
        except User.DoesNotExist:
            return JsonResponse({'error': 'User does not exist.'}, status=404)

        content = Content(title=title, description=description, category=category, creator=creator)
        content.save()

        return JsonResponse({'message': 'Content created successfully.'}, status=201)

    def get(self, request):
        """
        Handle GET requests.
        """
        content_id = request.GET.get('id')

        if not content_id:
            return JsonResponse({'error': 'Missing required information.'}, status=400)

        try:
            content = Content.objects.get(id=content_id)
        except Content.DoesNotExist:
            return JsonResponse({'error': 'Content does not exist.'}, status=404)

        return JsonResponse({
            'title': content.title,
            'description': content.description,
            'category': content.category,
            'creator': content.creator.username
        }, status=200)
```

