```php
function find_median($arr) {
    // Filter array and remove non-numeric values
    $arr = array_filter($arr, 'is_numeric');

    // Return null if array is empty
    if(count($arr) == 0){
        return null;
    }

    // Sort the array
    sort($arr, SORT_NUMERIC);

    // Calculate this array's length
    $count = count($arr);

    // Find the middle index
    $middleIndex = floor($count / 2);

    // Calculate median
    if($count % 2 == 0) {
        $median = ($arr[$middleIndex] + $arr[$middleIndex - 1]) / 2;
    } else {
        $median = $arr[$middleIndex];
    }

    return $median;
}

