        string = string.upper()
        morse = []
        for char in string:
            morse_code = self.char_to_morse.get(char)
            if morse_code:
                morse.append(morse_code)
            else:
                raise ValueError(f'Invalid character: {char}')
        return morse

    def from_morse(self, morse):
        string = ''
        for code in morse:
            char = self.morse_to_char.get(code)
            if char:
                string += char
            else:
                raise ValueError(f'Invalid Morse code: {code}')
        return string
