Here is the solution in Java, using a merge sort algorithm. It also takes into account if the array should be sorted in ascending order (if the sum of the first and last index values is odd), or sorted in descending order (if the sum is even).

```java
import java.util.*;

class Solution {
    public static List<Integer> mergeSort(List<Integer> list) {
        if (list.size() <= 1) 
            return list;

        int midpoint = list.size() / 2;
        List<Integer> left = mergeSort(new ArrayList<>(list.subList(0, midpoint)));
        List<Integer> right = mergeSort(new ArrayList<>(list.subList(midpoint, list.size())));

        return merge(left, right, (list.size() - 1) % 2 == 0);
    }

    private static List<Integer> merge(List<Integer> left, List<Integer> right, boolean descending) {
        List<Integer> result = new ArrayList<>();
        int leftPointer = 0, rightPointer = 0;

        while (leftPointer < left.size() && rightPointer < right.size()) {
            if (descending) {
                if (left.get(leftPointer) > right.get(rightPointer)) 
                    result.add(left.get(leftPointer++));
                else 
                    result.add(right.get(rightPointer++));

            } else {
                if (left.get(leftPointer) < right.get(rightPointer)) 
                    result.add(left.get(leftPointer++));
                else 
                    result.add(right.get(rightPointer++));
            }
        }

        while (leftPointer < left.size()) 
            result.add(left.get(leftPointer++));

        while (rightPointer < right.size()) 
            result.add(right.get(rightPointer++));

        return result;
    }
