You can tackle this problem using a recursive descent parser. You would first need a tokenizer, which turns the input string into a stream of tokens. Then the parser which verifies correctness and precedence of operators. The parser can be implemented using grammar-based parsing techniques.

In this case, I would write the code in Python:

```python
import re
import operator as op

class ParserError(Exception): pass

class TokenType:
    NUM, ADD, SUB, MUL, DIV, LPAREN, RPAREN, EOF = range(8)

class Token:
    def __init__(self, ttype, value=None):
        self.ttype = ttype
        self.value = value

class Lexer:
    def __init__(self, text):
        self.text = text
        self.pos = 0
        self.current_char = self.text[self.pos]

    def error(self):
        raise ParserError('Invalid character')

    def next_token(self):
        while self.current_char is not None:
            if self.current_char.isspace():
                self.skip_whitespace()
                continue
            if self.current_char.isdigit():
                return Token(TokenType.NUM, self.integer())
            if self.current_char == '+':
                self.advance()
                return Token(TokenType.ADD)
            if self.current_char == '-':
                self.advance()
                return Token(TokenType.SUB)
            if self.current_char == '*':
                self.advance()
                return Token(TokenType.MUL)
            if self.current_char == '/':
                self.advance()
                return Token(TokenType.DIV)
            if self.current_char == '(':
                self.advance()
                return Token(TokenType.LPAREN)
            if self.current_char == ')':
                self.advance()
                return Token(TokenType.RPAREN)
            self.error()
        return Token(TokenType.EOF)

    def skip_whitespace(self):
         while self.current_char is not None and self.current_char.isspace():
             self.advance()

    def integer(self):
        result = ''
        while self.current_char is not None and self.current_char.isdigit():
            result += self.current_char
            self.advance()
        return int(result)

    def advance(self):
        self.pos += 1
        self.current_char = self.text[self.pos] if self.pos < len(self.text) else None

class Parser:
    def __init__(self, lexer): 
        self.lexer = lexer
        self.current_token = self.lexer.next_token()

    def error(self):
        raise ParserError('Invalid syntax')

    def eat(self, token_type):
        if self.current_token.ttype == token_type:
            self.current_token = self.lexer.next_token()
        else:
            self.error()

    def expr(self):
        node = self.term()
        while self.current_token.ttype in (TokenType.ADD, TokenType.SUB):
            token = self.current_token
            if token.ttype == TokenType.ADD:
                self.eat(TokenType.ADD)
                node += self.term()
            elif token.ttype == TokenType.SUB:
                self.eat(TokenType.SUB)
                node -= self.term()
        return node

    def term(self):
        node = self.factor()
        while self.current_token.ttype in (TokenType.MUL, TokenType.DIV):
            token = self.current_token
            if token.ttype == TokenType.MUL:
                self.eat(TokenType.MUL)
                node *= self.factor()
            elif token.ttype == TokenType.DIV:
                self.eat(TokenType.DIV)
                divisor = self.factor()
                if divisor == 0:
                    raise ZeroDivisionError('division by zero')
                else:
                    node /= divisor
        return node

    def factor(self):
        token = self.current_token
        if token.ttype == TokenType.NUM:
            self.eat(TokenType.NUM)
            return token.value
        elif token.ttype == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            node = self.expr()
            self.eat(TokenType.RPAREN)
            return node
        self.error()

def main():
    while True:
        try:
            text = input('calc> ')
        except EOFError:
            break
        if not text:
            continue
        lexer = Lexer(text)
        parser = Parser(lexer)
        result = parser.parse()
        print(result)

if __name__ == '__main__':
    main()
```
This program supports addition, subtraction, multiplication, and division with both integer and floating point numbers. It also handles parenthesis correctly. It will raise a ParserError for invalid input and a ZeroDivisionError for divisions by zero. To use it, run the file and type in calculations as input. It will print the result for valid calculations, or an error message for invalid ones. You can end the program with Ctrl+D (or Ctrl+Z on windows).

