This problem can be solved with multiple steps as follows: 

1. Convert the two given Binary Search Trees (BSTs) to Doubly Linked Lists (DLLs)
2. Merge the two sorted DLLs into one
3. Convert the merged DLL back to a Balanced BST

Here is the C++ function implementation:

```c++
#include<bits/stdc++.h>
using namespace std;

class node {
public:
    int data;
    node* left, * right;
};

node* newNode(int data) {
    node* Node = new node();
    if (!Node) {
        cout << "Memory error\n";
        return NULL;
    }
    Node->data = data;
    Node->left = Node->right = NULL;
    return Node;
}

node* sortedListToBST(node **head_ref, int n){
    if (n <= 0)
        return NULL;
    node *left = sortedListToBST(head_ref, n/2);
    node *root = *head_ref;
    root->left = left;
    *head_ref = (*head_ref)->right;
    root->right = sortedListToBST(head_ref, n - n / 2 - 1);
    return root;
}

node* mergeDLLs(node* head1, node* head2) {
    if (head1 == NULL)
        return head2;

    if (head2 == NULL)
        return head1;

    if (head1->data < head2->data) {
        head1->right = mergeDLLs(head1->right,head2);
        head1->right->left = head1;
        head1->left = NULL;
        return head1;
    } else {
        head2->right = mergeDLLs(head1, head2->right);
        head2->right->left = head2;
        head2->left = NULL;
        return head2;
    }
}

node* binaryTreeToDLL(node **root_ref) {
    if (*root_ref == NULL)
        return NULL;

    node* a = binaryTreeToDLL(&((*root_ref)->left));
    node* b = binaryTreeToDLL(&((*root_ref)->right));

    (*root_ref)->left = (*root_ref)->right = NULL;

    return mergeDLLs(mergeDLLs(a, *root_ref), b);
}

node* mergeTwoBSTs(node* root1, node* root2) {
    node* head1 = binaryTreeToDLL(&root1);
    node* head2 = binaryTreeToDLL(&root2);
    node* merged = mergeDLLs(head1, head2);

    int n = 0;
    node *temp = merged;
    while (temp){
        n++;
        temp = temp->right;
    }

    return sortedListToBST(&merged, n);
}

void preOrder(node* node) {
    if (node == NULL)
        return;
    cout << node->data << " ";
    preOrder(node->left);
    preOrder(node->right);
}

int main() {
    node* root1 = newNode(3);
    root1->left = newNode(1);
    root1->right = newNode(5);

    node* root2 = newNode(4);
    root2->left = newNode(2);
    root2->right = newNode(6);

    node* mergedTree = mergeTwoBSTs(root1, root2);

    cout << "Merged tree in preorder is \n";
    preOrder(mergedTree);

    return 0;
}
```

Kindly note that there are multiple techniques to convert a Binary Search Tree to a Doubly Linked List (DLL), to merge two DLLs and to convert a DLL to a Balanced Binary Search Tree. This is one of those methods.

The edit distance or Levenshtein distance between two strings is the minimum number of single-character edits (insertions, deletions, or substitutions) required to change one string into the other.

Here's a simple C++ implementation that uses dynamic programming:

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

int editDistance(std::string str1, std::string str2)
{
    int m = str1.length();
    int n = str2.length();

    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1));

    for(int i = 0; i <= m; i++)
    {
        for(int j = 0; j <= n; j++)
        {
            // If first string is empty, insert all characters of second string into first
            if(i == 0)
                dp[i][j] = j;

            // If second string is empty, remove all characters of first string
            else if(j == 0)
                dp[i][j] = i;

            // If last characters are same, ignore last character and get count for remaining strings
            else if(str1[i - 1] == str2[j - 1])
                dp[i][j] = dp[i - 1][j - 1];

            // If last characters are not same, consider all possibilities and find minimum
            else 
                dp[i][j] = 1 + std::min({dp[i][j - 1],   // Insert in str1
                                         dp[i - 1][j],   // Remove from str1
                                         dp[i - 1][j - 1] // Replace in str1
                                         });
        }
    }

    return dp[m][n];
}

int main()
{
    std::string str1 = "kitten";
    std::string str2 = "sitting";
    std::cout << "Edit distance between " << str1 << " and " << str2 << " is " << editDistance(str1, str2) << std::endl;
    return 0;
}
```

This implementation creates a 2D dynamic programming table where dp[i][j] holds the edit distance between str1[0..i-1] and str2[0..j-1]. It fills the table in a top-down manner and finally, the bottom right corner of the table contains the edit distance between the input strings. The time complexity is O(m*n), where m and n are the lengths of the input strings.

