type Handler struct {
	limiter *RateLimiter
	store   *JSONStore
	logger  *Logger
}

func NewHandler(limiter *RateLimiter, store *JSONStore, logger *Logger) *Handler {
	handler := &Handler{
		limiter: limiter,
		store:   store,
		logger:  logger,
	}
	return handler
}

func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	clientIP := r.RemoteAddr
	if !h.limiter.Allow(clientIP) {
		h.logger.Write(fmt.Sprintf("%s %s %d", clientIP, r.RequestURI, http.StatusTooManyRequests))
		http.Error(w, "Too many requests, please try again later.", http.StatusTooManyRequests)
		return
	}
	h.logger.Write(fmt.Sprintf("%s %s %d", clientIP, r.RequestURI, http.StatusOK))

	router := NewRouter(h)

	switch r.Method {
	case http.MethodGet:
		router.Get(w, r)
	case http.MethodPost:
		router.Post(w, r)
	default:
		http.Error(w, "Method not supported.", http.StatusMethodNotAllowed)
	}
}
