```csharp
using System;

public class Program
{
    public static void Main()
    {
        Console.WriteLine("Input an integer to check for Armstrong Number:");

        int num = Convert.ToInt32(Console.ReadLine());
        bool isArmstrong = CheckArmstrongNumber(num);

        if(isArmstrong)
            Console.WriteLine(num + " is an Armstrong number.");
        else
            Console.WriteLine(num + " is not an Armstrong number.");
    }

    public static bool CheckArmstrongNumber(int num)
    {
        int remainder, sum = 0;
        int n = num;

        int totalDigits = num.ToString().Length;

        while(n != 0)
        {
            remainder = n % 10;
            sum += (int)Math.Pow(remainder, totalDigits);
            n /= 10;
        }

        if(sum == num)
            return true;
        else
            return false;
    }
}
```

