Here is C program that does cyclical and anti-cyclical rotation and reversal of the rotation for arrays of variable sizes with elements of type int, float, and char:

```c
#include <stdio.h>
#include <string.h>

void rotate(void* arr, int size_of_element, int num_elements, int direction) {
    char buffer[size_of_element];
    if(direction == 1) { //1 for clockwise rotation
        memcpy(buffer, (char*)arr + size_of_element * (num_elements - 1), size_of_element);
        memmove((char*)arr+size_of_element, arr, size_of_element * (num_elements-1));
        memcpy(arr, buffer, size_of_element);
    } else if (direction == -1) { //-1 for anti-clockwise rotation
        memcpy(buffer, arr, size_of_element);
        memmove(arr, (char*)arr + size_of_element, size_of_element * (num_elements-1));
        memcpy((char*)arr + size_of_element * (num_elements - 1), buffer, size_of_element);
    }
}

void reverse_rotation(void* arr, int size_of_element, int num_elements, int direction) {
    if(direction == 1) {
        rotate(arr, size_of_element, num_elements, -1);
    } else if (direction == -1) {
        rotate(arr, size_of_element, num_elements, 1);
    }
}

int main() {
    int array1[] = {2, 4, 6};
    float array2[] = {2.5, 4.9, 6.3};
    char array3[] = {'a', 'b', 'c'};

    rotate(array1, sizeof(*array1), 3, 1); //Perform clockwise rotation
    rotate(array2, sizeof(*array2), 3, -1); //Perform anti-clockwise rotation

    //Reverse the previous rotations
    reverse_rotation(array1, sizeof(*array1), 3, 1); 
    reverse_rotation(array2, sizeof(*array2), 3, -1);

    rotate(array3, sizeof(*array3), 3, 1); //Perform clockwise rotation
    return 0;
}
```

Two functions were created for the problem - rotate() and reverse_rotation(). The first rotates our type-independent array in a cyclical or anti-cyclical pattern, based on the direction passed. The second undoes the operation carried out by the first. Our direction is check via if/else, determining the order of the swaps for our rotation.

Keep in mind, this code does not perform any checks for invalid input, such as a NULL pointer or an invalid direction. Depending on the specific use case, these checks may need to be added.

