Here's a possible implementation of the aforementioned stack data structure:

```java
public class DynamicStack {

    private int capacity;
    private Object[] stack;
    private int top;

    public DynamicStack(int capacity) {
        this.capacity = capacity;
        this.stack = new Object[capacity];
        this.top = -1;
    }

    public void push(Object value) {
        if (top >= capacity) {
            resize();
        }
        stack[++top] = value;
    }

    public Object pop() {
        if (isEmpty()) {
            throw new RuntimeException("Stack is empty");
        }
        return stack[top--];
    }

    public Object peek() {
        if (isEmpty()) {
            throw new RuntimeException("Stack is empty");
        }
        return stack[top];
    }

    public boolean isEmpty() {
        return top == -1;
    }

    public int getSize() {
        return top + 1;
    }

    private void resize() {
        capacity *= 2;
        Object[] newStack = new Object[capacity];
        System.arraycopy(stack, 0, newStack, 0, stack.length);
        stack = newStack;
    }

    public static void main(String[] args) {
        DynamicStack stack = new DynamicStack(2);

        System.out.println("Stack is empty? " + stack.isEmpty());

        stack.push(1);
        stack.push(2);

        System.out.println("Stack size: " + stack.getSize());
        System.out.println("Stack peek: " + stack.peek());

        stack.push(3);

        System.out.println("Stack size after resize: " + stack.getSize());
        System.out.println("Stack peek after resize: " + stack.peek());

        stack.pop();
        System.out.println("Stack size after pop: " + stack.getSize());
        System.out.println("Stack peek after pop: " + stack.peek());

        stack.pop();
        stack.pop();

        System.out.println("Stack is empty after popping all elements? " + stack.isEmpty());
    }
}
```

