Please note that in C, we must know an approximate size of an array beforehand unlike Python, which is dynamically sized. Here, I've assumed that the `MAX_SIZE` is 50 and `MAX_STR` is 10.

Also, memory management in C is manual. We need to allocate the memory using `malloc`, `calloc` and free it after use using `free`.

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_SIZE 50
#define MAX_STR 10

void reverse(char *str) {
    int len = strlen(str);
    for (int i = 0; i < len/2; i++) {
        char temp = str[i];
        str[i] = str[len-i-1];
        str[len-i-1] = temp;
    }
}

char * tailored_merge(char **strings, int size) {
    int max_length = 0;
    for (int i = 0; i < size; i++) {
        int len = strlen(strings[i]);
        if (len > max_length) {
            max_length = len;
        }
        reverse(strings[i]);
    }
    char * result = (char *) malloc(max_length * size + 1);
    int k = 0;
    for (int i = 0; i < max_length; i++) {
        for (int j = 0; j < size; j++) {
            if (i < strlen(strings[j])) {
                result[k++] = strings[j][i];
            }
        }
    }
    result[k] = '\0';
    reverse(result);
    return result;
}

int main() {
    char **strings = (char **) malloc(MAX_SIZE * sizeof(char *));
    for (int i = 0; i < MAX_SIZE; i++) {
        strings[i] = (char *) malloc(MAX_STR * sizeof(char));
    }
    strcpy(strings[0], "abc");
    strcpy(strings[1], "def");
    strcpy(strings[2], "ghi");

    char *result = tailored_merge(strings, 3);
    printf("%s", result);

    //free allocated memory
    free(result);
    for (int i = 0; i < MAX_SIZE; i++) {
        free(strings[i]);
    }
    free(strings);
    return 0;
}
```
Please note that the code snippet is assuming all strings are null-terminated which is standard in C.

Also, note to free your allocated memory after usage to prevent memory leaks. malloc, realloc and calloc need to be balanced with a call to free when you're done with the memory.

def rolling_max_min(numbers: List[int]) -> List[Tuple[int, int]]:
