Observer Design Pattern is a design pattern that provides a way to communicate between objects when a state change occurs. It is also referred to as Publish-Subscribe pattern. Here we implement Observer pattern in Java:

```java
import java.util.ArrayList;
import java.util.List;

// Observable interface
interface Observable {
    void registerObserver(Observer observer);
    void removeObserver(Observer observer);
    void notifyObservers();
}

// Observer interface
interface Observer {
    void update(String message);
}

// Concrete observable class
class Entity implements Observable {
    private List<Observer> observers = new ArrayList<>();
    private String message;

    public void registerObserver(Observer observer) {
        observers.add(observer);
    }

    public void removeObserver(Observer observer) {
        observers.remove(observer);
    }

    public void notifyObservers() {
        for (Observer observer : observers) {
            observer.update(message);
        }
    }

    public void changeState(String message) {
        this.message = message;
        notifyObservers();
    }
}

// Concrete observer class
class EntityObserver implements Observer {
    private String name;

    public EntityObserver(String name) {
        this.name = name;
