class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def insert_into_tree(root, val, cmp_func):
    if root is None:
        return TreeNode(val)
    if cmp_func(val, root.val):
        root.left = insert_into_tree(root.left, val, cmp_func)
    else:
        root.right = insert_into_tree(root.right, val, cmp_func)
    return root


def find_median_of_tree(root):
    def in_order_traversal(node):
        if not node:
            return []
        return in_order_traversal(node.left) + [node.val] + in_order_traversal(node.right)

    in_order = in_order_traversal(root)
    n = len(in_order)
    if n % 2 == 0:  # even length, average of two middle elements
        return (in_order[n // 2 - 1] + in_order[n // 2]) / 2.0
    else:  # odd length, middle element
        return in_order[n // 2]


