        raise ValueError("Input list is empty")

    root = None
    for val in l:
        if not isinstance(val, (int, float)):
            raise TypeError("Invalid data type in the list")
        root = insert_into_tree(root, float(val), cmp_func)

    return find_median_of_tree(root)


