public class BinarySearch {
    public static void main(String[] args) {
        int[] numbers = {5, 3, 10, 1, 7};
        Arrays.sort(numbers);

        int target = 7;
        int iterativeResult = iterativeBinarySearch(numbers, target);
        int recursiveResult = recursiveBinarySearch(numbers, 0, numbers.length - 1, target);

        System.out.println("Iterative Binary Search: " + (iterativeResult != -1 ? "Found at index " + iterativeResult : "Not Found"));
        System.out.println("Recursive Binary Search: " + (recursiveResult != -1 ? "Found at index " + recursiveResult : "Not Found"));
    }

    public static int iterativeBinarySearch(int[] arr, int target) {
        int left = 0;
        int right = arr.length - 1;
        while (left <= right) {
            int middle = left + (right - left) / 2;

            if (arr[middle] == target)
                return middle;

            if (arr[middle] < target)
                left = middle + 1;

            else
                right = middle - 1;
        }

        return -1;
    }

    public static int recursiveBinarySearch(int[] arr, int left, int right, int target) {
        if (right >= left) {
            int mid = left + (right - left) / 2;

            if (arr[mid] == target)
