def swap(string):
    n = len(string)
    for i in range(n):
        for j in range(i+1, n):
            if string[i] > string[j]:
                string = string[:i] + string[j] + string[i+1:j] + string[i] + string[j+1:]
                return string
    return string

def remove_1_or_2_chars(string):
    n = len(string)
    for i in range(n-1):
        if string[i] > string[i+1]:
            string = string[:i] + string[i+2:]
            return string
    return string[:n-1]

def replace(string):
    n = len(string)
    for i in range(n-1):
        if string[i] > string[i+1]:
            string = string[:i] + chr(ord(string[i+1])-1) + string[i+1:]
            return string
    return string

def advanced_rearrange(string):
