    string = "".join(sorted(list(string)))
    if string == copy:
        return string

    copy = swap(copy)
    if "".join(sorted(list(copy))) == copy:
        return copy

    copy = remove_1_or_2_chars(copy)
    if "".join(sorted(list(copy))) == copy:
        return copy

    copy = replace(copy)
    if "".join(sorted(list(copy))) == copy:
        return copy

    return string
