import java.util.concurrent.*;

public class MultiThreadedFibonacci {
    private final ConcurrentHashMap<Integer, Long> fibCache = new ConcurrentHashMap<>();

    public MultiThreadedFibonacci() {
        fibCache.put(0, 0L);
        fibCache.put(1, 1L);
    }

    public long fib(int n) {
        return fibCache.computeIfAbsent(n, (key) -> fib(n - 1) + fib(n - 2));
    }

    public void printFibSequence(int n) {
        for (int i = 0; i <= n; i++) {
            final int index = i;
            new Thread(new Runnable() {
                @Override
                public void run() {
                    System.out.println("fib(" + index + ") = " + fib(index));
                }
            }).start();
        }
    }

    public static void main(String[] args) {
        MultiThreadedFibonacci fibonacci = new MultiThreadedFibonacci();
        fibonacci.printFibSequence(10);
    }
}
```
