Here is the equivalent C++ code:

```C++
#include <vector>
using namespace std;

bool multiplicationSort(vector<int>& arr) {
    if (arr.size() == 0) {
        return true;
    }
    for (int i = 0; i < arr.size(); i++) {
        bool isValid = true;
        for (int j = 0; j < arr.size(); j++) {
            if (arr[(i + j) % arr.size()] % arr[(i + j - 1 + arr.size()) % arr.size()] != 0) {
