This task can be done using any programming language. In this case, I'll show you how to do it in Python. Python has built-in support for using dictionaries which are equivalent to hash tables. We'll create a MyLinkedList class to simulate a doubly linked list and a MyHashTable class  to create a hash table and handle collisions with separate chaining.

```python
class Node:
    def __init__(self, value, prev_node=None, next_node=None):
        self.value = value
        self.prev_node = prev_node
        self.next_node = next_node


class MyLinkedList:

    def __init__(self):
        self.head = None
        self.tail = None
        self.size = 0

    def add_node(self, value):
        new_node = Node(value)
        if self.head is None:
            self.head = new_node
            self.tail = new_node
        else:
            new_node.prev_node = self.tail
            self.tail.next_node = new_node
            self.tail = new_node
        self.size += 1
        return new_node


class MyHashTable:
    def __init__(self):
        self.table = {}

    def add(self, key, value):
        if key in self.table:
            self.table[key].append(value)
        else:
            self.table[key] = [value]


def solve_problem(input_list):
    linked_list = MyLinkedList()
    hash_table = MyHashTable()

    for index, value in enumerate(input_list):
        linked_list.add_node(value)
        hash_table.add(value, index)

    return hash_table.table


# Example usage:

