```java
import java.util.*;
import java.lang.*;

class Solution {
    private static String[] symbol = {"M","CM","D","CD","C","XC","L","XL","X","IX","V","IV","I"}; 
    private static int[] value = {1000,900,500,400,100,90,50,40,10,9,5,4,1};

    public static String toRoman(int number) {
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < value.length && number > 0; i++) {
            while (value[i] <= number) {
                number -= value[i];
                res.append(symbol[i]);
            }
        }
        return res.toString().toLowerCase();
    }

    public static double[] intToAsciiRoman(int number) {
        if (number < 1 || number > 5000) {
            throw new IllegalArgumentException("Value out of range (1 <= num <= 5000)");
        }
        String roman = toRoman(number);
        double[] result = new double[roman.length() + 2];
        double sum = 0;
        for(int i = 0; i < roman.length(); i++) {
            result[i] = (double)roman.charAt(i);
            sum += result[i];
        }
        result[roman.length()] = sum;
        result[roman.length() + 1] = sum / roman.length();
        return result;
    }
}
```
