using namespace std;

string encode_cyclic(string text){
    for(int i=0; i < text.length(); i += 3){
        if(i+2 < text.length()){
            char temp = text[i+2];
            text[i+2] = text[i+1];
            text[i+1] = text[i];
            text[i] = temp;
        }
    }
    return text;
}

string decode_cyclic(string text){
    for(int i=0; i < text.length(); i += 3){
        if(i+2 < text.length()){
            char temp = text[i];
            text[i] = text[i+1];
            text[i+1] = text[i+2];
            text[i+2] = temp;
        }
    }
    return text;
}
```

