func QuickSort(list []int) []int {
    if len(list) <= 1 {
        return list
    } 

    pivot := list[len(list)/2]
    var lesser, equal, greater []int

    for _, num := range list {
        switch {
        case num < pivot:
            lesser = append(lesser, num)
        case num == pivot:
            equal = append(equal, num)
        case num > pivot:
            greater = append(greater, num)
        }
    }

    result := append(QuickSort(lesser), equal...)
    result = append(result, QuickSort(greater)...)

    return result
}

func BinarySearch(list []int, num int) bool {
    left, right := 0, len(list) - 1

    for left <= right {
        mid := (left + right) / 2
        switch {
        case list[mid] < num:
            left = mid + 1
        case list[mid] > num:
            right = mid - 1
        default:
            return true
        }
    }
    return false
}

func SharedElements(list1, list2 []int) []int {
    sortedList1, sortedList2 := QuickSort(list1), QuickSort(list2)
    seen := make(map[int]bool)
    result := make([]int, 0)

    for _, num := range sortedList1 {
        if BinarySearch(sortedList2, num) && !seen[num] {
            result = append(result, num)
            seen[num] = true
        }
    }

    return result
}

func main() {
    list1 := []int{1, 2, 3, 4, 5}
    list2 := []int{2, 3, 4, 6, 7}

    fmt.Println(SharedElements(list1, list2))  // Output: [2 3 4]
}
```

Please note that Golang doesn't support list comprehension. That's the reason we are using loops here.
Also, to check for duplicate elements, we are using a map instead of checking the existence of the element in the final result slice because map lookup is more efficient than slice lookup in Golang.
One more thing to note is that the append operation could be costly in Golang if the capacity of the slice is not correctly set initially as each append would lead to the creation of a new underlying array if the capacity is exceeded. As a result, avoid frequent appends wherever possible.

