def prod_signs(arr):
    if not arr:
        return None

    # Get the counts of positive and negative integers (ignoring duplicates)
    positive_counts = {}
    negative_counts = {}
    for num in arr:
        if num > 0:
            positive_counts[num] = positive_counts.get(num, 0) + 1
        elif num < 0:
            negative_counts[abs(num)] = negative_counts.get(abs(num), 0) + 1

    # Compute the sum of magnitudes of unique integers
    magnitudes_sum = sum(positive_counts.keys()) + sum(negative_counts.keys())

    # Compute the product of signs of each unique number
    product_signs = 1
    for count in positive_counts.values():
        if count % 2 == 1:
            product_signs *= 1
    for count in negative_counts.values():
        if count % 2 == 1:
            product_signs *= -1

    return magnitudes_sum * product_signs

