        let index = $0.index($0.startIndex, offsetBy: n, limitedBy: $0.endIndex)
        let secondIndex = $1.index($1.startIndex, offsetBy: n, limitedBy: $1.endIndex)

        if let unwrappedIndex = index, let unwrappedSecondIndex = secondIndex {
            return $0[unwrappedIndex] < $1[unwrappedSecondIndex]
        } else {
            return $0.endIndex < $1.endIndex
        }
