Here is a simple C++ program that uses the Bubble Sort algorithm to sort an array of integers in descending order.

```cpp
#include<iostream>
using namespace std;

void bubbleSort(int array[], int size) {
    for(int i = 0; i<size-1; i++) {
        for(int j = 0; j<size-i-1; j++) {
            if(array[j] < array[j+1]) {
                //swap elements using a temporary variable
                int temp = array[j];
                array[j] = array[j+1];
                array[j+1] = temp;
            }
        }
    }
}

void printArray(int array[], int size) {
    for(int i = 0; i < size; i++) {
        cout<<array[i]<<" ";
    }
    cout<<endl;
}

