func advanced_sort(numbers []int) (bool, []string) {
	N := len(numbers)
	operations := make([]string, 0)

	if N == 0 {
		return true, operations
	}

	sortedNumbers := make([]int, N)
	copy(sortedNumbers, numbers)
	sort.Ints(sortedNumbers)

	if areEqual(numbers, sortedNumbers) {
		return true, operations
	}

	i := 0
	for i < N-1 {
		if numbers[i] > numbers[i+1] {
			numbers = append(numbers[:i], numbers[i+1:]...)
			operations = append(operations, fmt.Sprintf("Remove %d", i))
			N = len(numbers)
		} else {
			i++
		}

		if areEqual(numbers, sortedNumbers) {
			return true, operations
		}
	}

	return false, []string{}
}

func areEqual(numbersA, numbersB []int) bool {
	if len(numbersA) != len(numbersB) {
		return false
	}
	for i, v := range numbersA {
