Next, we add javascript (main.js) to generate the SVG dynamically. Here we set attributes such as width and height, we also set the viewBox attribute to make sure the SVG scales correctly when the screen size changes.

```javascript
let svgns = "http://www.w3.org/2000/svg";

// get SVG and container element
let svg = document.getElementById('mysvg');
let container = document.getElementById('container');

// Function to generate SVG content
function generateSVG() {
    // clear existing SVG content
    while (svg.firstChild) {
        svg.removeChild(svg.firstChild);
    }

    // get the size of the container
    let rectContainer = container.getBoundingClientRect();

    // Create a circle element, for simplicity
    let circle = document.createElementNS(svgns, 'circle');

    // set circle attributes
    circle.setAttributeNS(null, 'cx', rectContainer.width/2);
    circle.setAttributeNS(null, 'cy', rectContainer.height/2);
    circle.setAttributeNS(null, 'r', rectContainer.height/4);
    circle.setAttributeNS(null, 'style', 'fill:lime; stroke:purple; stroke-width:2');

    // append circle to SVG
    svg.appendChild(circle);

    // update SVG attributes
    svg.setAttribute('width', '100%');
    svg.setAttribute('height', '100%');
    svg.setAttribute('viewBox', '0 0 ' + rectContainer.width + ' ' + rectContainer.height);
};

// generate SVG content on page load
window.onload = generateSVG;

// Listen to resize events
window.addEventListener("resize", generateSVG);
```

