// Function for binary search
int binarySearch(std::vector<int>& vec, int start, int end, int x) {
    if (end >= start) {
        int mid = start + (end - start) / 2;

        // If the element is present at the middle
        if (vec[mid] == x)
            return mid;

        // If element is smaller than mid, it can only be present in left subarray
        if (vec[mid] > x)
            return binarySearch(vec, start, mid - 1, x);

        // Else the element can only be present in right subarray
        return binarySearch(vec, mid + 1, end, x);
    }

    // We reach here when element is not present in array
    return -1;
}

int main() {
    std::vector<int> vec = {2, 4, 6, 8, 10};
    int x = 8;
    int n = vec.size();
    int result = binarySearch(vec, 0, n - 1, x);
    if (result == -1)
        std::cout << "The specified value is not present in the given sequence" << std::endl;
    else
        std::cout << "The specified value is present at index: " << result << std::endl;
    return 0;
}
