def check_inc_matrix(matrix):
    # Checking horizontal sequence
    for row in matrix:
        for i in range(len(row) - 1):
            if row[i] >= row[i+1]:
                return False

    # Checking vertical sequence
    for col in range(len(matrix[0])):
