In Entity Framework, there is no automatic feature as like Rails Magic Timestamping. However, it can still be achieved using either `Database Triggers` or `Overriding SaveChanges();` method.

Here’s an example overriding `SaveChanges()`:

```csharp
public class MyContext : DbContext
{
    public override int SaveChanges()
    {
        var entries = ChangeTracker
            .Entries()
            .Where(e => e.Entity is IHaveDateTimes && (
                e.State == EntityState.Added
                || e.State == EntityState.Modified));

        foreach (var entityEntry in entries)
        {
            ((IHaveDateTimes)entityEntry.Entity).UpdatedAt = DateTime.Now;

            if (entityEntry.State == EntityState.Added)
            {
               ((IHaveDateTimes)entityEntry.Entity).CreatedAt = DateTime.Now;
            }
        }

        return base.SaveChanges();
    }
}

public interface IHaveDateTimes
{
