/// Introduce the 'delimeter' digit amongst every couple of sequential numbers in the supplied 'numbers' list.
/// Moreover, make sure to manage scenarios that involve a negative or non-integer `delimeter`.
/// Also handles nested list within numbers list.
///
/// ## Examples
/// ```
/// let interspersed: Vec<i32> = intersperse(&[], 4);     // []
/// let interspersed: Vec<i32> = intersperse(&[1, 2, 3], 4); // [1, 4, 2, 4, 3]
/// let interspersed: Vec<i32> = intersperse(&[1, 2, 3], -2); // [1, 2, 3]
/// let interspersed: Vec<i32> = intersperse(&[1, vec![2, 3]], 4); // [1, 4, 2, 4, 3]
/// ```
use std::any::Any;
use std::pin::Pin;
use std::boxed::Box;
use std::iter::once;

pub fn intersperse(numbers: &Vec<Box<dyn Any>>, delimeter: i32) -> Vec<i32> {
    let mut outcome = vec![];
    let mut flattened_numbers = vec![];

    for num in numbers.iter() {
        // This block is to handle nested vector and flatten them.
        if let Some(n) = num.downcast_ref::<i32>() {
            flattened_numbers.push(*n);
        } else if let Some(v) = num.downcast_ref::<Vec<Box<dyn Any>>>() {
            flattened_numbers.extend(intersperse(v, delimeter));  // recursive flatten
        }
    }

    let len = flattened_numbers.len();
    for (i, n) in flattened_numbers.into_iter().enumerate() {
        // This block is to place the delimeter (if it's a non-negative integer) in between the numbers.
        outcome.push(n);
        if i < len - 1 && delimeter >= 0 {
            outcome.push(delimeter);
        }
    }

    outcome
}
