Here's a JavaScript class that allows you to manipulate the background color and font color of an HTML element based on the WCAG guidelines. This does not take into account the size of the text, so it assumes normal size text (contrast ratio of at least 4.5:1).

Instead of using the WCAG formula for calculating contrast ratio, which involves a very complex formula to calculate relative luminance, it uses an approximation formula to calculate contrast ratio. This approximation formula considers the R, G, B values independently, gives a good approximation and significantly simplifies code complexity.

```javascript
class WCAGCompliantStyler {
    constructor() { }

    changeColors(elementId, backgroundColor, fontColor) {
        const el = document.getElementById(elementId);
        if (!el) {
            throw new Error('Element not found');
        }

        const contrastRatio = this.calculateContrastRatio(backgroundColor, fontColor);

        if (contrastRatio < 4.5) {
            throw new Error('Colors do not meet WCAG contrast guide');  
        }

        el.style.backgroundColor = backgroundColor;
        el.style.color = fontColor;
    }

    calculateContrastRatio(color1, color2) {
        const color1Rgb = this.hexToRgb(color1);
        const color2Rgb = this.hexToRgb(color2);

        if (!color1Rgb || !color2Rgb) {
            throw new Error('Invalid color value');
        }

        let contrastRatio = (Math.max(color1Rgb.r, color2Rgb.r) - Math.min(color1Rgb.r, color2Rgb.r)) +
            (Math.max(color1Rgb.g, color2Rgb.g) - Math.min(color1Rgb.g, color2Rgb.g)) +
            (Math.max(color1Rgb.b, color2Rgb.b) - Math.min(color1Rgb.b, color2Rgb.b))

        contrastRatio /= 765;  // max difference (255 * 3)

        return contrastRatio;
    } 

    hexToRgb(hex) {
        const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        return result ? {
            r: parseInt(result[1], 16),
            g: parseInt(result[2], 16),
            b: parseInt(result[3], 16)
        } : null;
    }
}
```

