```javascript
import { writable } from 'svelte/store';

// create initial data
const initialGreetings = new Set();

const createGreetingsStore = () => {
  const { subscribe, set, update } = writable(initialGreetings);

  return {
    subscribe,
    addGreeting: (greeting) => update(greetings => {
      greetings.add(greeting)
      return greetings
    }),
    deleteGreeting: (greeting) => update(greetings => {
      greetings.delete(greeting)
      return greetings
    }),
    reset: () => set(new Set())
  }
}

export const greetings = createGreetingsStore();
```
Now you can add, delete, and reset greeting notifications anywhere in your app:

```javascript
import { greetings } from './greetings.js';

