        weight = count_divisors(num)
        total += num * weight
        weight_sum += weight
    avg = round(total / weight_sum)
    if base == 2:
        return bin(avg)
    elif base == 8:
        return oct(avg)
    elif base == 10:
        return avg
    else:
        return int(str(avg), base)
```

