        this.y2 = y2;
        this.z2 = z2;
    }

    public boolean isPointInside(double x, double y, double z) {
        return (x >= x1 && x <= x2) && (y >= y1 && y <= y2) && (z >= z1 && z <= z2);
    }

    public double shortestDistance(double x, double y, double z) {
        if (isPointInside(x, y, z)) {
            return 0.0;
        }

        double dx = Math.max(Math.max(x1 - x, x - x2), 0);
        double dy = Math.max(Math.max(y1 - y, y - y2), 0);
        double dz = Math.max(Math.max(z1 - z, z - z2), 0);

        return Math.sqrt(dx * dx + dy * dy + dz * dz);
    }
}
