import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;

public class Main {

    public static void main(String[] args) throws IOException {
        BufferedImage image = ImageIO.read(new File("inputImage.jpg"));
        String data = "steganography"; // Encode this string to the image
        encodeImage(image, data);
        ImageIO.write(image, "jpg", new File("encodedImage.jpg"));
    }

    private static void encodeImage(BufferedImage image, String data) {
        int[] pixels = image.getRGB(0, 0, image.getWidth(), image.getHeight(), null, 0, image.getWidth());
        char[] chars = data.toCharArray();
        int charIndex = 0;
        int charProgress = 0;
        for (int i = 0; i < pixels.length; i++) {
            int pixel = pixels[i];
            for (int j = 0; j < 3; j++) {
                if (charIndex >= chars.length) {
                    return;
                }
                int section = (chars[charIndex] >> (6 - (charProgress * 2))) & 0x3; // Separate into two bits sections
                int channel;
                switch (j) {
                    case 0:  // Red
                        channel = (pixel >> 16) & 0xFF;
                        break;
                    case 1:  // Green
                        channel = (pixel >> 8) & 0xFF;
                        break;
                    case 2:  // Blue
                        channel = pixel & 0xFF;
                        break;
                    default: // This should never run
                        throw new IllegalStateException("Too many color channels.");
                }
                channel = (channel & 0xFC) | section; // Embed the two bits into the least significant bits of the channel
                switch (j) {
                    case 0:
                        pixel = (pixel & 0xFF00FFFF) | (channel << 16);
                        break;
                    case 1:
                        pixel = (pixel & 0xFFFF00FF) | (channel << 8);
                        break;
                    case 2:
                        pixel = (pixel & 0xFFFFFF00) | channel;
                        break;
                }
                pixels[i] = pixel;
                charProgress++;
                if (charProgress >= 4) {
                    charIndex++;
                    charProgress = 0;
                }
            }
        }
        image.setRGB(0, 0, image.getWidth(), image.getHeight(), pixels, 0, image.getWidth());
    }
}
```

In this example, we embed our message into the least significant bits of the red, green, and blue channels of each pixel. Each character from the string is separated into four 2-bit sections, which are then embedded into three channels of each pixel. We use a single character from the string for each pixel in the image. 

Note: The LSB modification strategy in this example is quite simple and not the most efficient or secure. It is merely a basic demonstration. Actual steganography software would use more complex methods to hide data, and may also employ additional techniques such as encryption.

