func weightedMedianOccurrences(arr []int, weights []int) int {
    if len(arr) != len(weights) {
        return -1
    }

    frequency := make(map[int]int)
    weightsDict := make(map[int]int)

    for i := range arr {
        frequency[arr[i]]++
        weightsDict[arr[i]] += weights[i]
    }

    frequencyClasses := make([]int, 0, len(frequency))
    for _, v := range frequency {
        frequencyClasses = append(frequencyClasses, v)
    }

    sort.Ints(frequencyClasses)

