        return -1
    }

    medianFrequency := frequencyClasses[len(frequencyClasses)/2]

    numbersAtMedianFrequency := make([]int, 0)
    for k, v := range frequency {
        if v == medianFrequency {
            numbersAtMedianFrequency = append(numbersAtMedianFrequency, k)
        }
    }

    if len(numbersAtMedianFrequency) == 1 {
        return numbersAtMedianFrequency[0]
    } else {
        weightsAtMedianFrequency := make([][2]int, len(numbersAtMedianFrequency))
        for i, num := range numbersAtMedianFrequency {
            weightsAtMedianFrequency[i] = [2]int{weightsDict[num], num}
