Here is a JavaScript solution which relies on the concept that a palindrome can only be created from a string that has even numbers of each character type, and at most one character type that only appears an odd number of times. 

The function `canFormPalindrome` first builds a character frequency map of the input string. Then it checks the frequency of each character. If more than one character has an odd frequency then we cannot form a palindrome with the given string.

The function `generatePalindromes` uses recursion to generate all the possible palindrome permutations from the input string. It encapsulates the logic for generating palindromes based on the frequency map created by `canFormPalindrome`.

Since creating the frequency map is an O(n) operation and we must iterate through the entire input string, the time complexity for these functions can be considered as nearly O(n).

```JavaScript
function canFormPalindrome(str) {
    const hash = {};
    for(let char of str) {
        hash[char] = (hash[char] || 0) + 1;
    }
    return hash;
}

function generatePalindromes(hash, word, start, end, results) {
    if(start > end) {
        results.push(word.join(''));
        return;
    }

    for(var key in hash) {
        if(hash[key] > 0) {
            hash[key] -= (start == end ? 1 : 2);  // If it is a half part, we can take 2 chars, otherwise we take 1 char
            word[start] = word[end] = key;  // Put the char at both sides of the sub word.
            generatePalindromes(hash, word, start + 1, end - 1, results);
            hash[key] += (start == end ? 1 : 2);  // Backtrack.
        }
    }
}

function checkedPalindromes(str) {
    let length = str.length;
    const results = [];
    const hash = canFormPalindrome(str);
    let count = Object.values(hash).filter(x => x % 2).length;
    if(length % 2 !== count) return "No palindrome permutations possible.";
    generatePalindromes(hash, new Array(Math.floor(length / 2) * 2 + 1), 0, Math.floor(length/2) * 2, results);
    return results;
}
console.log(checkedPalindromes("carerac"));
```
