from sklearn.exceptions import NotFittedError

class NaiveBayesModel:
    def __init__(self):
        self.data = pd.DataFrame()
        self.model = BernoulliNB()

    def add_records(self, records):
        try:
            new_data = pd.DataFrame(records)
            self.data = pd.concat([self.data, new_data])
        except Exception as e:
            print(f"Failed to add records: {e}")

    def remove_records(self, indices):
        try:
            self.data = self.data.drop(indices)
        except Exception as e:
            print(f"Failed to remove records: {e}")

    def update_record(self, index, record):
        try:
            for col, value in record.items():
                self.data.at[index, col] = value
        except Exception as e:
            print(f"Failed to update record: {e}")

    def build_model(self, target_column):
        self.model.fit(self.data.drop([target_column], 1), self.data[target_column])

    def predict(self, records):
        try:
            return self.model.predict(records)
        except NotFittedError:
            print("Model is not fitted yet. Call build_model first.")
