                                 int row_index, int column_index) {
        Node newNode = new Node();
        newNode.value = non_zero_element;
        if (startNode == null) {
            newNode.row_position = row_index;
            newNode.column_postion = column_index;
            newNode.next = null;
            startNode = newNode;
        } else {
            Node temp = startNode;
            while (temp.next != null)
                temp = temp.next;

            newNode.row_position = row_index;
            newNode.column_postion = column_index;
            newNode.next = null;
            temp.next = newNode;
        }
    }

