fn bubble_sort(mut nums: Vec<i32>) -> Vec<i32> {
    let len = nums.len();
    for _ in 0..len {
        for j in 0..len - 1 {
            if nums[j] > nums[j + 1] {
                nums.swap(j, j + 1);
            }
        }
    }
    nums
}

