Python program to design in-memory file system is as follows:

```python
class Dir:
    def __init__(self):
        self.childs = dict()
        self.files = dict()

class FileSystem:
    def __init__(self):
        self.root = Dir() 

    def getChildDir(self, dirs, cur, create):
        for dir in dirs:
            if not dir in cur.childs:
                if not create:
                    return None
                cur.childs[dir] = Dir()
            cur = cur.childs[dir]
        return cur 

    def ls(self, path: str):
        dirs = path.split('/')[1:]
        cur = self.getChildDir(dirs[:-1], self.root, False)
        if dirs[-1] in cur.childs: 
            return sorted(cur.childs[dirs[-1]].childs.keys() + cur.childs[dirs[-1]].files.keys())
        if dirs[-1] in cur.files:  
            return [dirs[-1]]  
        return []  

    def mkdir(self, path: str):
        dirs = path.split('/')[1:]
        self.getChildDir(dirs, self.root, True)

    def addContentToFile(self, path: str, content: str):
        dirs = path.split('/')[1:]
        cur = self.getChildDir(dirs[:-1], self.root, True)
        if dirs[-1] not in cur.files:
            cur.files[dirs[-1]] = ''
        cur.files[dirs[-1]] += content

    def readContentFromFile(self, path: str) -> str:
        dirs = path.split('/')[1:]
        cur = self.getChildDir(dirs[:-1], self.root, False)
        if dirs[-1] not in cur.files:
            return ''
        return cur.files[dirs[-1]]

    def delete(self, path: str):
        dirs = path.split('/')[1:]
        parent = self.getChildDir(dirs[:-1], self.root, False)
        cur = dirs[-1]
        if cur in parent.childs:
            del parent.childs[cur]
        elif cur in parent.files:
            del parent.files[cur]
```

With this data structure, each operation time complexity is O(m+n+klogk), where m, n and k separately represent the path depth, the file count in a directory and the child count in a directory.

