```python
def binary_search_even(arr, x):
    left, right = 0, len(arr) // 2

    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid * 2] == x:
            return mid * 2
        elif arr[mid * 2] < x:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def binary_search_odd(arr, x):
    left, right = 0, len(arr) // 2

    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid * 2 + 1] == x:
            return mid * 2 + 1
        elif arr[mid * 2 + 1] > x:
            left = mid + 1
        else:
            right = mid - 1

    return -1

