        foreach (T item in this.dictionary.Keys)
        {
            union.Add(item);
        }
        foreach (T item in other.dictionary.Keys)
        {
            union.Add(item);
        }
        return union;
    }

    public Set<T> Intersection(Set<T> other)
    {
        Set<T> intersection = new Set<T>();
        foreach (T item in this.dictionary.Keys)
        {
