    let s = s.chars().collect::<Vec<char>>();
    let len = s.len();
    let mut start = 0;
    let mut end = len - 1;

    while start < end {
        if s[start] != s[end] {
            return false;
        }
        start += 1;
        end -= 1;
    }
    return true;
}

fn make_palindrome(s: &str) -> String {
