function isValidISBN(isbn, type) {
    if (type === 'ISBN-10') {
        var sum = 0;
        for (var i = 0; i < 9; i++)
            sum += (10 - i) * isbn.charAt(i);
        var check = (11 - sum % 11) % 11;
        return check === Number(isbn.charAt(9));
