        var sum = 0;
        for (var i = 0; i < 12; i++)
            sum += ((i % 2 === 0) ? 1 : 3) * isbn.charAt(i);
        var check = (10 - sum % 10) % 10;
        return check === Number(isbn.charAt(12));
    }
}

