class MyCircularDeque:

    def __init__(self, k: int): 
        self.queue = [0]*k
        self.headIdx = 0
        self.count = 0
        self.capacity = k

    def insertFront(self, value: int) -> bool:
        if self.count == self.capacity:
            return False
        self.headIdx = (self.headIdx - 1 + self.capacity) % self.capacity
        self.queue[self.headIdx] = value
        self.count += 1
        return True

    def insertLast(self, value: int) -> bool:
        if self.count == self.capacity:
            return False
        self.queue[(self.headIdx + self.count) % self.capacity] = value
        self.count += 1
        return True

    def deleteFront(self) -> bool:
        if self.count == 0:
            return False
        self.headIdx = (self.headIdx + 1) % self.capacity
        self.count -= 1
        return True

    def deleteLast(self) -> bool:
        if self.count == 0:
            return False
        self.count -= 1
        return True

    def getFront(self) -> int:
        if self.count == 0:
            return -1
        return self.queue[self.headIdx]

    def getRear(self) -> int:
        if self.count == 0:
            return -1
        return self.queue[(self.headIdx + self.count - 1) % self.capacity]

    def getMiddle(self) -> int:
        if self.count == 0:
            return -1
        if self.count % 2 == 0:
            mid1 = self.queue[(self.headIdx + self.count // 2 - 1) % self.capacity]
            mid2 = self.queue[(self.headIdx + self.count // 2) % self.capacity]
            return mid1, mid2
        else:
            mid = self.queue[(self.headIdx + self.count // 2) % self.capacity]
            return mid

    def isEmpty(self) -> bool:
        return self.count == 0

    def isFull(self) -> bool:
        return self.count == self.capacity
```

