```python
class Quaternion:
    def __init__(self, x=0, y=0, z=0, w=0):
        self.x = x
        self.y = y
        self.z = z
        self.w = w

    def __add__(self, other):
        return Quaternion(
            self.x + other.x,
            self.y + other.y,
            self.z + other.z,
            self.w + other.w
        )

    def __sub__(self, other):
        return Quaternion(
            self.x - other.x,
            self.y - other.y,
            self.z - other.z,
            self.w - other.w
        )

    def __mul__(self, other):
        return Quaternion(
            self.w * other.x + self.x * other.w + self.y * other.z - self.z * other.y,
            self.w * other.y - self.x * other.z + self.y * other.w + self.z * other.x,
            self.w * other.z + self.x * other.y - self.y * other.x + self.z * other.w,
            self.w * other.w - self.x * other.x - self.y * other.y - self.z * other.z
        )

    def __div__(self, other):
        mod_squared = other.x**2 + other.y**2 + other.z**2 + other.w**2
        if mod_squared == 0:
            raise ZeroDivisionError("Cannot divide by zero!")
        return Quaternion(
            (self.x * other.w - self.w * other.x + self.y * other.z - self.z * other.y) / mod_squared,
            (self.y * other.w - self.w * other.y + self.z * other.x - self.x * other.z) / mod_squared,
            (self.z * other.w - self.w * other.z + self.x * other.y - self.y * other.x) / mod_squared,
            (self.w * other.w + self.x * other.x + self.y * other.y + self.z * other.z) / mod_squared
        )

    def __str__(self):
        return "Quaternion [x: {}, y: {}, z: {}, w: {}]".format(self.x, self.y, self.z, self.w)

