    """
    This function checks with a recursive approach if a number is prime
    :param n: number to be checked
    :param i: iteration number, should be left at default value when called
    :return: True if number is prime, False otherwise
    """
    if n <= 2:
        if n == 2:
            return True
        else:
            return False
    if n % i == 0:
        return False
    if i * i > n:
        return True
