```Java
import java.util.Arrays;
import java.util.Random;

public class TestSearch {

    // Binary search method
    public static int binarySearch(int arr[], int x) {
        int left = 0, right = arr.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;

            // Check if x is present at mid
            if (arr[mid] == x)
                return mid;

            // If x is greater, ignore left half  
            if (arr[mid] < x)
                left = mid + 1;

            // If x is smaller, ignore right half 
            else
                right = mid - 1;
        }

        // if we reach here, then element was not present
        return -1; 
    }

    // Method to test binarySearch method efficiency
    public static void testEfficiency() {
        Random rand = new Random();
        for(int size = 5; size <= 5000; size += 500) {
            int[] arr = new int[size];
            for(int i = 0; i < size; i++) {
                arr[i] = rand.nextInt(5000);
            }
            Arrays.sort(arr);

            long start = System.nanoTime();
            binarySearch(arr, rand.nextInt(5000));
            long end = System.nanoTime();
            System.out.println("Time taken for " + size + " elements: " + (end - start) + " nanoseconds.");
        }
    }

    // Main method
    public static void main(String[] args) {
        testEfficiency();
    }
}
```

