```python
def find_element(arr, target):
    low = 0
    high = len(arr) - 1

    while low <= high:
        mid = (low + high) // 2

        if target == arr[mid]:
            return mid

        # if the left side is sorted
        if arr[low] <= arr[mid]:
            # target lies within range 
            if arr[low] <= target <= arr[mid]:
