func cyclic_encode(s string) string {
	var groups []string
	for i := 0; i < len(s); i += 3 {
		end := i + 3
		if end > len(s) {
			end = len(s)
		}
		groups = append(groups, s[i:end])
	}
	for i, group := range groups {
		if len(group) == 3 {
			groups[i] = group[1:] + string(group[0])
		}
	}
	return strings.Join(groups, "")
}

func decode_cyclic(s string) string {
	var groups []string
	for i := 0; i < len(s); i += 3 {
		end := i + 3
		if end > len(s) {
			end = len(s)
		}
		groups = append(groups, s[i:end])
	}
	for i, group := range groups {
		if len(group) == 3 {
			groups[i] = string(group[len(group)-1]) + group[:len(group)-1]
		}
	}

	return strings.Join(groups, "")
}

func main() {
