def is_prime_and_largest_prime_factor(n):
    # function to check if a number is prime
    def is_prime(n):
        if n <= 1:
            return False
        elif n == 2:
            return True
        else:
            for i in range(2, int(n**0.5) + 1):
                if n % i == 0:
                    return False
            return True
    # check if the number is prime
    prime = is_prime(n)
    # if the number is not prime, find its largest prime factor
    if not prime and n > 1:
        factor = 2
        while factor * factor <= n:
            if n % factor:
                factor += 1
            else:
                n //= factor
    return (prime, n)
