Here's JavaScript-coded sliding window solution that accomplishes the outlined specifications. This code applies Array.prototype.reduce to slide a window of length k across the input array, storing each subset's start index, and its min and max sums.

/** Generates all sublist of length k for super array */
function slidingWindow(inputArr, k) {
    if (inputArr == null || k > inputArr.length) {
        throw new Error('Invalid input data');
    }

    let results = [];
    let windowSum = 0;
    let windowStart = 0;

    for (let windowEnd = 0; windowEnd < inputArr.length; windowEnd++) {
        windowSum += inputArr[windowEnd];

        if (windowEnd >= k - 1) {
            results.push({startIndex: windowStart, subArr: inputArr.slice(windowStart, windowStart + k), sum: windowSum});
            windowSum -= inputArr[windowStart];
            windowStart += 1;
        }
    }

    return results;
}

