```javascript
function isNested(string) {
  var stack = [];
  var bracketsMap = {"(": ")", "[": "]", "{": "}", "<": ">"};
  var error = "";

  for (var i = 0; i < string.length; i++) {
    var character = string[i];

    if (bracketsMap.hasOwnProperty(character)) { // encountered an open bracket
      stack.push(character);
    } else if (Object.values(bracketsMap).includes(character)) { // encountered a close bracket
      if (!stack.length || bracketsMap[stack.pop()] !== character) {
        error = "Position " + (i + 1);
        return {isValid: false, error: error};
      }
    } else {
      error = "Position " + (i + 1) + " - Invalid character " + character;
      return {isValid: false, error: error};
    }
  }

  // if the stack is empty then brackets were balanced
  if (!stack.length) {
    return {isValid: true, error: null};
  } else {
    error = "Position " + string.length + " - unmatched " + stack[stack.length - 1];
    return {isValid: false, error: error};
  }
}

