function isCreditCardValid(cardNumber) {

    var cardType = "";
    if( (cardNumber.charAt(0) === "4") && (cardNumber.length === 16) ) {
        cardType = "Visa";
    } else if( (cardNumber.substring(0,2) === "51" || cardNumber.substring(0,2) === "52" || cardNumber.substring(0,2) === "53" || cardNumber.substring(0,2) === "54" || cardNumber.substring(0,2) === "55") && (cardNumber.length === 16) ) {
        cardType = "MasterCard";
    } else {
        return false; // If it's neither Visa nor Mastercard
    }

    // Luhn Algorithm
    let sum = 0;
    let isSecondDigit = false;
    for (let i = cardNumber.length - 1; i >= 0; i--) {
        let digit = parseInt(cardNumber[i]);

        if (isSecondDigit){
            digit *= 2;
            if(digit > 9){
                digit -= 9;
            }
        }
        sum += digit;
        isSecondDigit = !isSecondDigit;
    }
    console.log(`Card type: ${cardType}`);
    return sum % 10 === 0;
}

