```dart
import 'dart:math';

class RandomSequenceGenerator {
  final int start;
  final int end;
  List<int> _candidates;
  Random _random;

  RandomSequenceGenerator({this.start = 0, this.end}) {
    if (start >= end) {
      throw ArgumentError('The start must be less than the end.');
    }
    _candidates = List<int>.generate((end - start), (i) => i + start);
    _random = Random();
  }

  int getNextNumber() {
    if (_candidates.isEmpty) {
      throw StateError('No more numbers left.');
    }

    var randomIndex = _random.nextInt(_candidates.length);
    return _candidates.removeAt(randomIndex);
  }
}
