Yes, you can interpret Reverse Polish Notation(RPN) into "normal" mathematical notation, also known as infix notation. The pseudocode or general algorithm which you can implement in both C# and C++ is as follows:

1. Scan the given expression and do following for every scanned element.
   - If the element is a number, push it into the Stack
   - If the element is a operator, pop operands for the operator from stack. Evaluate the operator and push the result back to Stack
2. When the expression is ended, the number in the stack is the final answer

Implementing the above algorithm in code form:

C# Code Sample:

```
public static double EvaluateRPN(string[] tokens)
{
    var stack = new Stack<double>();

    foreach (var token in tokens)
    {
        if (double.TryParse(token, out double num))
        {
            stack.Push(num);
        }
        else
        {
            double secondOperand = stack.Pop();
            double firstOperand = stack.Pop();

            switch (token)
            {
                case "+":
                    stack.Push(firstOperand + secondOperand);
                    break;
                case "-":
                    stack.Push(firstOperand - secondOperand);
                    break;
                case "*":
                    stack.Push(firstOperand * secondOperand);
                    break;
                case "/":
                    stack.Push(firstOperand / secondOperand);
                    break;
                default:
                    throw new ArgumentException("Unsupported operation");
            }
        }
    }

    return stack.Pop();
}
```

C++ Code Sample:

```cpp
double EvaluateRPN(vector<string> &tokens)
{
    stack<double> stk;
    for (string &s : tokens)
    {
        if (s.size() > 1 || isdigit(s[0]))
            stk.push(stod(s));
        else
        {
            double op2 = stk.top();
            stk.pop();
            double op1 = stk.top();
            stk.pop();
            switch (s[0])
            {
            case '+':
                stk.push(op1 + op2);
                break;
            case '-':
                stk.push(op1 - op2);
                break;
            case '*':
                stk.push(op1 * op2);
                break;
            case '/':
                stk.push(op1 / op2);
                break;
            }
        }
    }
    return stk.top();
}
```
Note that "stod" is a C++ function that converts a string to a double.

