        return y;
    }

    public float getZ() {
        return z;
    }

    public double distanceTo(Point p) {
        float dx = x - p.getX();
        float dy = y - p.getY();
        float dz = z - p.getZ();
        return Math.sqrt(dx * dx + dy * dy + dz * dz);
    }

    public Point midPoint(Point p) {
        return new Point((x + p.getX()) / 2, (y + p.getY()) / 2, (z + p.getZ()) / 2);
    }

