This is a Python code for applying specific transformations to an input string:

1. If a character is a number and odd, it is changed to the nearest even number. If it is an even number or a digit missing in the mapping, it remains the same.
2. If a character is a letter, its case is inverted (lowercase to uppercase and vice versa).
3. If a character is a special symbol, it is duplicated and case inversion also applied if it was an alphabetic letter.
4. The function then counts the frequency of each character in the transformed string.

Here is the C version of the code:

```c
#include <ctype.h>
#include <string.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct
{
    char* transformed_sequence;
    int frequency_dict[128];
} AdvancedTransformResult;

static char number_mapping[] = {'0', '0', '2', '2', '4', '4', '6', '6', '8', '8'};

AdvancedTransformResult advanced_transformation(const char* sequence)
{
    // Define a mapping for numbers to their nearest even equivalent
    size_t sequence_length = strlen(sequence);

    // Initialize an empty string to capture the transformed sequence
    char* transformed_sequence = malloc(sequence_length*2 + 1);
    memset(transformed_sequence, 0, sequence_length*2 + 1);

    // Process each character in the sequence
    int frequency_dict[128] = {0};

    int index = 0;
    for (int i = 0; i < sequence_length; i++) {
        char char_value = sequence[i];
        // If the character is a number, map it to nearest even number.
        if (isdigit(char_value)) {
            transformed_sequence[index++] = number_mapping[char_value - '0'];
        } 
        // If the character is a letter, convert to opposite case.
        else if (isalpha(char_value)) {
            transformed_sequence[index++] = islower(char_value) ? toupper(char_value) : tolower(char_value);
        } 
        // If it is a special character, double it
        else {
            transformed_sequence[index++] = char_value;
            transformed_sequence[index++] = char_value;
        }

        // Increase the count in the dict for each character occurrence
        frequency_dict[(int)transformed_sequence[index-1]]++;
    }

    AdvancedTransformResult result;
    result.transformed_sequence = transformed_sequence;
    memcpy(result.frequency_dict, frequency_dict, sizeof(frequency_dict));
    return result;
}

int main() {
    const char* sequence = "Hello123!";
    AdvancedTransformResult result = advanced_transformation(sequence);
    printf("Transformed sequence: %s\n", result.transformed_sequence);

    for (int i = 0; i < 128; i++)
        if (result.frequency_dict[i] > 0)
            printf("Frequency of %c: %d\n", i, result.frequency_dict[i]);

    free(result.transformed_sequence);
    return 0;
}
```

