function getSilverlightVersion() {
    var isSilverlightInstalled = false;
    var silverlightVersion = "No Silverlight.";
    try{
       // for NPAPI browsers (non-IE) 
       if(window.navigator.plugins["Silverlight Plug-In"]){
         isSilverlightInstalled = true;
         var words = 
           window.navigator.plugins["Silverlight Plug-In"].description.split(" ");
         for(var i = 0; i < words.length; ++i){
