           }
         }
       }
       // for ActiveX enabled browsers (IE) 
       else if (navigator.userAgent.indexOf("MSIE") > -1){
         try{
           var slControl = new ActiveXObject('AgControl.AgControl');
           if(slControl){
             isSilverlightInstalled = true;
             silverlightVersion = "Silverlight " + slControl.settings.version;
           }
         } 
         catch(e){
           isSilverlightInstalled = false; // Silverlight is not installed or not enabled for ActiveX
         }
       } 
       else {
         isSilverlightInstalled = false; // Browser doesn't support Silverlight
       } 
    }
    catch(e){
      isSilverlightInstalled = false; // Unknown error
    }

    return silverlightVersion;
}
