    Groups groups;
    initGroups(&groups, 10);    // initial capacity of 10, will expand if necessary

    separateAndCountParenGroups(test, &groups);

    for(int i = 0; i < groups.current_size; i++)
        printf("%s\n", groups.items[i]);

    // Free allocated memory
    for (int i = 0; i < groups.current_size; i++)
        free(groups.items[i]);
    free(groups.items);

    return 0;
}
```

