Here is the improved code that handles the negative delimiter properly;

```python
from typing import List

def intersperse(numbers1: List[int], numbers2: List[int], delimeter: int) -> List[int]:

    # If delimeter is negative, get its absolute value
    if delimeter < 0:
        delimeter = abs(delimeter)
        try:
            # Remove elements at index equal to delimeter from both lists
            numbers1.pop(delimeter)
            numbers2.pop(delimeter)
        except IndexError:
            pass  # pass if index out of range to continue with existing elements

    # Interweave numbers1, delimeter and numbers2
    result = []
    for num1, num2 in zip(numbers1, numbers2):
        result.extend([num1, delimeter, num2, delimeter])

    # If numbers1 is longer than numbers2, add remaining items
    if len(numbers1) > len(numbers2):
        for num in numbers1[len(numbers2):]:
            result.extend([num, delimeter])

    # If numbers2 is longer than numbers1, add remaining items
    elif len(numbers2) > len(numbers1):
        for num in numbers2[len(numbers1):]:
            result.extend([num, delimeter])

    # Remove the last delimeter from the result
    return result[:-1]

# Test cases
print(intersperse([1, 2, 3], [4, 5, 6], 7))   # Should print [1, 7, 4, 7, 2, 7, 5, 7, 3, 7, 6]
print(intersperse([1, 2, 3], [4, 5, 6], -2))  # Should print [1, 4, 3, 6]
```

