```cpp
#include <algorithm>
#include <cctype>
#include <string>
using namespace std;

bool isPalindrome(string s, int l, int r) {
    while (l < r) {
        if (s[l++] != s[r--]) {
            return false;
        }
    }
    return true;
}

string longestPalindromicPostfix(string s) {
    int n = s.length();
    for (int i = 0; i < n; i++) {
        if (isPalindrome(s, i, n - 1)) {
            return s.substr(i);
        }
    }
    return "";
}

string makePalindromePlus(string s, string prefix, string suffix) {
    s.erase(remove_if(s.begin(), s.end(), [](char c) { return !isalnum(c); }), s.end());
    transform(s.begin(), s.end(), s.begin(), ::tolower);

    prefix.erase(remove_if(prefix.begin(), prefix.end(), [](char c) { return !isalnum(c); }), prefix.end());
    transform(prefix.begin(), prefix.end(), prefix.begin(), ::tolower);

    suffix.erase(remove_if(suffix.begin(), suffix.end(), [](char c) { return !isalnum(c); }), suffix.end());
    transform(suffix.begin(), suffix.end(), suffix.begin(), ::tolower);

    s = prefix + s + suffix;
    string postfix = longestPalindromicPostfix(s);
    string prefixToMirror = postfix.empty() ? s : s.substr(0, s.length() - postfix.length());
    reverse(prefixToMirror.begin(), prefixToMirror.end());

    return s + prefixToMirror;
}
```

This code includes the algorithm library (for the `remove_if`, `transform` and `reverse` algorithms), and the cctype library for the `isalnum` function. The way it removes non-alphanumeric characters is slightly less intuitive in C++. It uses the erase-remove idiom which is frequently used in C++ to remove elements from a container based on a condition. It also uses the tolower function inside a transform algorithm to convert all characters to lowercase.

