```python
import numpy as np
from sklearn.metrics import log_loss

def adjust_probs(probs, ext_factor):
    adjusted = np.maximum(np.add(probs, ext_factor), 0)
    if np.sum(adjusted) > 0:
        return adjusted / np.sum(adjusted)
    else:
        return np.full(len(probs), 1/len(probs))

def multiclass_log_loss(y_true, y_pred, ext_factor):
    y_pred_adjusted = np.array([adjust_probs(p, f) for p, f in zip(y_pred, ext_factor)])
    return log_loss(y_true, y_pred_adjusted)

