Here's a basic implementation for decision tree classifier in Python. Please note that this is a simplified version and may not handle all types of datasets or edge cases perfectly, such as missing values or complex data types.

```python
import numpy as np
from scipy.stats import entropy
from sklearn.datasets import load_iris
import matplotlib.pyplot as plt

class TreeNode:
    def __init__(self, feature=None, threshold=None, left=None, right=None, *, value=None):
        self.feature = feature
        self.threshold = threshold
        self.left = left
        self.right = right
        self.value = value

    def is_leaf_node(self):
        return self.value is not None

class DecisionTree:
    def __init__(self, min_samples_split=2, max_depth=100, n_feats=None):
        self.min_samples_split = min_samples_split
        self.max_depth = max_depth
        self.n_feats = n_feats
        self.root = None

    @staticmethod
    def _entropy(y):
        hist = np.bincount(y)
        ps = hist / len(y)
        return entropy(ps)

    def _gain(self, X_column, y, threshold):
        parent_entropy = self._entropy(y)
        left_indices, right_indices = X_column < threshold, X_column >= threshold
        if len(np.unique(y[left_indices])) == 1 and len(np.unique(y[right_indices])) == 1:
            n_left, n_right = np.sum(left_indices), np.sum(right_indices)
            e_left, e_right = self._entropy(y[left_indices]), self._entropy(y[right_indices])
            child_entropy = (n_left / len(y)) * e_left + (n_right / len(y)) * e_right
            ig = parent_entropy - child_entropy
            return ig
        else:
            return 0

    def _best_split(self, X, y):
        best_idx, best_thr = None, None
        best_gain, best_gain_thr = -1, None
        for idx in range(X.shape[1]):
            X_column, thresholds = X[:, idx], np.unique(X[:, idx])
            for threshold in thresholds:
                gain = self._gain(X_column, y, threshold)
                if gain > best_gain:
                    best_gain = gain
                    best_idx = idx
                    best_thr = threshold
        return best_idx, best_thr

    def _build_tree(self, X, y, depth=0):
        n_samples, n_features = X.shape
        n_labels = len(np.unique(y))
        if (depth >= self.max_depth
            or n_labels == 1
            or n_samples < self.min_samples_split):
            leaf_value = np.argmax(np.bincount(y))
            return TreeNode(value=leaf_value)

        feat_idxs = np.random.choice(n_features, self.n_feats, replace=False)
        best_feat, best_thr = self._best_split(X, y)
        if best_feat is None:
            leaf_value = np.argmax(np.bincount(y))
            return TreeNode(value=leaf_value)

        left_idxs, right_idxs = X[:, best_feat] < best_thr, X[:, best_feat] >= best_thr
        left = self._build_tree(X[left_idxs], y[left_idxs], depth+1)
        right = self._build_tree(X[right_idxs], y[right_idxs], depth+1)
        return TreeNode(best_feat, best_thr, left, right)

    def fit(self, X, y):
        if not self.n_feats:
            self.n_feats = int(np.sqrt(X.shape[1]))
        self.root = self._build_tree(X, y)

    def _predict(self, x, node):
        if node.is_leaf_node():
            return node.value

        if x[node.feature] < node.threshold:
            return self._predict(x, node.left)
        return self._predict(x, node.right)

    def predict(self, X):
        return np.array([self._predict(xi, self.root) for xi in X])
```

