```java
import java.math.BigDecimal;
import java.math.MathContext;
import java.util.Scanner;

public class Calculator
{
    public static final BigDecimal PI = new BigDecimal(Math.PI);
    public static final BigDecimal TWO = new BigDecimal("2");
    public static final MathContext mc = new MathContext(20);

    static BigDecimal sin(BigDecimal x) {
        BigDecimal res = x, term = x;
        for (int i = 2; i <= 100; i += 2) {
            term = term.negate().multiply(x.pow(2)).divide(new BigDecimal(i * (i + 1)), mc);
            res = res.add(term);
        }
        return res;
    }

    static BigDecimal cos(BigDecimal x) {
        return sin(x.add(PI.divide(TWO, mc)));
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("Enter a number: ");
        BigDecimal x = scanner.nextBigDecimal();
        System.out.println("sin(" + x + ") = " + sin(x));
        System.out.println("cos(" + x + ") = " + cos(x));
    }
}
```

Here, we are using Taylor series to compute `sin` and `cos`. The Taylor series converges towards the true value more efficiently with more terms hence increasing accuracy. The precision of the calculations is limited by `MathContext`(here we set the precision to 20 decimal places).

