import java.util.*;
class Main{
    static boolean checkPrime(int n){
        if(n <= 1)
            return false;
        for(int i = 2; i * i <= n; i++){
            if(n % i == 0)
                return false;
        }
        return true;
    }
    static ArrayList<Integer> generateFiboSeries(int n){
        ArrayList<Integer> fiboSeries = new ArrayList<>();
        int a = 0, b = 1, c;
        if(n > 0)
          fiboSeries.add(a);
        if(n > 1)
          fiboSeries.add(b);
        c = a + b;
        while(c <= n){
            fiboSeries.add(c);
            a = b;
            b = c;
            c = a + b;
        }
        return fiboSeries;
    }
    public static void main (String[] args) {
        int n = 6;
        ArrayList<Integer> fibo = generateFiboSeries(n);
        String result = "";
        for(Integer number : fibo){
