    try:
        sorted_collection = sorted(collection)
        length = len(sorted_collection)

        if length == 0:
            return "Error: Empty Collection"

        if length % 2 == 0:
            median = (sorted_collection[length // 2] + sorted_collection[length // 2 - 1]) / 2
