type DataPoint struct {
	Timestamp time.Time
	Value     float64
}

type MQTTHandler struct {
	mqttClient paho.Client
	topic      string
}

type DataService struct {
	dbClient   influxdb.Client
	dbName     string
	mqttHandler *MQTTHandler
}

// Start MQTT client and subscribe to a topic
func (h *MQTTHandler) start() {
	opts := paho.NewClientOptions().AddBroker("tcp://broker.hivemq.com:8000")
	opts.SetClientID("go_mqtt_client")
	opts.SetConnectionLostHandler(func(c paho.Client, err error) {
		fmt.Printf("MQTT connection lost: %v", err)
	})

	client := paho.NewClient(opts)
	if token := client.Connect(); token.Wait() && token.Error() != nil {
		panic(token.Error())
	}

	h.mqttClient = client

	if token := client.Subscribe(h.topic, 1, nil); token.Wait() && token.Error() != nil {
		fmt.Println(token.Error())
		os.Exit(1)
	}
}

// Initialize InfluxDB client
func (s *DataService) start() {
	influxDB, err := influxdb.NewHTTPClient(influxdb.HTTPConfig{
		Addr: "http://localhost:8086",
	})

	if err != nil {
		log.Fatal(err)
	}

	s.dbClient = influxDB
	s.mqttHandler = &MQTTHandler{topic: "sensor/data"}
	s.mqttHandler.start()

	go s.listenAndStore()
}

// Listen to MQTT topic and store ingoing data into InfluxDB
func (s *DataService) listenAndStore() {
	for {
		// Listen to our MQTT topic
		msg := <-s.mqttHandler.msgChan

		// Transform the payload into a struct and insert it into the DB.
		var dp DataPoint
		b := []byte(msg.Payload())
		err := json.Unmarshal(b, &dp)
		if err != nil {
			log.Printf("could not decode message payload: %v", err)
			continue
		}

		// Write point to InfluxDB
		bp, err := influxdb.NewBatchPoints(
			influxdb.BatchPointsConfig{Database: s.dbName, Precision: "s"},
		)
		if err != nil {
			log.Printf("error creating batch points: %v", err)
			continue
		}

		point, err := influxdb.NewPoint(
			s.mqttHandler.topic, 
			map[string]string{}, 
			map[string]interface{}{"value": dp.Value}, 
			dp.Timestamp,
		)
		if err != nil {
			log.Printf("error creating new point: %v", err)
			continue
		}

		bp.AddPoint(point)
		s.dbClient.Write(bp)
	}
}

func main() {
	s := &DataService{dbName: "mydb"}
	s.start()

	// Keep the program running
	select {}
}

```
