public class WordSearch {
    public static void main(String[] args) {
        String filePath = "/path/to/text/file.txt";
        List<String> words = Arrays.asList("word1", "word2", "word3");  // list of words to search
        try {
            countWordOccurrences(filePath, words);
        } catch (IOException e) {
            System.out.println(e.getMessage());
        }
