    public static void countWordOccurrences(String filePath, List<String> words) throws IOException {
        File file = new File(filePath);
        if (!file.exists()) {  // Check if file exists
            System.out.println("The file " + filePath + " does not exist.");
            return;
        }

        Map<String, Integer> wordOccurrences = new HashMap<>();
        for (String word : words)
            wordOccurrences.put(word, 0);

        BufferedReader reader = new BufferedReader(new FileReader(file));

        String line;
        while ((line = reader.readLine()) != null) {
            for (String word : words) {
                int count = line.toLowerCase().split(word.toLowerCase(), -1).length - 1;
                wordOccurrences.put(word, wordOccurrences.get(word) + count);
            }
        }
        reader.close();

        for (Map.Entry<String, Integer> entry : wordOccurrences.entrySet())
            System.out.println("The word \"" + entry.getKey() + "\" appears " + entry.getValue() + " times.");
    }
}
