def median_height(height_list):
    if not isinstance(height_list, list):
        raise ValueError("Input should be a list")
    for height in height_list:
        if not isinstance(height, (int, float)):
            raise ValueError("All elements in the list should be numbers")
    sorted_list = sorted(height_list)
    size = len(sorted_list)
    if size % 2 == 1:
        return sorted_list[size//2]
    else:
        return (sorted_list[size//2 - 1] + sorted_list[size//2]) / 2
```

