import java.util.*;

public class MessageTransformer {
    private static final int MAX_WORD_LENGTH = 10;

    public static class InvalidMessageFormatException extends Exception {
        public InvalidMessageFormatException(String message) {
            super(message);
        }
    }

    public static String transformMessage(String message) throws InvalidMessageFormatException {
        // check for null and blank messages
        if (message == null || message.trim().isEmpty()) {
            throw new InvalidMessageFormatException("Invalid message format: message cannot be null or blank.");
        }

        // transform the message to upper case and split it into individual words
        String[] words = message.toUpperCase().split("\\s+");

        List<String> transformedWords = new LinkedList<>();
        for (String word : words) {
            if (word.isEmpty()) {
                continue;
            }
            // If word is longer than the maximum length, split it and add the segments to the list separately
            while (word.length() > MAX_WORD_LENGTH) {
                transformedWords.add(word.substring(0, MAX_WORD_LENGTH));
                word = word.substring(MAX_WORD_LENGTH);
            }
            transformedWords.add(word);
        }

        // reverse the order of the words and join them together again
        Collections.reverse(transformedWords);
        return String.join(" ", transformedWords);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Please enter your message: ");
        String message = scanner.nextLine();

        try {
            String transformedMessage = transformMessage(message);
            System.out.println("Transformed Message: " + transformedMessage);
        } catch (InvalidMessageFormatException e) {
            System.out.println(e.getMessage());
        }
    }
}
```
Note: This Java solution will first uppercase all characters of the input string, then split it by spaces to obtain individual words. Each word is then checked to see if its length is more than 10, in which case the word is split at the 10th character and moved to the next line. The words are then added into an ArrayList, which is reversed and joined together to form the final message. If the input message is null or empty, an InvalidMessageFormatException is thrown.

