Here's a simple C++ program that will calculate the product of the diagonals in a 3x3 matrix:

```cpp
#include <iostream>

int main() {
    int A[3][3] = { {2, 1, 3}, {4, 5, 6}, {7, 8, 9} };

    int productMain = 1;
    int productSecondary = 1;

    for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
            // checking the condition for principal diagonal
            if (i == j)
                productMain *= A[i][j];
            // checking the condition for secondary diagonal
            if (i == 3 - j - 1)
                productSecondary *= A[i][j];
        }
    }

    std::cout << "Product of elements in main diagonal: " << productMain << std::endl;
    std::cout << "Product of elements in secondary diagonal: " << productSecondary << std::endl;

    return 0;
}
```
This will calculate both the product of main diagonal (from top left to bottom right) and the product of secondary diagonal (From top right to bottom left).

