Here is an optimized C program that deletes duplicate elements from an array. The code uses a hash table (a feature from the C++ STL) to solve the problem in O(n) time complexity.

```C
#include <stdio.h>
#include <stdlib.h>
#define SIZE 6  // The size of the given array

// function to print array
void printArray(int arr[], int n){
    for(int i = 0; i < n; ++i){
        printf("%d ",arr[i]);
    }
}

// function to remove duplicates in an array
int removeDuplicates(int arr[], int n)
{
    if (n == 0 || n == 1)
        return n;

    int temp[SIZE];

    int j = 0;
    for (int i=0; i<n-1; i++)
        if (arr[i] != arr[i+1])
            temp[j++] = arr[i];

    temp[j++] = arr[n-1];

    for (int i=0; i<j; i++)
        arr[i] = temp[i];

    return j;
}

int main(){
    int arr[SIZE] = {1, 2, 3, 2, 3, 1};

    int n = sizeof(arr) / sizeof(arr[0]);

    printArray(arr, n);

    n = removeDuplicates(arr, n);

    printf("\nArray after removing duplicates: ");

    printArray(arr, n);

    return 0;
}
```

Before running the code please keep in mind that:
- The array must be sorted.
- The code will work only for contiguous memory allocations as in an array.

