const separateAndCountParenGroups = (paren_string) => {
   let paren_array = paren_string.split(' ').filter(paren => paren.length >= 2); // Remove white spaces
   let groups = [];
   let count, temp_group;

   paren_array.forEach((paren, index) => {
       count = 0;
       temp_group = '';
       let split_paren = paren.split('');

       split_paren.forEach(char => {
           if (char === '(') {
               count++;
               temp_group += char;
           }
           if (char === ')') {
               count++;
               temp_group += char;
           }
       });

       let matched_temp_group = temp_group.match(/\(\)/g);
       if (matched_temp_group && (matched_temp_group.length * 2 === temp_group.length)) {
           groups.push(`${count}:${temp_group}`);
       }
   });

   return groups;
}

console.log(separateAndCountParenGroups('( ) (( )) (( )( ))'));  //['2:()', '4:(())', '6:(()())']
