app.use(cookieParser());
app.all("*", (req, res) => {
  proxy.web(req, res, {
    target: servers[serverIndex]
  });

  serverIndex = (serverIndex + 1) % servers.length;
});

const server = https.createServer(options, app);
http.createServer(app).listen(3000);
server.listen(3001);
```

