```cpp
#include <iostream>
using namespace std;

class CustomStackAllocator
{
private:
    static const size_t MemoryPoolSize = 1024;
    static const int MaxNumberOfStacks = 10;

    struct MemoryBlock
    {
        char memory[MemoryPoolSize];
        MemoryBlock* next;
    };

    struct StackMemoryBlock
    {
        size_t stackIndex;
        size_t blockSize;
        StackMemoryBlock* next;
    };

    MemoryBlock* memoryPool;
    StackMemoryBlock* freeStackMemoryBlocks;
    StackMemoryBlock* usedStackMemoryBlocks;

    void AllocateMemoryPool()
    {
        memoryPool = new MemoryBlock;
        memoryPool->next = nullptr;
    }

    StackMemoryBlock* AllocateStackMemoryBlock()
    {
        StackMemoryBlock* block = new StackMemoryBlock;
        block->blockSize = MemoryPoolSize / MaxNumberOfStacks;
        block->next = nullptr;
        return block;
    }

    void InitializeMemoryManager()
    {
        AllocateMemoryPool();

        freeStackMemoryBlocks = AllocateStackMemoryBlock();
        StackMemoryBlock* current = freeStackMemoryBlocks;
        for (int i = 1; i < MaxNumberOfStacks; i++)
        {
            current->next = AllocateStackMemoryBlock();
            current = current->next;
        }
    }

public:
    CustomStackAllocator()
    {
        InitializeMemoryManager();
    }

    ~CustomStackAllocator()
    {
        StackMemoryBlock* current = freeStackMemoryBlocks;
        while (current)
        {
            StackMemoryBlock* temp = current;
            current = current->next;
            delete temp;
        }

        current = usedStackMemoryBlocks;
        while (current)
 {
            StackMemoryBlock* temp = current;
            current = current->next;
            delete temp;
        }
    }

    void* Allocate(size_t index)
    {
        if (index < MaxNumberOfStacks)
        {
            if (freeStackMemoryBlocks)
            {
                StackMemoryBlock* block = freeStackMemoryBlocks;
                freeStackMemoryBlocks = block->next;

                block->stackIndex = index;
                block->next = usedStackMemoryBlocks;
                usedStackMemoryBlocks = block;

                return memoryPool->memory + (block->blockSize * index);
            }
            else
            {
                throw std::runtime_error("No stack memory blocks left.");
            }
        }
        else
        {
            throw std::runtime_error("Index out of range.");
        }
    }

    void Deallocate(void* ptr)
    {
        if (ptr)
        {
            StackMemoryBlock* prev = nullptr;
            StackMemoryBlock* current = usedStackMemoryBlocks;
            while (current)
            {
                if (memoryPool->memory + (current->stackIndex * current->blockSize) == ptr)
                {
                    if (prev)
                    {
                        prev->next = current->next;
                    }
                    else
                    {
                        usedStackMemoryBlocks = current->next;
                    }

                    current->next = freeStackMemoryBlocks;
                    freeStackMemoryBlocks = current;

                    return;
                }

                prev = current;
                current = current->next;
            }
        }
    }
};

class Stack
{
private:
    CustomStackAllocator* allocator;
    int index;
    int* data;
    int top;

public:
    Stack(CustomStackAllocator* allocator) : allocator(allocator), index(-1), data(NULL), top(-1)
    {
        // Assuming Stack size to be 32 (number of elements)
        data = static_cast<int*>(allocator->Allocate(32));
    }

    ~Stack()
    {
        allocator->Deallocate(data);
    }

    void Push(int value)
    {
        if (top < 31)
        {
            top++;
            data[top] = value;
        }
        else
        {
            throw std::runtime_error("Stack is full.");
        }
    }

    int Pop()
    {
        if (top >= 0)
        {
            int value = data[top];
            top--;
            return value;
        }
        else
        {
            throw std::runtime_error("Stack is empty.");
        }
    }
};

int main()
{
    CustomStackAllocator allocator;
    Stack s1(&allocator);
    Stack s2(&allocator);

    s1.Push(1);
    s1.Push(2);

    s2.Push(3);
    s2.Push(4);

    cout << "s1: " << s1.Pop() << " " << s1.Pop() << endl;
    cout << "s2: " << s2.Pop() << " " << s2.Pop() << endl;
}
```

