```python
def selection_sort(arr, order='asc'):
    for i in range(len(arr)):
        index = i
        for j in range(i+1, len(arr)):
            if order == 'desc':
                if arr[j] > arr[index]:
                    index = j
            else:
                if arr[j] < arr[index]:
                    index = j
        arr[i], arr[index] = arr[index], arr[i]
    return arr

