Here, we will implement a singly linked list from scratch and add additional methods to reverse and sort the linked list. To accomplish this, we'll have to implement the following methods:

- get(int index): Traverse the linked list to the `index` and return the value of the node. If index is invalid, return -1.
- addAtHead(int val): Create a new node with the given value and point its next pointer to the current head. Then update the head to the new node.
- addAtTail(int val): Traverse the list to the last node and append a new node after the tail.
- addAtIndex(int index, int val): Traverse to the `index - 1` node and insert a new node after it.
- deleteAtIndex(int index): Traverse to the `index - 1` node and update its next pointer to the next-next node.
- reverse(): Create two pointers, one for prev and one for next. Iterate over the linked list, for each node set the next to the prev, update the prev to current and current to next.
- sort(): Implement the bubble sort algorithm to sort the linked list; for each node, compare it with every node after it and swap if it's greater.

Here is the Python implementation of the above:

```python
class Node:
    def __init__(self, x):
        self.val = x
        self.next = None

class MyLinkedList:
    def __init__(self):
        self.size = 0
        self.head = Node(0)  # sentinel node as pseudo-head

    def get(self, index: int) -> int:
        if index < 0 or index >= self.size:
            return -1
        curr = self.head
        for _ in range(index + 1):  # index steps needed to move to node at index
            curr = curr.next
        return curr.val

    def addAtHead(self, val: int) -> None:
        self.addAtIndex(0, val)

    def addAtTail(self, val: int) -> None:
        self.addAtIndex(self.size, val)

    def addAtIndex(self, index: int, val: int) -> None:
        if index > self.size:
            return
        if index < 0: 
            index = 0
        self.size += 1
        pred = self.head
        for _ in range(index):
            pred = pred.next
        to_add = Node(val)
        to_add.next = pred.next
        pred.next = to_add

    def deleteAtIndex(self, index: int) -> None:
        if index < 0 or index >= self.size:
            return
        self.size -= 1
        pred = self.head
        for _ in range(index):
            pred = pred.next
        pred.next = pred.next.next

    def reverse(self) -> None:
        prev = None
        curr = self.head
        while curr is not None:
            next_node = curr.next
            curr.next = prev
            prev = curr
            curr = next_node
        self.head = prev

    def sort(self) -> None:
        curr = self.head
        while curr is not None:
            next_node = curr.next
            while next_node is not None:
                if curr.val > next_node.val:
                    curr.val, next_node.val = next_node.val, curr.val
                next_node = next_node.next
            curr = curr.next
```

This will allow basic operations with linked list like adding, deleting, accessing elements at specific index, reversing and sorting it.

