        return self.p[k]

    def union(self, k, v):
        xr = self.find(k)
        yr = self.find(v)
        self.p[xr] = yr

def solve(pairs):
    N = max(v for x, y, w in pairs) + 1
    dsu = DSU(N)
    edge = [None]*N
    graph = collections.defaultdict(list)
    pairs.sort(key=lambda k: -k[2])

    for x, y, w in pairs:
        xr = dsu.find(x)
        ss = xr, len(graph[xr])
        if edge[xr] is None:
            edge[xr] = (y, len(graph[xr]), w)
        else:
            graph[xr].append([y - edge[xr][0], ss])
        dsu.p[xr] = xr = dsu.find(x + 1)

    for x, y, w in pairs[::-1]:
        xr = dsu.find(x)
        if edge[xr] is not None and (y, len(graph[xr]), dsu.find(x+1), len(graph[dsu.find(x+1)])) != edge[xr]:
            graph[xr].append([y - edge[xr][0], edge[xr][2]])
        edge[xr] = None

    size = [0]*N
    dp = [0]*N
    size[-1] = 1
    dp[-1] = 1
    for n in range(N-2, -1, -1):
        vals = collections.defaultdict(int)
        vals[0] = 1
        for dw, (nx, j) in graph[n]:
            for v in list(vals):
                vals[v + dw] = (vals[v + dw] + vals[v] * size[nx]) % MOD * dp[nx]**(j+1) % MOD

        dp[n] = vals.popitem()[1]
        size[n] = sum(size[nx] % MOD for nx, _ in graph[n]) % MOD

    return dp[0] if len(list(vals)) == 1 else 2

def numberOfWays(pairs):
    if solve(pairs) == 1:
        return 1
    else:
        return 0
```

