int digit_product_sum(int n, int *product, int *digit_sum) 
{
    *product = 1;
    *digit_sum = 0;

    while (n != 0) 
    {
        int digit = n % 10;
        *product *= digit;
        *digit_sum += digit;
        n /= 10;
    }
} 

int compare(const void *a, const void *b) 
{
    Number *num1 = (Number *)a;
    Number *num2 = (Number *)b;

