Here is a simple implementation of an AVL Tree in Rust:

```rust
#[derive(Debug)]
pub struct Node {
    value: i32,
    left: Option<Box<Node>>,
    right: Option<Box<Node>>,
    height: u8,
}

#[derive(Debug)]
pub struct AVLTree {
    root: Option<Box<Node>>,
}

impl Node {
    fn new(value: i32) -> Self {
        Node {
            value,
            left: None,
            right: None,
            height: 1,
        }
    }

    fn height(&self) -> u8 {
        self.height
    }

    fn get_balance(&self) -> i8 {
        let left_height = match &self.left {
            Some(node) => node.height as i8,
            None => 0
        };

        let right_height = match &self.right {
            Some(node) => node.height as i8,
            None => 0
        };

        left_height - right_height
    }
}

impl AVLTree {
    pub fn new() -> Self {
        AVLTree { root: None }
    }

    pub fn insert(&mut self, value: i32) {
        let node = Self::insert_node(self.root.take(), value);
        self.root = Some(node);
    }

    // You can implement the deletion and the search function using this template.

    fn insert_node(mut node_option: Option<Box<Node>>, value: i32) -> Box<Node> {
        match node_option {
            None => Box::new(Node::new(value)),
            Some(mut node) => {
                if value < node.value {
                    let left = Self::insert_node(node.left.take(), value);
                    node.left = Some(left);
                } else if value > node.value {
                    let right = Self::insert_node(node.right.take(), value);
                    node.right = Some(right);
                } else {
                    panic!("value already exists in the AVLTree!");
                }

                node.height = 1 + Self::max(Self::height(&node.left), Self::height(&node.right));
                node_option = Some(node);
                node_option = Self::balance(node_option);
                node_option.unwrap()
            }
        }
    }

    // And so on...
}

```

