def findRootWithConstantSpace(nodes):
    total_sum = sum(node.val for node in nodes)
    child_node_sum = sum(child.val for node in nodes for child in node.children)
    for node in nodes:
        if total_sum - node.val == child_node_sum:
            return node
    return None
```

