```JavaScript
const express = require('express');
const router = express.Router();

// ROAC middleware
const permit = (...allowedRights) => {
  const isAllowed = right => allowedRights.indexOf(right) > -1;

  return (req, res, next) => {
    if (req.user && req.user.rights.some(isAllowed)) next();
    else res.status(403).json({message: 'Forbidden'}); // user is not authorized.
  }
}

// express routes
