  res.json({message: 'You are allowed to read this resource.'});
});

router.post("/protected_resource", permit('write'), (req, res) => {
  res.json({message: 'You are allowed to write this resource.'});
});

// error handling middleware.
router.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).send('Something broke!');
});

module.exports = router;
```
In the above code, `permit` middleware is used for access control and is reusable across routes and applications. An error-handling middleware at the end helps in the case of system failures or anomalies.

