Here's an example of how you could build an express route for handling different types of browser requests, with basic error handling and data validation/sanitization. 

```javascript
const express = require('express');
const app = express();
const bodyParser = require('body-parser');
const sanitizeHtml = require('sanitize-html');

// To handle JSON payloads
app.use(bodyParser.json());
// To handle URL-encoded data
app.use(bodyParser.urlencoded({ extended: true }));

app.get('/Home', function (req, res) {
    // validate and sanitize data
    const sanitizedData = sanitizeHtml(req.query.data);
    // Action for GET request
    res.send(`GET request to the homepage: ${sanitizedData}`);
});

app.post('/Home', function (req, res) {
    // validate and sanitize data
    const sanitizedData = sanitizeHtml(req.body.data);
    // Action for POST request
    res.send(`POST request to the homepage: ${sanitizedData}`);
});

app.put('/Home', function (req, res) {
    // validate and sanitize data
    const sanitizedData = sanitizeHtml(req.body.data);
    // Action for PUT request
    res.send(`PUT request to the homepage: ${sanitizedData}`);
});

app.delete('/Home', function (req, res) {
    // validate and sanitize data
    const sanitizedData = sanitizeHtml(req.body.data);
    // Action for DELETE request
    res.send(`DELETE request to the homepage: ${sanitizedData}`);
});

// Error handling middleware
app.use(function (err, req, res, next) {
    console.error(err.stack);
    res.status(500).send({error: 'An error occurred processing your request'});
});

app.listen(3000, function () {
    console.log('Example app listening on port 3000!');
});
```

This example uses the 'body-parser' middleware for parsing incoming request bodies in a middleware before handlers and it supports both JSON and URL-encoded format. It uses the 'sanitize-html' library for sanitizing the incoming data to remove any malicious code. The error handling middleware is at the bottom of the chain, it receives any errors that are thrown in other middleware or routes.

Remember, it's a basic example. Depending on your use case, you need to adjust the solution. For example, if you deal with session-based requests, you need to use a middleware like 'cookie-parser' or 'express-session', when dealing with cross-origin requests, you need 'cors' middleware, and you may want to use some kind of logging improvement like 'Morgan' depends on your needs. Also, you will need to adjust the data validation and sanitization to properly deal with the specific type and structure of data that your app will receive. 

