        {{2, 3}, {4, 5}, {6, 7}}
    };

    // For each 2D vector in the 3D vector
    for (auto &two_d : arr) {
        // First sort each 1D vector in ascending order
        for (auto &one_d : two_d) {
            sort(one_d.begin(), one_d.end());
        }
        // Then sort the 2d vector in ascending order by sum of each 1D vector
        sort(two_d.begin(), two_d.end(), [](auto &a, auto &b) {return getSum(a) < getSum(b);});
    }

    // Now sort the 3D vector in ascending order by the sum of each 2D vector
    sort(arr.begin(), arr.end(), [](auto &a, auto &b) {return getSum(a) < getSum(b);});

    // Print out the sorted 3D vector
    for (auto &two_d : arr) {
        for (auto &one_d : two_d) {
            cout << "{" ;
            for (auto &el : one_d) {
                cout << el << ",";
            }
            cout << "}, ";
        }
        cout << endl;
    }
    return 0;
}
```

