       Node* fast;
       Node* slow;
       slow = head;
       fast = head->next;

       // Fast advances two nodes, and slow advances one node
       while (fast != NULL) {
           fast = fast->next;
           if (fast != NULL) {
               slow = slow->next;
               fast = fast->next;
           }
