def countPalindromicSubsequences(self, S, K, C):
    MOD = 10**9 + 7
    W = len(S)
    alphabet = 'abcd'
    S = ' ' + S + ' '
    #Previous and next
    B = [[0] * (W+2) for _ in range(4)]
    F = [[0] * (W+2) for _ in range(4)]
    B[3] = [0]*(W+2)
    F[3] = [W+1]*(W+2)
    for i in range(W):
        B[S[i+1] - 'a'][i+1] = i
        F[S[i+1] - 'a'][W-i] = W-i+1
    for c in range(4):
        for i in reversed(range(W+1)):
            B[c][i] = max(B[c][i],B[c][i+1])
        for i in range(1, W + 2):
            F[c][i] = min(F[c][i], F[c][i - 1])

    dp = [[0] * (W+2) for _ in range(K+1)]
    dp[0][W + 1] = 1

    for k in range(1, K+1):
        for w in reversed(range(1, W+2)):
            for c in range(4):
                if c not in map(lambda x: x - 'a', C):
                    continue
                i = B[c][w]
                j = F[c][i + k - 1]
                dp[k][i] += dp[k-1][j] % MOD;

    return sum(dp[K][i] for i in range(W+1)) % MOD;
```
