template <typename K, typename V>
class Dictionary {
public:
    Dictionary() = default;

    void insert(const K& key, const V& value) {
        data[key] = value;
    }

    V getValue(const K& key) {
        if(data.find(key) != data.end()) {
            return data[key];
        } else {
            throw std::runtime_error("Key not found in the dictionary"); 
        }
    }

