def check_duplicate(lst: list, num: int) -> bool:
    for i in lst:
        if i == num:
            return True
    return False

def insert_in_sorted_order(lst: list, num: int) -> list:
    if len(lst) == 0 or lst[-1] < num:
        lst.append(num)
    else:
        for i in range(len(lst)):
            if lst[i] > num:
                lst.insert(i, num)
                break
    return lst
