#include <string>

std::string bitwise_xor(const std::string& s, int key) {
    /*  
    returns encoded string with bitwise xor operation.
    */
    std::string xor_string = "";

    for (char c : s) {
        xor_string += char(int(c) ^ key); // xor operation with a random number for simplicity
    }

    return xor_string;
}

std::string multiple_encode(std::string s, int key_start, int times){
    /*
    Encodes the given string multiple times using a different key for each operation.
    */
    for (int i = 0; i < times; ++i) {
        s = bitwise_xor(s, key_start + i);
    }

    return s;
}

std::string decode_bitwise_xor(const std::string& s, int key) {
    /*
    Reverses the effect of the initial bitwise_xor function.
    */
    return bitwise_xor(s, key); // xor operation is its own inverse
}

std::string multiple_decode(std::string s, int key_start, int times){
    /*
    Decodes a string that has been encoded multiple times using different keys, so long as the initial key is known and the string was encoded using incrementing keys.
    */
    for (int i = times - 1; i >= 0; --i) {
        s = decode_bitwise_xor(s, key_start + i);
    }

    return s;
}
```

