To find the middle element of a singly linked list, you can use the Slow and Fast Pointer Approach, also known as the Hare & Tortoise Algorithm:

1. Create two pointers, a slow-pointer and a fast-pointer and initialize them to the head of the linked list.
2. Move the slow-pointer by one node at a time and the fast-pointer by two nodes at a time.
3. When the fast-pointer reaches the end of the linked list, the slow-pointer will be at the middle of the linked list.

Here is the code for the above method in C programming language:

```c
#include<stdio.h>
#include<stdlib.h>

struct node {
    int data;
    struct node *next;
};

void findMiddle(struct node *head) {
    struct node *slow_ptr = head;
    struct node *fast_ptr = head;

    if (head != NULL) {
        while (fast_ptr != NULL && fast_ptr->next != NULL) {
            fast_ptr = fast_ptr->next->next;
            slow_ptr = slow_ptr->next;
        }
        printf("The middle element is [%d]\n", slow_ptr->data);
    }
}

void push(struct node **head_ref, int new_data) {
    struct node *new_node = (struct node *) malloc(sizeof(struct node));
    new_node->data  = new_data;
    new_node->next = (*head_ref);
    (*head_ref)    = new_node;
}

int main() {
    struct node *head = NULL;
    int i;

    for (i = 5; i > 0; i--) {
        push(&head, i);
        findMiddle(head);
    }

    return 0;
}
```

