        for (double num : numArray) {
            sum += num;
        }
        double mean = sum / n;
        System.out.println("Mean: " + mean);

        // Calculate Median
        double median;
        if (n % 2 == 0)
            median = ((double)numArray[n / 2] + (double)numArray[n / 2 - 1]) / 2;
