package main

import "fmt"

// Function name: sipNectar
// Parameters:
// - nectarSipped: Amount of nectar already sipped.
// - cluster_count: cluster count
// - cluster_needs: List of nectar needs for each cluster.
// - remaining: Amount of remaining nectar.
func sipNectar(nectarSipped int, cluster_count int, cluster_needs []int, remaining int) ([]int, error) {
	// Initialize a variable to calculate the sum of nectar needs in the cluster
	clusterTotalNeed := 0
	for _, need := range cluster_needs {
		// Summing up the nectar needs in the cluster
		clusterTotalNeed += need
	}

	// Checking if remaining nectar is less than the cluster's total need
	if clusterTotalNeed > remaining {
		// If it is, sip all remaining nectar
		nectarSipped += remaining
		remaining = 0
	} else {
		// If it's not, sip only what's needed
		nectarSipped += clusterTotalNeed
		remaining -= clusterTotalNeed
	}

	// Returning the result as a list
	return []int{nectarSipped, remaining}, nil
}

func main() {
	res, _ := sipNectar(5, 3, []int{2, 3, 4}, 10)
	fmt.Println(res)
}
```
