using namespace std;

vector<int> prime_factors(int num){
    int n = num;
    vector<int> prime_factors;
    for (int i = 2; i <= n;) {
        if (n % i == 0) {
            prime_factors.push_back(i);
            n /= i;
        }
        else {
            i++;
        }
    }
    return prime_factors;
}

int count_divisors(int num) {
    vector<int> factors = prime_factors(num);
    int divisors = 1;

    int i = 0;
    while (i < factors.size()) {
        int cnt = 1;
        int cur = factors[i];
        while (i < factors.size() && factors[i] == cur) {
            cnt++;
            i++;
        }
        divisors *= cnt;
    }
    return divisors;
}

bool is_perfect(int num) {
    int sum = 1;

    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) {
            int diff = num/i;
            sum += i;
            if(i != diff) sum += diff;
        }
    }
    return sum == num;
}

int main()
{
