char *longest_oscillating_subseq(char  *s) {
    int n = strlen(s);

    char val[2] = {'1', '0'};
    int *dp = (int*) malloc(n * sizeof(int));
    for(int i = 0; i < n; i++) dp[i] = 1;

    int *pos = (int*) malloc(n * sizeof(int));
    for(int i = 0; i < n; i++) pos[i] = -1;

    int best_end = 0;

    for(int i = 1; i < n; i++) {
        for(int j = 0; j < i; j++) {
            if(s[i] == s[j])
                continue;
            else if(dp[j]+1 > dp[i] && s[i] == val[dp[j] % 2]) {
                dp[i] = dp[j]+1;
                pos[i] = j;
            }
        }
        if(dp[i] > dp[best_end])
            best_end = i;
    }

    char *osci_subseq = (char*) malloc((dp[best_end]+1) * sizeof(char));
    int k=dp[best_end];
    osci_subseq[k] = '\0';
    k--;
    int i = best_end;
    while(i != -1) {
        osci_subseq[k] = s[i];
        k--;
        i = pos[i];
    }

    free(dp);
    free(pos);
    return osci_subseq;
}

