Here is a C++ solution using AVL tree, a self-balancing Binary Search Tree (BST) where the balance factor of every node is either -1, 0 or 1. 

Please note that this code doesn't support deletion function, as deleting a node in a binary tree is a complex process and can greatly increase the complexity of this code. Please note to support the deletion operation would greatly increase the complexity of this code

```cpp
#include<iostream>
using namespace std;

class Node{
public:
    int key;
    Node* left;
    Node* right;
    int height;
};

int height(Node* n){
    if(n==NULL){
        return 0;
    }
    return n->height;
}

int max(int a, int b){
    return (a>b)?a:b;
}

Node* newNode(int key){
    Node* node=new Node();
    node->key=key;
    node->left=NULL;
    node->right=NULL;
    node->height=1;
    return(node);
}

Node* rightRotate(Node* y){
    Node* x=y->left;
    Node* T2=x->right;
    x->right=y;
    y->left=T2;
    y->height=max(height(y->left),height(y->right))+1;
    x->height=max(height(x->left),height(x->right))+1;
    return x;
}

Node* leftRotate(Node* x){
    Node* y=x->right;
    Node* T2=y->left;
    y->left=x;
    x->right=T2;
    x->height=max(height(x->left),height(x->right))+1;
    y->height=max(height(y->left),height(y->right))+1;
    return y;
}

int getBalance(Node* n){
    if(n==NULL){
        return 0;
    }
    return height(n->left)-height(n->right);
}

Node* insert(Node* node,int key){
    if(node==NULL){
        return(newNode(key));
    }
    if(key<node->key){
        node->left=insert(node->left,key);
    }
    else if(key>node->key){
        node->right=insert(node->right,key);
    }
    else if(key==node->key){
        return node;
    }

    node->height=1+max(height(node->left),height(node->right));
    int balance=getBalance(node);
    if(balance>1 && key<node->left->key){
        return rightRotate(node);
    }
    if(balance<-1 && key>node->right->key){
        return leftRotate(node);
    }
    if(balance>1 && key>node->left->key){
        node->left=leftRotate(node->left);
        return rightRotate(node);
    }
    if(balance<-1 && key<node->right->key){
        node->right=rightRotate(node->right);
        return leftRotate(node);
    }
    return node;
}

void printTree(Node* root, string indent, bool last){
    if(root!=NULL){
        cout<<indent;
        if(last){
            cout<<"R----";
            indent+="     ";
        }
        else{
            cout<<"L----";
            indent+="|    ";
        }
        cout<<root->key<<endl;
        printTree(root->left,indent,false);
        printTree(root->right,indent,true);
    }
}

int main(){
    Node* root = NULL; 
    root = insert(root, 10); 
    root = insert(root, 20); 
    root = insert(root, 30); 
    root = insert(root, 40); 
    root = insert(root, 50); 
    root = insert(root, 25); 
    root = insert(root, 25);
    cout<<"Binary Search Tree is:\n";
    printTree(root, "", true);
    return 0;
}
