typedef std::complex<double> Complex;

double trimmed_mean(std::vector<Complex> l, double trim_percentage) {
    // sort complex numbers by their magnitude
    std::sort(l.begin(), l.end(), [](Complex a, Complex b) {
        return (a.real() + a.imag()) < (b.real() + b.imag());
    });

    // calculate the size of the trimming
    size_t trim_size = static_cast<size_t>(l.size() * trim_percentage);

    // trim off the beginning and end of the vector
    l.erase(l.end() - trim_size, l.end());
    l.erase(l.begin(), l.begin() + trim_size);

    // calculate the sum
