```javascript
function convertAndFilter(arr) {
  try {
    let converted = arr.map(Number); 
    let isNumber = (n) => !isNaN(parseFloat(n)) && isFinite(n);
    converted.forEach((num, index) => {
      if(!isNumber(num)) {
        throw new Error(`Element at index ${index} is not a number`);
      }
    });
    let oddNumbers = converted.filter(num => num % 2 !== 0);
    return oddNumbers;
  } catch (err) {
    console.log(err);
    return;
  }
}

