In Javascript, you can use the Euclidean algorithm to calculate the greatest common divisor (GCD), and then calculate the least common multiple (LCM) using it. Note that the standard Javascript `Math` object does not have a `gcd` method, so we have to create our own.

Here is the equivalent Javascript code of your Python function:

```javascript
function gcd(a, b) {
    if (b === 0) {
        return a;
    }
    return gcd(b, a % b);
}

function lcm(w, x, y, z) {
    let temp = gcd(w, x);
    temp = (w * x) / temp;

    let temp1 = gcd(temp, y);
    temp = (temp * y) / temp1;

    temp1 = gcd(temp, z);
    temp = (temp * z) / temp1;

    return temp;
}

