import java.util.ArrayList;

class Main {
  public static void main(String[] args) {
    List<Integer> list = Arrays.asList(5, 2, null, 8, 1);
    List<Integer> sortedList = sortList(list);
    System.out.println(sortedList);
  }

  public static List<Integer> sortList(List<Integer> list) {
    List<Integer> sortedList = new ArrayList<>();
    for(Integer num : list) {
      if(num != null) {
        insertInOrder(sortedList, num);
      }
    }
    return sortedList;
  }

  private static void insertInOrder(List<Integer> list, Integer value) {
    for(int i = 0; i < list.size(); i++) {
      if(list.get(i) > value) {
        list.add(i, value);
        return;
      }
    }
    list.add(value);
  }
}
```

In the above code, the `sortList` method is used to sort the integers in the list and handle null values. The method iterates over each integer in the passed list and checks if it is not null before passing to the `insertInOrder` method. The `insertInOrder` method is used to insert an integer in its correct place in the list to maintain the list in sorted order.

