CREATE PROCEDURE calculate_median()
BEGIN
    -- Creating a temporary table to store median values
    DROP TEMPORARY TABLE IF EXISTS medians;
    CREATE TEMPORARY TABLE medians(
        `item_category` VARCHAR(255),
        `median` DECIMAL(10, 2)
    );

    -- Getting all distinct categories
    DECLARE done INT DEFAULT 0;
    DECLARE cur1 CURSOR FOR SELECT DISTINCT item_category FROM sales WHERE status ='sold';
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
    DECLARE @cat VARCHAR(255);

    OPEN cur1;
    read_loop: LOOP
        FETCH cur1 INTO @cat;

        IF done THEN
            LEAVE read_loop;
        END IF;

        -- Inserting median for each category into temporary table
        INSERT INTO medians
        SELECT 
            @cat,  
            (
                SELECT 
                    avg(tmp.cost) 
                FROM 
                (
                    SELECT 
                        cost 
                    FROM 
                        sales 
                    WHERE 
                        status = 'sold' AND
                        item_category = @cat
                    ORDER BY 
                        cost 
                    LIMIT 
                        2 - (SELECT COUNT(*) FROM sales WHERE status = 'sold' AND item_category = @cat) % 2    
                    OFFSET 
                        (SELECT COUNT(*) FROM sales WHERE status = 'sold' AND item_category = @cat) / 2
                ) as tmp
            );

    END LOOP;

    CLOSE cur1;
    SELECT * FROM medians;
END//
DELIMITER ;
