    public int calculateSum() {
        int sum = 0;
        for (int i = start; i <= end; i++) {
            if (i % 2 == 0){   // Check if the number is even.
                sum += (i * i);  // If the number is even, add the quadratic to sum.
            }
        }
        return sum;
    }

    // Getters and Setters
    public int getStart() {
        return start;
    }

    public void setStart(int start) {
        this.start = start;
    }

    public int getEnd() {
        return end;
    }

    public void setEnd(int end) {
        this.end = end;
    }
}
