use std::collections::HashMap;
use std::env;

fn fetch_customer_data() -> Result<Vec<HashMap<String, String>>, Box<dyn std::error::Error>> {
    // Connect to the database
    let conn = Environment::new()?
        .set_odbc_version_3()?
        .create_handle()?
        .connect(&env::var("AWS_AURORA_SERVER")?,
                 &env::var("USERNAME")?,
                 &env::var("PASSWORD")?)?;

    // Execute an SQL query
    let query = conn.execute("SELECT * FROM customer_details", ())?;

    // Fetch the results into a vector of hash map
    let mut results = Vec::new();

    while let Some(mut cursor) = query.fetch()? {
        let mut row = HashMap::new();
        for (i, col) in cursor.columns().unwrap().iter().enumerate() {
            row.insert(col.name()?, cursor.get_data::<&str>(i as u16)?.unwrap_or("").to_string());
        }
        results.push(row);
    }

    // Disconnect from the database
    conn.disconnect()?;

    Ok(results)
}

