```java
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

class Node {
    int data;
    Node next;

    Node(int d) {
        data = d;
        next = null;
    }
}

public class LinkedList {
    private volatile Node head;
    private final Lock lock = new ReentrantLock();

    public void push(int new_data) {
        Node new_node = new Node(new_data);
        if (head == null) {
            head = new_node;
        } else {
            Node last = head;
            while (last.next != null) {
                last = last.next;
            }
            last.next = new_node;
        }
    }

    public void delete(int key) {
        lock.lock(); //lock to ensure thread safety
        try {
            if (head == null)
                throw new RuntimeException("List is Empty!"); //throwing error if list is empty

            Node temp = head, prev = null;

            // If head node itself holds the key to be deleted
            if (temp != null && temp.data == key) {
                head = temp.next; // Changed head
                return;
            }

            // Search for the key to be deleted
            while (temp != null && temp.data != key) {
                prev = temp;
                temp = temp.next;
            }

            // If key was not present in linked list
            if (temp == null)
                throw new RuntimeException("Element not found"); //throwing error if element is not found

            // Unlink the node from linked list
            prev.next = temp.next;
        } finally {
            lock.unlock(); //unlock the lock
        }
    }

    public void printList() {
        Node temp = head;
        while (temp != null) {
            System.out.println(temp.data + " ");
            temp = temp.next;
        }
    }

    public static void main(String[] args) {
        LinkedList llist = new LinkedList();

        llist.push(7);
        llist.push(1);
        llist.push(3);
        llist.push(2);

        llist.printList();

        llist.delete(1); // Delete node at position 4

        System.out.println("\nLinked List after Deletion at position 1: ");
        llist.printList();
    }
}
```

In the above code, the `lock.lock()` and `lock.unlock()` are used to make the simultaneous modification of data thread-safe. 

