function matrixToJSON(matrix) {
    if (matrix == null || !Array.isArray(matrix) || matrix.length === 0) { throw new Error('Invalid input'); }
    let jsonMatrix = [];
    for (let i = 0; i < matrix.length; i++) {
        if (!Array.isArray(matrix[i])) { throw new Error('Invalid input'); }
        let row = [];
        for (let j = 0; j < matrix[i].length; j++) {
            row.push(matrix[i][j]);
        }
