std::vector<int> verifyBingo(const std::vector<int>& drawnNums, const std::vector<int>& markedNums)
{
    std::vector<int> differences; // vector to hold the differences between corresponding elements

    // size of vectors is supposed to be the same to perform 1-to-1 comparison
