char* reverseStr(const char* str) {
    int len = strlen(str);
    char* reversedStr = malloc((len + 1) * sizeof(char));

    if (reversedStr == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    int i;
    for (i = 0; i < len; ++i) {
        reversedStr[i] = str[len - i - 1];
    }
    reversedStr[len] = '\0';  // Don't forget the terminator

