import java.util.*;
import java.lang.*;

class Solution {

    class Pair implements Comparable<Pair> {
        int i, j, depth;

        Pair(int i, int j, int depth) {
            this.i = i;
            this.j = j;
            this.depth = depth;
        }

        @Override
        public int compareTo(Pair other) {
            return other.depth - this.depth;  
        }
    }

    public Pair<List<int[]>, Integer> optimalFillStrategy(List<List<Integer>> grid, int capacity) {
        PriorityQueue<Pair> maxHeap = new PriorityQueue<>();
        for(int i = 0; i < grid.size(); i++) {
            for(int j = 0; j < grid.get(0).size(); j++) {
                if(grid.get(i).get(j) == 1) {
                    maxHeap.add(new Pair(i, j, 1));
                }
            }
        }

        List<int[]> strategy = new ArrayList<>();
        int refills = 0;

        while(!maxHeap.isEmpty()) {
            for(int i = 0; i < capacity && !maxHeap.isEmpty(); i++) {
                Pair maxWell = maxHeap.poll();
                strategy.add(new int[]{maxWell.i, maxWell.j});
            }
            refills++;
        }

        return new Pair<>(strategy, refills);
    }
}

