                System.out.print("*");
            } 
            else 
            {
                System.out.print(" ");
            }
        }

        System.out.println();
    }

    public static void printEquilateralRow(int stars, int size) 
    {
        for (int i = 0; i < size; i++)
        {
            System.out.print(i < size-stars ? " " : "*");
        }

        for (int i = 0; i < size-1; i++) 
