Here is a simple JavaScript function that generates a SVG element for a zigzag line and allows the user to adjust the angles forming the zigzag. 

The solution required an understanding and utilisation of SVG element creation, Path (d) attribute, and event handling in JavaScript. This function assumes that the user will provide angles in degrees.

NOTE: Due to differences in rendering, SVG elements may not appear correctly inside a console and would ideally be placed within a webpage. 

```JavaScript
function createZigzag(id, width, height, numZigs, angles) {
    const angle1 = Math.PI * angles[0] / 180;
    const angle2 = Math.PI * angles[1] / 180;

    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
    svg.setAttribute('id', id);
    svg.setAttribute('width', width);
    svg.setAttribute('height', height);

    const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    path.setAttribute('stroke', 'black');
    path.setAttribute('fill', 'none');

    const step = width / (numZigs * 2);
    let d = `M 0,${height / 2} `;
    let goingUp = true;

    for(let i = 0; i < numZigs * 2; i += 2){
        const endX1 = step * (i + 1);
        const endY1 = goingUp ?
            height / 2 - Math.tan(angle1) * step / 2:
            height / 2 + Math.tan(angle1) * step / 2;

        const endX2 = step * (i + 2);
        const endY2 = goingUp ?
            height / 2 - Math.tan(angle2) * step :
            height / 2 + Math.tan(angle2) * step;

        d += `L ${endX1},${endY1} L ${endX2},${endY2} `;

        goingUp = !goingUp;
    }

    path.setAttribute('d', d);

    svg.appendChild(path);

    return svg;
}

function adjustAngles(id, angles) {
    const svg = document.getElementById(id);
    const path = svg.getElementsByTagName('path')[0];
    const d = path.getAttribute('d');
    const newD = d.split(' ').map((s, i) => {
        if (i % 4 === 2) {
            const angle = (i % 8 === 2) ? angles[0] : angles[1];
            const endY = Number(s.split(',')[1]);
            const newY = (i % 8 === 2) ?
                endY - Math.tan(Math.PI * angle / 180) * step / 2:
                endY + Math.tan(Math.PI * angle / 180) * step / 2;

            return `${s.split(',')[0]},${newY}`;
        }

        return s;
    }).join(' ');

    path.setAttribute('d', newD);

    return svg;
}
```
To use this function, `createZigzag("zigzag", 500, 500, 10, [45, 45])` would create a zigzag pattern of 10 zigzags within a SVG of width and height 500px, with each zig and zag at 45 degrees. 

`adjustAngles("zigzag", [60, 30])` would then adjust the zigzag's angles to be 60 and 30 degrees respectively.

