class WordDistance:

    def __init__(self, wordsDict):
        self.dict = {}
        for i in range(len(wordsDict)):
            if wordsDict[i] in self.dict:
                self.dict[wordsDict[i]].append(i)
            else:
                self.dict[wordsDict[i]] = [i]

    def shortest(self, word1, word2):
        indexes1 = self.dict[word1]
        indexes2 = self.dict[word2]
        i, j, min_distance = 0, 0, float('inf')
        while i < len(indexes1) and j < len(indexes2):
            min_distance = min(min_distance, abs(indexes1[i] - indexes2[j]))
            if indexes1[i] < indexes2[j]:
                i += 1
            else:
                j += 1
        return min_distance

    def longest(self, word1, word2):
        indexes1 = self.dict[word1]
        indexes2 = self.dict[word2]
        max_distance = max(abs(indexes1[0] - indexes2[-1]), abs(indexes2[0] - indexes1[-1]))
        return max_distance
```
