def monotonic(l: list, strict: bool = False):
    if len(l) < 2:
        return True

    if strict: 
        diff = [l[i + 1] - l[i] for i in range(len(l) - 1)]
        if all(x > 0 for x in diff) or all(x < 0 for x in diff):
            return True
        else:
