Here's a simplified implementation of a Ternary Tree with depth-first search algorithm in Objective-C:

In the given example, I'll define a node structure `Node`. Then, `insertNode:inNode:` function is used to construct the tree and `depthFirstSearch:inNode:` function to carry out the depth-first search operation:

```objective-c
#import <Foundation/Foundation.h>

typedef struct Node {
    int data;
    struct Node *left;
    struct Node *mid;
    struct Node *right;
} Node;

Node* newNode(int data) {
    Node *node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->left = NULL;
    node->mid = NULL;
    node->right = NULL;

    return node;
}

Node* insertNode(int data, Node *node) {
    if(node == NULL) {
        return newNode(data);
    }

    if(data < node->data) {
        node->left = insertNode(data, node->left);
    } else if(data > node->data) {
        node->right = insertNode(data, node->right);
    } else {
        node->mid = insertNode(data, node->mid);
    }

    return node;
}

void depthFirstSearch(Node *node) {
    if(node == NULL) {
        return;
    }

    depthFirstSearch(node->left);
    depthFirstSearch(node->mid);
    depthFirstSearch(node->right);

    printf("%d ", node->data);
}

int main() {
    @autoreleasepool {
        Node *root = NULL;

        int data[] = {13, 7, 6, 15, 19, 4, 9, 22, 1, 11, 3};
        int length = sizeof(data) / sizeof(int);

        for(int i = 0; i < length; i++) {
            root = insertNode(data[i], root);
        }

        depthFirstSearch(root);
    }

    return 0;
}
```
