def separate_paren_groups(paren_string: str, handle_errors: bool) -> List[str]:
    groups = []
    stack = []
    start = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                if handle_errors:
                    print(f'Unbalanced closing bracket at position {i}')
                else:
                    raise ValueError(f'Unbalanced closing bracket at position {i}')
            else:
                stack.pop()

            if not stack:
                groups.append(paren_string[start:i+1])
                start = i + 1

    if stack:
        if handle_errors:
            print('Unbalanced opening brackets')
        else:
            raise ValueError('Unbalanced opening brackets')

    return [group.replace(' ', '') for group in groups]
```

