def compute_mean(tup):
    numeric_elements = [el for el in tup if isinstance(el, (Number))]
    if not numeric_elements:
        raise ValueError("The tuple should contain at least one numeric value")
    return statistics.mean(numeric_elements)

def compute_median(tup):
    numeric_elements = [el for el in tup if isinstance(el, (Number))]
    if not numeric_elements:
        raise ValueError("The tuple should contain at least one numeric value")
    return statistics.median(numeric_elements)

def convert_nested(el):
    if isinstance(el, list):
        el = tuple(el)
    elif isinstance(el, dict):
        el = tuple(el.values())
    return el

def verify_and_compute_disparity(tup1, tup2):
    if not isinstance(tup1, Iterable) or not isinstance(tup2, Iterable):
        raise TypeError("Both inputs must be iterable")
    tup1, tup2 = map(tuple, (tup1, tup2))  # ensure inputs are tuples

