```python
import operator as op
import re

def parse_expression(expr):
    tokens = re.findall("[+ ^ * / \ ( ) \-]|\d+", expr)
    stack = []
    for token in tokens:
        if token in '+-*/^':
            while stack and stack[-1] in '+-*/^':
                yield stack.pop()
            stack.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack:
                x = stack.pop()
                if x == '(':
                    break
                yield x
        else:
            yield int(token)
    while stack:
        yield stack.pop()

expr = "4 / 2 * (1 + 5) ^ 2"
stack = list(parse_expression(expr))

print(stack)
```
