import { FormGroup, ValidatorFn } from '@angular/forms';

// A validator function requires to have a FormGroup as parameter and a validation error or null as return
export function MatchPasswordValidator(): ValidatorFn {
  return (formGroup: FormGroup) => {
    const password = formGroup.get('password');
    const confirmPassword = formGroup.get('confirmPassword');

    // Return null if controls haven't initialised yet
    if (!password || !confirmPassword) {
      return null;
    }

    // Return null if another validator has already found an error on the matchingControl
    if (confirmPassword.errors && !confirmPassword.errors.matchPassword) {
      return null;
