To handle negative discount values and non-numeric inputs, we need to raise specific exceptions for these cases. We can define a custom exception class for each case.

Here's the corrected code and I've included a series of test inputs at the end of the code.

```python
class NonNumericInputError(Exception):
    """Raised when the input is not a number"""
    pass

class NegativeDiscountError(Exception):
    """Raised when the discount value is negative"""
    pass

class DiscountCalculator:
    def __init__(self, price, cash_coupon, percentage_coupon):
        if isinstance(price, (int, float)) and isinstance(cash_coupon, (int, float)) and isinstance(percentage_coupon, (int, float)):
            if cash_coupon >= 0 and percentage_coupon >= 0:
                self.price = price
                self.cash_coupon = cash_coupon
                self.percentage_coupon = percentage_coupon
            else:
                raise NegativeDiscountError("Discount value must not be negative")
        else:
            raise NonNumericInputError("Price, Cash Coupon, and Percentage Coupon must be numbers")

    def calculate_discount(self):
        discounted_price = self.price - self.cash_coupon
        discounted_price = discounted_price * (100 - self.percentage_coupon) / 100
        return discounted_price

# Test with regular numeric inputs
discountCalculator = DiscountCalculator(100, 5, 10)
print(discountCalculator.calculate_discount()) # Output: 85.5

# Test with negative discount
