    discountCalculator = DiscountCalculator(100, -5, 10)
except NegativeDiscountError as e:
    print(e)  # Output: Discount value must not be negative

# Test with non-numeric input
try:
    discountCalculator = DiscountCalculator(100, "five", 10)
except NonNumericInputError as e:
    print(e)  # Output: Price, Cash Coupon, and Percentage Coupon must be numbers
