/// A MergeSort implementation in rust.

/// A helper function to merge two sorted slices depending on descending or not.
fn merge(arr: &mut [i32], l: usize, m: usize, r: usize, desc: bool) {
    let n1 = m - l + 1;
    let n2 = r - m;

    let l_arr = &arr[l..l+n1];
    let r_arr = &arr[m+1..m+n2+1];

    let mut i = 0;
    let mut j = 0;

    let mut k = l;

    while i < n1 && j < n2 {
        if desc ^ (l_arr[i] <= r_arr[j]) {
            arr[k] = l_arr[i];
            i += 1;
        } else {
            arr[k] = r_arr[j];
            j += 1;
        }
        k += 1;
    }

    while i < n1 {
        arr[k] = l_arr[i];
        i += 1;
        k += 1;
    }

    while j < n2 {
        arr[k] = r_arr[j];
        j += 1;
        k += 1;
    }
}

/// A recursive function to perform the merge sort, on the given slice by mutating it in place.
fn merge_sort_rec(arr: &mut [i32], l: usize, r: usize, desc: bool) {
    if l < r {
        let m = (l + r) / 2;

        merge_sort_rec(arr, l, m, desc);
        merge_sort_rec(arr, m + 1, r, desc);

        merge(arr, l, m, r, desc);
    }
}

/// A public function to initiate the merge sort on a vector and return the sorted vector.
pub fn merge_sort(mut array: Vec<i32>) -> Vec<i32> {
    // Odd sum check
    let odd_sum = (array.len() - 1) & 1;

    // Invoke the recursive merge sort function
    merge_sort_rec(&mut array, 0, array.len() - 1, odd_sum == 1);

    // Return the sorted array
    array
}
```

