func customStringList(_ lst: [String], _ reverse: Bool = false) -> [String] {
    let vowels = Set("aeiou")
    let specialChars = Set(" !@#$%^&*()-_=+[]{}|;:,.<>?")

    // Filter out the words with no vowels or containing special chars
    var newList = lst.filter { str in
        let containsVowels = str.lowercased().contains(where: { vowels.contains($0) })
        let containsSpecialChars = str.contains(where: { specialChars.contains($0) })
        return containsVowels && !containsSpecialChars
    }

    // Sort the list items by the word length in ascending order & lexicographic order
    newList = newList.sorted {a, b in
        if reverse {
            if a.count == b.count {
                return a.uppercased() > b.uppercased()
            }
            return a.count > b.count
        } else {
            if a.count == b.count {
                return a.uppercased() < b.uppercased()
            }
            return a.count < b.count
        }
    }

    return newList
}

