fn find_divisors(x: u32, depth: u32) -> Vec<u32> {
    let mut divisors = (1..=x).filter(|i| x % i == 0).collect::<Vec<_>>();
    if depth > 1 {
        let divisor_copy = divisors.clone();
        for div in divisor_copy {
            divisors.extend(find_divisors(div, depth - 1));
        }
    }
    divisors.sort_unstable();
    divisors.dedup();
    divisors
}

fn find_max_divisors(numbers: Vec<u32>, n: u32) -> Option<u32> {
