    sorted_numbers.sort_unstable();
    let mut max_divisors_count = 0;
    let mut max_divisors_num = None;

    for num in sorted_numbers {
        let div_count = find_divisors(num, n).len();
        if div_count as u32 > max_divisors_count {
            max_divisors_count = div_count as u32;
            max_divisors_num = Some(num);
        }
    }
    max_divisors_num
}
