fn compare_word_sequence(phrase1: &str, phrase2: &str) -> bool {
    // Create a Regex to find punctuation
    let re = Regex::new(r"[^\w\s]").unwrap();

    // Normalize both phrases: lowercase, remove punctuation and split by spaces
    let normalized_phrase1: Vec<&str> = re.replace_all(phrase1, "").to_lowercase().split_whitespace().collect();
    let normalized_phrase2: Vec<&str> = re.replace_all(phrase2, "").to_lowercase().split_whitespace().collect();

    // Compare the normalized phrases
