function squareAndCheck(n) {
    // Input validation
    if (n === null || n === undefined || typeof n !== 'number' || Number.isNaN(n) || !Number.isInteger(n) || n < 0) {
        return 'Invalid input';
    }
    let squaredNumber = n * n;

    if (isPrime(squaredNumber)) return squaredNumber;
    else return highestPrimeFactor(squaredNumber);
}

function isPrime(n) {
    if (n <= 1) return false;
    else if (n <= 3) return true;

    if (n % 2 === 0 || n % 3 === 0) return false;

    for (let i = 5; i * i <= n; i += 6) {
        if (n % i === 0 || n % (i + 2) === 0) return false;
    }

    return true;
}

function highestPrimeFactor(n) {
    let maxPrime = -1;
    while (n % 2 === 0) {
        maxPrime = 2;
        n >>= 1;
    }
    for (let i = 3; i <= Math.sqrt(n); i += 2) {
        while (n % i === 0) {
            maxPrime = i;
            n = n / i;
        }
    }
    if (n > 2) maxPrime = n;
    return maxPrime;
}
