import Foundation

func peculiarOrdering(_ lst: inout [Int?]) -> [Int] {
    // Remove nil values
    lst = lst.compactMap { $0 }

    // Check if the list is empty after removing nil values
    if lst.isEmpty {
        return []
    }

    var outList = [Int]()
    while !lst.isEmpty {
        // Add the smallest element
        if let minValue = lst.min() {
            outList.append(minValue)
            // Remove the smallest element
            lst.removeAll(where: { $0 == minValue })
        }

        // Check if list still has elements
        if !lst.isEmpty {
            // Add the largest element
            if let maxValue = lst.max(){
                outList.append(maxValue)
                // Remove the largest element
                lst.removeAll(where: { $0 == maxValue })
            }
        }
    }
    return outList
}
