#include<iostream>
using namespace std;

// Function to calculate GCD using Euclidean algorithm
int GCD(int a, int b) {
    while(b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

// Function to calculate LCM
int LCM(int a, int b) {
    // LCM(a, b) = |a*b|/GCD(a, b)
    // Using abs to handle negative numbers
    return abs(a * b) / GCD(a, b);
}

int main() {
