Below is a very basic example of how an API for an online store application could look in Python using Flask - a micro web framework. The assumptions here are that we already have a predefined product database which we can perform CRUD operations on: 

```python
from flask import Flask, jsonify, request
app = Flask(__name__)

# Sample product data
products = [
    {'id': 1, 'name': 'Product 1', 'price': 100},
    {'id': 2, 'name': 'Product 2', 'price': 200},
    {'id': 3, 'name': 'Product 3', 'price': 300},
]


@app.route('/products', methods=['GET'])
def get_products():
    return jsonify({'products': products})


@app.route('/product/<int:product_id>', methods=['GET'])
def get_product(product_id):
    product = [product for product in products if product['id'] == product_id]
    if len(product) == 0:
        abort(404)
    return jsonify({'product': product[0]})


@app.route('/product', methods=['POST'])
def create_product():
    if not request.json or not 'name' in request.json:
        abort(400)
    product = {
        'id': products[-1]['id'] + 1,
        'name': request.json['name'],
        'price': request.json.get('price', ""),
    }
    products.append(product)
    return jsonify({'product': product}), 201


@app.route('/product/<int:product_id>', methods=['PUT'])
def update_product(product_id):
    product = [product for product in products if product['id'] == product_id]
    if len(product) == 0:
        abort(404)
    if not request.json:
        abort(400)
    if 'name' in request.json and type(request.json['name']) != unicode:
        abort(400)
    if 'price' in request.json and type(request.json['price']) is not int:
        abort(400)
    product[0]['name'] = request.json.get('name', product[0]['name'])
    product[0]['price'] = request.json.get('price', product[0]['price'])
    return jsonify({'product': product[0]})


@app.route('/product/<int:product_id>', methods=['DELETE'])
def delete_product(product_id):
    product = [product for product in products if product['id'] == product_id]
    if len(product) == 0:
        abort(404)
    products.remove(product[0])
    return jsonify({'result': True})


if __name__ == '__main__':
    app.run()
```

