function countOccurrencesAndUniqueChars(mainStr, subStr) {
  var mainString = mainStr.toLowerCase();
  var subString = subStr.toLowerCase();

  var uniqueCharacters = [];
  for(var i = 0; i < subString.length; i++) {
    if (!uniqueCharacters.includes(subString[i])) {
      uniqueCharacters.push(subString[i]);
    }
  }

  var mainIndex = 0;
  var subIndex = 0;
  var count = 0;
  while(mainIndex < mainString.length) {
    if (mainString[mainIndex] == subString[subIndex]) {
      subIndex += 1;
      if(subIndex == subString.length) {
        count += 1;
        subIndex = 0;
      }
    } else if(subIndex > 0) {
      subIndex = 0;
    }
    mainIndex += 1;
  }

  return {occurrences: count, uniqueCharacters: uniqueCharacters.length};
}

