#include <stdio.h>

// Create function pointer types
typedef void(*SortFnInt)(int[], int);
typedef void(*SortFnFloat)(float[], int);
typedef void(*SortFnStruct)(struct data[], int);

// Struct
struct data {
    int id;
    char name[100];
};

// Compare function for qsort
int compare(const void *a, const void *b) {
    return ( *(int*)a - *(int*)b);
}

// Quicksort for integers
void quicksort(int arr[], int n) {
    qsort(arr, n, sizeof(int), compare);
}

// Insertion sort for floats
void insertionsort(float arr[], int n) {
    int i, j;
    float key;

    for (i = 1; i < n; i++) {
        key = arr[i];
        j = i - 1;

        while(j >= 0 && arr[j] > key) {
            arr[j+1] = arr[j];
            j = j - 1;
        }

        arr[j+1] = key;
    }
}

// Bubble sort for structs
void bubblesort(struct data arr[], int n) {
    int i, j;
    struct data temp;

    for (i = 0; i < n-1; i++) {
        for (j = 0; j < n-i-1; j++) {
            if (arr[j].id > arr[j+1].id) {
                temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
        }
    }
}

// Main function
int main() {
    // Declare and initialize example integer array, float array, and struct array
    int arrInt[] = {10, 7, 8, 9, 1, 5};
    float arrFloat[] = {10.1f, 7.7f, 8.45f, 9.33f, 1.99f, 5.75f};
    struct data arrStruct[] = {
        {2, "data2"},
        {1, "data1"},
        {3, "data3"},
    };

    int nInt = sizeof(arrInt)/sizeof(arrInt[0]);
    int nFloat = sizeof(arrFloat)/sizeof(arrFloat[0]);
    int nStruct = sizeof(arrStruct)/sizeof(arrStruct[0]);

    // choose sorting function
    SortFnInt sortFnInt = quicksort;
    SortFnFloat sortFnFloat = insertionsort;
    SortFnStruct sortFnStruct = bubblesort;

    // Call sorting function using function pointer
    sortFnInt(arrInt, nInt);
    sortFnFloat(arrFloat, nFloat);
    sortFnStruct(arrStruct, nStruct);

    // Print sorted arrays
    for(int i=0; i<nInt; i++)
        printf("%d ", arrInt[i]);
    printf("\n");

    for(int i=0; i<nFloat; i++)
        printf("%.2f ", arrFloat[i]);
    printf("\n");

    for(int i=0; i<nStruct; i++)
        printf("%d:%s ", arrStruct[i].id, arrStruct[i].name);
    printf("\n");

    return 0;
}
