Here is a Python-based solution using the `concurrent.futures` module that allows calculations to be divided among different threads for better performance. In programming, thread-safety is crucial to ensure that our shared data is consistently manipulated across different threads without causing unexpected outcomes.

```python
import concurrent.futures
import math
import threading

class HashedPrimes:
    def __init__(self, up_to):
        self.max = up_to
        self.hashed_primes = [0] * (up_to+1)
        self.populate_primes_dict()
        self.lock = threading.Lock()  # For thread-safety

    def populate_primes_dict(self):
        def is_prime(n):
            if n % 2 == 0 and n > 2: 
                return False
            for i in range(3, int(math.sqrt(n)) + 1, 2):
                if n % i == 0:
                    return False
            return True

        with concurrent.futures.ThreadPoolExecutor() as executor:
            for number, prime in enumerate(executor.map(is_prime, range(2, self.max + 1)), 2):
                if prime:
                    self.hashed_primes[number] = 1

    def is_prime(self, num):
        with self.lock:  # For thread-safety
            if num > self.max: # If number is beyond the bound
                raise ValueError(f'This class instance only stores primes up to {self.max}')
            return bool(self.hashed_primes[num])
```
