def transform_string(s):
    def helper(s, i, should_invert):
        res = []
        while i < len(s):
            if s[i] == '(':
                temp, i = helper(s, i+1, not should_invert)
                if should_invert:
                    res.append(temp[::-1])
                else:
                    res.append(temp)
            elif s[i] == ')':
                return ''.join(res), i+1
            else:
                res.append(s[i].upper() if (s[i].islower() ^ should_invert) else s[i].lower())
                i += 1
        return ''.join(res), i

    result, _ = helper(s, 0, True)
    return result
```

