        const len = str.length;
        for (let i = 0; i < len/2; i++) {
            if (str[i] !== str[len - 1 - i]) {
                return false;
            }
        }
        return true;
    }

    // add to the head
    addToHead(data) {
        if(this.isPalindrome(data)) {
            const newNode = new Node(data);
            if(this.head === null) {
                this.head = this.tail = newNode;
            } else {
                this.head.previous = newNode;
                newNode.next = this.head;
                this.head = newNode;
            }
        } else {
            console.log('Data is not palindromic');
        }
    }

    // add to the tail
    addToTail(data) {
        if(this.isPalindrome(data)) {
            const newNode = new Node(data);
            if(this.tail === null) {
                this.head = this.tail = newNode;
            } else {
                this.tail.next = newNode;
                newNode.previous = this.tail;
                this.tail = newNode;
            }
        } else {
            console.log('Data is not palindromic');
        }
    }
}

let dll = new DoublyLinkedList();
dll.addToHead('racecar'); //Adds to the head 
dll.addToTail('radar'); //Adds to the tail 
```
