```javascript

function reverseAlphaChars(str) {
  let arr = str.split(''), // convert string to array
      left = 0, 
      right = arr.length - 1;

  while (left < right) {
    if (!arr[left].match(/[a-z]/i)) { // if the left pointer is not an alphabet letter, move it one step right
      left++;
    } else if (!arr[right].match(/[a-z]/i)) { // if the right pointer is not an alphabet letter, move it one step left
      right--;
    } else { // if both are alphabet letters, swap them
      let temp = arr[left]; 
      arr[left] = arr[right];
      arr[right] = temp;
      left++;
      right--;
    }
  }
  return arr.join(''); // join array elements into a string
}

