Here is a class in Java that implements the standard deviation, median, and mode calculation methods:

```Java
import java.util.*;

public class MyStatClass {

    public double calculateSD(int numArray[]) {
        double sum = 0.0, standardDeviation = 0.0;
        int length = numArray.length;

        for(double num : numArray) {
            sum += num;
        }

        double mean = sum/length;

        for(double num: numArray) {
            standardDeviation += Math.pow(num - mean, 2);
        }

        return Math.sqrt(standardDeviation/length);
    }

    public double calculateMedian(int numArray[]) {
        Arrays.sort(numArray);

        int length = numArray.length;
        double median = 0;

        if (length % 2 == 0) {
            median = (numArray[(length - 1) / 2] + numArray[length / 2]) / 2.0;
        } else {
            median = numArray[length / 2];
        }

        return median;
    }

    public int calculateMode(int numArray[]) {
        HashMap<Integer, Integer> numCountMap = new HashMap<>();
        for(int val : numArray) {
            if(numCountMap.containsKey(val)) {
                numCountMap.replace(val, numCountMap.get(val) + 1);
            } else {
                numCountMap.put(val, 1);
            }
        }

        int maxCount = -1;
        int mode = -1;
        for(Map.Entry<Integer, Integer> entry : numCountMap.entrySet()) {
            if(entry.getValue() > maxCount) {
                maxCount = entry.getValue();
                mode = entry.getKey();
            }
        }

        return mode;
    }

    public static void main(String[] args) {
        MyStatClass sc = new MyStatClass();
        int[] numbers = {3, 5, 11, 19, 21, 23, 25, 29};

        System.out.printf("The standard deviation is %.2f\n", sc.calculateSD(numbers));
        System.out.printf("The median is %.2f\n", sc.calculateMedian(numbers));
        System.out.println("The mode is " + sc.calculateMode(numbers));
    }
}
```

