fn advanced_filter(strings: Vec<String>, prefix_suffix_inner_length: (String, String, String, usize)) -> Vec<String> {
    let (prefix, suffix, inner, length) = prefix_suffix_inner_length;
    let mut results = Vec::new(); // this will store our results

