using System.Linq;

public class Player
{
    public string Name { get; set; }
    public int Score { get; set; }
    public int Rank { get; set; }
}

public class RankingSystem
{
    private List<Player> players;

    public RankingSystem()
    {
        players = new List<Player>();
    }

    public void AddPlayer(string playerName, int playerScore)
    {
        if (playerScore < 1 || playerScore > 100)
            throw new Exception("Invalid score. Score must be between 1 and 100.");

        if (players.Any(p => p.Name == playerName))
            throw new Exception("Player with the same name already exists.");

        var player = new Player
        {
            Name = playerName,
            Score = playerScore
        };
        players.Add(player);
        UpdateRanks();
    }

    public int GetPlayerRank(string playerName)
    {
        var player = players.FirstOrDefault(p => p.Name == playerName);

        if (player == null)
            throw new Exception("Player does not exist.");

        return player.Rank;
    }

    private void UpdateRanks()
    {
        var rankedPlayers = players.OrderByDescending(p => p.Score).ThenBy(p => p.Name).ToList();

        for (int i = 0; i < rankedPlayers.Count; i++)
        {
            if (i > 0 && rankedPlayers[i].Score == rankedPlayers[i - 1].Score)
                rankedPlayers[i].Rank = rankedPlayers[i - 1].Rank;
            else
                rankedPlayers[i].Rank = i + 1;

            players.First(p => p.Name == rankedPlayers[i].Name).Rank = rankedPlayers[i].Rank;
        }
    }
}
