  - There is no list comprehension in C. We must use a loop to compute the sum.
  - How we generated a-z in C, using for-loop from 'a' to 'z'

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

int char_to_int[26];
char longestString[100];

int ends_with(const char *str, const char *suffix) {
    size_t lenstr = strlen(str);
    size_t lensuffix = strlen(suffix);
    if (lensuffix >  lenstr) return 0;
    return strncmp(str + lenstr - lensuffix, suffix, lensuffix) == 0;
}

int calculateTotalSum(char* s) {
    int totalSum = 0;
    for (int i = 0; i < strlen(s); i++) {
        totalSum += char_to_int[tolower(s[i]-'a')];
    }
    return totalSum;
}

void findLongestString(char* strings[], int numberOfStrings, char* prefixSuffix[]) {
    char* longestString = "";
    int totalSum = 0;

    // maps a-z to 1-26, useful for sum computation
    for (unsigned char ch = 'a', num = 1; ch <= 'z'; ch++, num++) {
        char_to_int[ch - 'a'] = num;
    }

    for (int i = 0; i < numberOfStrings; i++) {
        char *s = strings[i];

        if (strncasecmp(s, prefixSuffix[0], strlen(prefixSuffix[0])) == 0 
            && ends_with(s, prefixSuffix[1]) 
                && strlen(s) >= strlen(longestString)) {

            // Record the longest string and compute sum of its characters
            longestString = s;
            totalSum = calculateTotalSum(s);
        }
    }

    printf("Longest String: %s, Total Sum: %d\r\n", longestString, totalSum);
}

int main() {
    char* strings[] = {"apple", "program", "banana"};
    char* prefixSuffix[] = {"a", "e"};
    findLongestString(strings, sizeof(strings)/sizeof(strings[0]), prefixSuffix);
