    void insert(T data) {
        Node<T> *node = new Node<T>(data);
        node->next = head;
        head = node;
    }

    Node<T>* mergeAndRemoveDuplicates(Node<T> *head1, Node<T> *head2) {
        if (!head1) return head2;
        if (!head2) return head1;

        if(head1->data < head2->data) {
            head1->next = mergeAndRemoveDuplicates(head1->next, head2);
            return head1;
        }
        else if (head1->data > head2->data) {
            head2->next = mergeAndRemoveDuplicates(head1, head2->next);
            return head2;
        }
        else {
            head1->next = mergeAndRemoveDuplicates(head1->next, head2->next);
            return head1;
        }
    }
