Here is the Python code for the problem.

```python
class Node:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None
        self.edges = {}

class Solution:
    def diameterOfBinaryTree(self, root: Node) -> int:
        self.ans = 0
        def depth(node):
            if not node:
                return 0
            left = depth(node.left)
            right = depth(node.right)
            self.ans = max(self.ans, left + right + node.edges.get(node.left, 0) + 
                           node.edges.get(node.right, 0))
            return max(left + node.edges.get(node.left, 0), right + node.edges.get(node.right, 0))
        depth(root)
        return self.ans

# Test cases
