    edges = [(1,2,3), (1,3,2), (2,4,1), (2,5,2)]
    nodes = {i: Node(i) for i in range(1, 6)}
    for u, v, w in edges:
        nodes[u].edges[nodes[v]] = w
        if nodes[u].left is None:
            nodes[u].left = nodes[v]
        else:
            nodes[u].right = nodes[v]
    s = Solution()
    print(s.diameterOfBinaryTree(nodes[1]))  # Expected output 6

    edges = [(1,2,1)]
    nodes = {i: Node(i) for i in range(1, 3)}
    for u, v, w in edges:
        nodes[u].edges[nodes[v]] = w
