    // Validate if the prism is valid
    if ((sides[0] + sides[1] <= sides[2]) || h <= 0) {
        return -1.0;
    }

    // Calculate semi-perimeter
    double p = (a + b + c) / 2.0;

    // Calculate base area using Heron's formula
    double base_area = sqrt(p * (p - a) * (p - b) * (p - c));

    // Calculate and return volume rounded to 2 decimal places
    double volume = base_area * h;
    return round(volume * 100.0) / 100.0;
}
