    private static void bubbleSort(int[] arr) throws Exception {
        int n = arr.length;
        if(n == 0) throw new Exception("Array has no elements");

        for (int i = 0; i < n-1; i++) {
            for (int j = 0; j < n-i-1; j++) {
                if (arr[j] > arr[j+1]) {
