```java

public class SortArray {
    public static void main(String[] args) {
        int[] arr = {12, 6, 8, 10};
        bubbleSort(arr);

        System.out.println("Sorted array is: ");
        for(int i=0;i<arr.length;i++)
            System.out.print(arr[i] + " ");
    }

    static void bubbleSort(int[] arr) {
        int n = arr.length;
        int temp;

        for(int i=0; i < n; i++){
            for(int j=1; j < (n-i); j++){
                if(arr[j-1] > arr[j]){
                    //swap elements
                    temp = arr[j-1];
                    arr[j-1] = arr[j];
                    arr[j] = temp;
                }
            }
        }
    }
}
```

