def closest_prime_integer(value):
    try:
        value = float(value)
    except ValueError:
        return "Error: Invalid input."

    if value > 0:
        rounded_value = int(value) + int(value%1 >= 0.5)
    elif value < 0:
        rounded_value = int(value) - int(abs(value)%1 >= 0.5)
    else:
        rounded_value = 0

    if is_prime(rounded_value):
        return rounded_value
    else:
