function isPrime($num) {
    /* If number is less than 2, it's not a prime */
    if($num < 2) {
        return false;
    }

    /* If number is 2, it's a prime */
    if($num == 2) {
        return true;
    }

    /* If number is divided evenly by 2, it's not a prime */
    if($num % 2 == 0) {
        return false;
    }

    /* Checking from 3 to the square root of the number */
    for($i = 3; $i <= sqrt($num); $i += 2) {
        if($num % $i == 0) {
            return false;
        }
    }

    /* If no factors found, it's a prime */
    return true;
}

function primeSum($array) {
    $primeSum = 0;

    /* Checking each item in the array */
    foreach($array as $item) {
        /* If it's an array, use recursion */
        if(is_array($item)) {
            $primeSum += primeSum($item);
        } else {
            /* If it's a prime number, add it to the sum */
            if(isPrime($item)) {
                $primeSum += $item;
            }
        }
    }

    return $primeSum;
}
