class Main {
    public static void main(String[] args) {
        Map<String, String> map = new HashMap<>();
        map.put("1", "hello");
        map.put("2", "world");
        map.put("3", "goodbye");

        String source = "helloo";
        String bestMatch = matchString(source, map);

