    }

    public static String matchString(String source, Map<String, String> map) {
        FuzzyScore fuzzyScore = new FuzzyScore(Locale.getDefault());
        int maxScore = 0;
        String bestMatch = "";

        for (Map.Entry<String, String> entry : map.entrySet()) {
            int score = fuzzyScore.fuzzyScore(source, entry.getValue());
            if (score > maxScore) {
                maxScore = score;
                bestMatch = entry.getValue();
            }
        }

        return bestMatch;
    }
}
