from typing import List, Tuple, Dict


def factorize(n: int) -> Tuple[List[int], Dict[int, int]]:
    factors = []
    counts = {}

    # Find the factors of 2
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    if 2 in factors:
        counts[2] = factors.count(2)

    # Find odd prime factors
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i
        if i in factors:
            counts[i] = factors.count(i)

    # Check if the remaining n is a prime factor
    if n > 2:
        factors.append(n)
        counts[n] = 1

    return factors, counts


