```Csharp
using System;
using System.Collections.Generic;

public class Parentheses
{
    /*
     * This static method separate_paren_groups takes an input string and separates it into groups of balanced parentheses.
     * The return type is List<string>, each element of which is a group of balanced parentheses.
     */
    public static List<string> separate_paren_groups(string paren_string)
    {
        paren_string = paren_string.Replace(" ", "");  // first, remove all spaces from the string

        List<string> parentheses_groups = new List<string>();  // this list will hold the groups of balanced parentheses
        Stack<char> stack = new Stack<char>();  // this stack will help to check the balance of the parentheses
        int start = 0;  // this is the starting index of each group of balanced parentheses

        /*
         * In the following loop, it goes through each character of the string.
         * If an opening bracket is found, it's pushed onto the stack. If the stack was empty (which tells us this is the start of a new group), the index is stored.
         * If a closing bracket is found, it's popped from the stack. If that makes the stack empty, it means the parentheses were balanced and a group is found.
         * So, that group is then extracted from the string and added to the list.
         */
        for (int i = 0; i < paren_string.Length; i++)
        {
            if (paren_string[i] == '(')
            {
                if (stack.Count == 0) 
                {
                    start = i;
                }
                stack.Push(paren_string[i]);
            }
            else if (paren_string[i] == ')')
            {
                stack.Pop();
                if (stack.Count == 0)
                {
                    parentheses_groups.Add(paren_string.Substring(start, i - start + 1));
                }
            }
        }

        return parentheses_groups;  // finally, return the list of groups of balanced parentheses
    }
}
```
The code above will create a list of strings where each string represents a separate valid set of parentheses from the input `paren_string`. It uses a stack to track open and closing parentheses and whenever all opened parentheses are closed, it creates a string from that valid set of parentheses and adds it to the result list.

