#include <stdio.h>
#define SIZE 5
int top = -1;
int stack[SIZE];

void push(int value){
    if(top >= SIZE - 1){
        printf("Stack is full!");
    }
    else{
        top++;
        stack[top] = value;
        printf("Pushed element: %d\n",value);
    }
}

void pop(){
    if(top <= -1){
        printf("Stack is empty!");
    }
    else{
        printf("Popped element: %d\n", stack[top]);
        top--;
    }
}

void peek(){
    if(top == -1){
        printf("Stack is empty!");
    }
    else{
        printf("Peeked element: %d\n",stack[top]);
    }
}

void isEmpty(){
    if(top == -1){
        printf("Stack is empty!");
    }
    else{
        printf("Stack is not empty!");
    }
}

int main(){
