    push(2);
    push(3);
    push(4);
    push(5);
    push(6);  //stack is full

    peek();   //show the top item

    pop();
    pop();
    pop();
    pop();
    pop();
    pop();   //stack is empty

    isEmpty();      //check stack is empty

    return 0;
}
```

