import Foundation

func doAlgebra(operators: [String], operands: [Double], roundOff: Bool) throws -> Double {
    // Mapping the arithmetic operators to their respective functions
    var operatorMap: [String: (Double, Double) -> Double] = [
        "+": { $0 + $1 },
        "-": { $0 - $1 },
        "*": { $0 * $1 },
        "//": { floor($0 / $1) },
        "**": { pow($0, $1) }
    ]

    // Error handling
    if operands.count - operators.count != 1 {
        throw NSError(domain:"", code:400, userInfo:[ NSLocalizedDescriptionKey: "The number of operators must be exactly one less than the number of operands."])
    }

    // Initializing the result to the first operand
    var result = operands[0]

    // Going through each operator
    for idx in 0..<operators.count {
        // Updating the result based on the current operator and the next operand
        if let operation = operatorMap[operators[idx]] {
            result = operation(result, operands[idx + 1])
        } else {
            throw NSError(domain:"", code:400, userInfo:[ NSLocalizedDescriptionKey: "Invalid operator"])
        }
    }

    // Rounding off the result if needed
    if roundOff {
        result = round(result)
    }

    return result
}
