public class Solution {

    public List<Double> findClosestElements(List<Double> inputList) {
        Collections.sort(inputList);

        int minIndex = 0;
        double minDifference = Double.MAX_VALUE;
        for (int i = 0; i < inputList.size() - 1; i++) {
            double difference = inputList.get(i+1) - inputList.get(i);
            if (difference < minDifference) {
                minDifference = difference;
                minIndex = i;
            }
        }

        return new ArrayList<>(Arrays.asList(inputList.get(minIndex), inputList.get(minIndex + 1)));
    }
}
