def advanced_pascal_with_offset(n: int, offset: int):
    if n < 0 or offset < 0:
        raise ValueError("Cannot have negative index or offset.")

    calculated_values = dict()

    def pascal_modified(n):
        if n < offset:
            return 0

        # check if we calculated this before
        if n in calculated_values.keys():
