This is an example of how you could implement the requested feature in Rust.

```rust
// Define the Record
#[derive(Debug)]
pub struct Record {
    pub name: String,
    pub value: i32
}

// Implement methods for the Record
impl Record {

    // Comparison method for two Records.
    // Returns true if the first record comes before the second in the ordering, false otherwise.
    fn comes_before(&self, other: &Record) -> bool {
        self.value > other.value || (self.value == other.value && self.name < other.name)
    }
}

// Bubble sort
fn bubble_sort(records: &mut Vec<Record>) {
    let len = records.len();
    // Iterating over each index in vec
    for i in 0..len {
        // Last i elements are already sorted, so we iterate over vec until len - i
        for j in 0..(len - i - 1) {
            if !records[j].comes_before(&records[j + 1]) {
                // Swapping if element at j is not in right order with respect to the next element
                records.swap(j, j + 1);
            }
        }
    }
}

fn main() {
    // Create a vector of records
    let mut records = vec![
        Record { name: String::from("Alice"), value: 2 },
        Record { name: String::from("Bob"), value: 3 },
        Record { name: String::from("Charlie"), value: 1 },
        Record { name: String::from("Dante"), value: 3 },
    ];

    // Sort the records
