from typing import List
from collections import defaultdict

def how_many_times(string: str, substring: str) -> int:
    """
    Function to find how many times a given substring can be found
    in the original string, using Trie data structure.
    """
    class TrieNode:
        def __init__(self):
            self.children = defaultdict()
            self.endOfString = False

    def insert(root, string):
        node = root
        for ch in string:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.endOfString = True

    root = TrieNode()
    for i in range(len(string)):
        insert(root, string[i:])

    def search(root, substring):
        node = root
        for ch in substring:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return True if node and node.endOfString else False

    count = 0
    for i in range(len(string)):
        if search(root, string[i:i+len(substring)]):
            count += 1

    return count


def count_subsequences(string: str, substring: str) -> int:
    """
    Function to count non-overlapping subsequences of a given substring
    in the original string, using dynamic programming.
    """
    n = len(string)
    m = len(substring)
    lookup = [[0]*(m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        lookup[i][0] = 1
    for i in range(1, m + 1):
        lookup[0][i] = 0
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if string[i - 1] == substring[j - 1]:
                lookup[i][j] = lookup[i - 1][j - 1] + lookup[i - 1][j]
            else:
                lookup[i][j] = lookup[i - 1][j]
    return lookup[n][m]


def find_substrings_with_k_distinct_chars(string: str, k: int) -> List[str]:
    """
    Function to find all substrings of a given string with exactly k
    distinct characters and a length of at least k+1,
    """
