    var str = document.getElementById('input').value;
    var cleaned = str.replace(/[^a-zA-Z0-9]+/g, "").toLowerCase();
    if (cleaned === cleaned.split('').reverse().join('')) {
        document.getElementById('result').innerHTML = str + ' is a Palindrome';
