def extract_data(str):
    # splitting the string  
    str = str.replace(',', ' ').replace(';', ' ').split()
    # if str is a single word and consists solely of upper-case alphabetical characters.
    if len(str) == 1 and str[0].isupper():
        return sum(1 for ch in str[0] if (ord(ch)-ord('A'))%2==0)

    # creating dictionary 
    count = {'upper': 0, 'lower': 0, 'digits': 0, 'others': 0}
    for s in "".join(str):
        # counting uppercase letters 
        if s.isupper():
            count['upper'] += 1
        # counting lowercase letters
        elif s.islower():
            count['lower'] += 1
        # counting digits
