```python
from typing import List, Tuple, Dict, Union

def parse_paren_groups(paren_string: str, handle_errors: bool) -> Tuple[List[str], Dict[str, Union[int, str]]]:
    paren_string = paren_string.replace(' ', '')
    stack = []
    result = []
    parsed = []
    data_stats = {'Total groups separated': 0, 'Imbalanced groups': 0, 'Longest group length': 0}

    for i in range(len(paren_string)):
        if paren_string[i] == '(':
            stack.append(i)
        elif paren_string[i] == ')':
            # handle errors if we encounter an closing bracket without a matching opening bracket
            if not stack:
                if handle_errors:
                    data_stats['Imbalanced groups'] += 1
                    continue
                else:
                    raise ValueError("Imbalanced parentheses at index {}".format(i))
            else:
                start = stack.pop()
                if not stack:  # if current group is not nested in another group
                    grouped_string = paren_string[start:i+1]
                    parsed.append(grouped_string)
                    data_stats['Total groups separated'] += 1
                    data_stats['Longest group length'] = max(data_stats['Longest group length'], len(grouped_string))

    # handle errors if we have an opening bracket without a matching closing bracket
    if stack:
        if handle_errors:
            data_stats['Imbalanced groups'] += len(stack)
        else:
            raise ValueError("Imbalanced parentheses at index {}".format(stack[0]))

    return parsed, data_stats
