        if (s.length() != t.length()) {
            return false;
        }

        int[] letters = new int[128];

        for (int i = 0; i < s.length(); i++) {
            letters[s.charAt(i)]++;
            letters[t.charAt(i)]--;
        }

        for (int i = 0; i < letters.length; i++) {
