def sieve_of_eratosthenes(n):
    primes = [True for _ in range(n+1)]
    p = 2
    while p**2 <= n:
        if primes[p] is True:
            for i in range(p**2, n+1, p):
                primes[i] = False
        p += 1
    primes_only = []
    for p in range(2, n):
        if primes[p]:
            primes_only.append(p)
    return primes_only

