Here is a simple function you can use to check if two strings are anagrams of each other in C++. This function uses an unordered map to keep track of character counts, and iterates through both strings to increment and decrement these counts. After all characters are processed, if all character counts in the unordered map are 0, then the strings are anagrams of each other.

For handling non-alphanumeric characters, this code simply ignores them and does not include them in the character count. It uses the isalnum() function from the C++ Standard Library to check if a character is alphanumeric, and only processes the character further if it is alphanumeric.

```c++
#include <iostream>
#include <unordered_map>
#include <algorithm>
#include <cctype>

bool areAnagrams(std::string str1, std::string str2) {
    std::unordered_map<char, int> count;

    // Process characters from first string
    for (char c : str1) {
        // Convert all characters to lower case & calculate char freq in 1st string
        if (std::isalnum(c)) {
            c = std::tolower(c);
            count[c]++;
        }
    }

    // Process characters from second string
    for (char c : str2) {
        // Convert all characters to lower case & decrement char freq in 2nd string
        if (std::isalnum(c)) {
            c = std::tolower(c); 
            count[c]--;
        }
    }

    // Check if character counts are all 0
    for (auto &pair : count) {
        if (pair.second != 0) {
            return false;
        }
    }

    return true;
}

int main() {
    std::string str1 = "anagram";
    std::string str2 = "nagaram";
    std::cout << (areAnagrams(str1, str2) ? "Anagrams" : "Not Anagrams") << std::endl;

