func median(l []int) float64 {
	n := len(l)
	rand.Seed(time.Now().UTC().UnixNano()) // Seed for generating random numbers

	if n%2 == 1 {  // If there's an odd number of elements => one single median
		return float64(quickselect(l, 0, n-1, n/2)) 
	} else {  // Even number of elements => average of middle two
		return 0.5 * float64(quickselect(l, 0, n-1, n/2-1)+quickselect(l, 0, n-1, n/2)) 
	}
}

func quickselect(l []int, start int, end int, k int) int {
	// Returns the kth smallest element in the list within start..end
	if start == end { // If list contains only one element
		return l[start] 
	}

	// Choose a random pivot
	pivotIndex := rand.Intn(end-start+1) + start 

	// The pivot is in its final sorted position
	pivotIndex = partition(l, start, end, pivotIndex)

	if k == pivotIndex {
		return l[k]
	} else if k < pivotIndex {
		return quickselect(l, start, pivotIndex-1, k) 
	} else {  // k > pivotIndex   
		return quickselect(l, pivotIndex+1, end, k) 
	}
}

func partition(l []int, start int, end int, pivotIndex int) int {
	// Moves the pivot element to end
	l[pivotIndex], l[end] = l[end], l[pivotIndex]  

	// Puts elements less than pivot on left of pivot
	storeIndex := start
	for i := start; i < end; i++ {
		if l[i] < l[end] {
			l[storeIndex], l[i] = l[i], l[storeIndex]
			storeIndex++
		}
	}  

	// Moves pivot to its final place
	l[end], l[storeIndex] = l[storeIndex], l[end]  

	return storeIndex
}
