def longest_common_subsequence(X , Y):
  m = len(X)
  j = len(Y) 
  dp = [[None]*(j+1) for i in range(m+1)]
  for i in range(m+1):
    for j in range(j+1):
      if i == 0 or j== 0:
        dp[i][j] = 0
      elif X[i-1] == Y[j-1]:
        dp[i][j] = dp[i-1][j-1] + 1
      else:
        dp[i][j] = max(dp[i-1][j] , dp[i][j-1])
  return dp[m][n]

def shortest_unique_subsequence(strs):
  subseqs = {}
  for s in strs:
    for i in range(len(s)):
      for j in range(i+1, len(s)+1):
        subseq = s[i:j]
        subseqs[subseq] = subseqs.get(subseq, 0) + 1
  shortest_unique_subseq = [s for s, count in subseqs.items() if count == 1]
  return min(shortest_unique_subseq, key=len)

def solve(input1, input2):
  lcs = longest_common_subsequence(input1, input2)
  sus1 = shortest_unique_subsequence(input1)
  sus2 = shortest_unique_subsequence(input2)
  return lcs, sus1, sus2

