#include <libssh2.h>

void send_file_scp(
    char* hostname,
    char* username,
    char* password,
    char* local_file_path,
    char* remote_file_path)
{
    LIBSSH2_SESSION* session = libssh2_session_init();
    int rc = libssh2_session_startup(session, sock);
    if (rc == LIBSSH2_ERROR_EAGAIN)
    {
        // wait for it to complete
    }
    else if (rc)
    {
        fprintf(stderr, "Failure establishing SSH session: %d\n", rc);
        return;
    }

    libssh2_userauth_password(session, username, password);

    struct stat fileinfo;
    FILE* local = fopen(local_file_path, "rb");
    stat(local_file_path, &fileinfo);
    LIBSSH2_CHANNEL* channel = libssh2_scp_send(session, remote_file_path, fileinfo.st_mode & 0777, (unsigned long)fileinfo.st_size);

    char mem[1024*24];
    size_t nread;
    char* ptr;
    do
    {
        nread = fread(mem, 1, sizeof(mem), local);
        if (nread <= 0)
        {
            /* end of file */
            break;
        }
        ptr = mem;

        do
        {
            /* write data in a loop until we block */
            rc = libssh2_channel_write(channel, ptr, nread);

            if (rc < 0)
            {
                fprintf(stderr, "ERROR %d\n", rc);
                break;
            }
            else
            {
                /* rc indicates how many bytes were written this time */
                ptr += rc;
                nread -= rc;
            }
        }
        while (nread);

    } while (!0);

    fclose(local);
    libssh2_channel_free(channel);
    channel = NULL;

    libssh2_session_disconnect(session, "Bye bye, thank you");
    libssh2_session_free(session);
}
```

