The AWS SDK for Swift is called `aws-sdk-swift` and is distributed as a Swift package. However, it provides asynchronous API only since its 5.0 release. The interaction with S3 is done in Swift using a different style compared to Python, making use of chaining of promises using the `EventLoopFuture`. 

Also, `aws-sdk-swift` does not provide the specific Exceptions that Boto3 does. Instead it throws an `AWSErrorType`.

Here is a rough conversion to Swift equivalent:

```swift
import AWSS3
import NIO // NIO is used for interacting with the EventLoopFuture

let s3 = S3(region: .uswest2)

func uploadToS3(fileURL: URL, bucket: String, key: String = "") {
    let eventLoop: EventLoop = s3.client.eventLoopGroup.next()
    let request = S3.PutObjectRequest(body: .byteBuffer(.init()), bucket: bucket, key: key)
    let responseFuture = s3.putObject(request, on: eventLoop)

    responseFuture.whenSuccess { response in
        print("Success! \(fileURL) uploaded to \(bucket)")
    }
    responseFuture.whenFailure { error in
        print(error.localizedDescription)
    }
}

func downloadFromS3(fileURL: URL, bucket: String, key: String = "") {
    let eventLoop: EventLoop = s3.client.eventLoopGroup.next()
    let request = S3.GetObjectRequest(bucket: bucket, key: key)
    let futureResult = s3.getObject(request, on: eventLoop)

    futureResult.whenSuccess { result in
        print("Success! \(fileURL) downloaded from \(bucket)")
    }
    futureResult.whenFailure { error in
        print(error.localizedDescription)
    }
}

func listObjectsInS3(bucket: String) {
    let eventLoop: EventLoop = s3.client.eventLoopGroup.next()
    let request = S3.ListObjectsV2Request(bucket: bucket)
    let futureResult = s3.listObjectsV2(request, on: eventLoop)

    futureResult.whenSuccess { result in
        for content in result.contents ?? [] {
            print(content.key ?? "")
        }
    }
    futureResult.whenFailure { error in
        print(error.localizedDescription)
    }
}

func deleteFromS3(bucket: String, key: String) {
    let eventLoop: EventLoop = s3.client.eventLoopGroup.next()
    let request = S3.DeleteObjectRequest(bucket: bucket, key: key)
    let futureResult = s3.deleteObject(request, on: eventLoop)

    futureResult.whenSuccess { result in
        print("Success! \(key) deleted from \(bucket)")
    }
    futureResult.whenFailure { error in
        print(error.localizedDescription)
    }
}
```

Please note that creating an instance of Service (like `S3` above) might require AWS credentials which can be set in your environment variables as mentioned in [aws-sdk-swift](https://github.com/soto-project/soto) documentation.

